function Tab:AddToggle(text, default, callback)
  local c = card(self, 42)
  local lab = make("TextLabel", {
    Size = UDim2.new(1, -80, 1, 0),
    Position = UDim2.fromOffset(14, 0),
    BackgroundTransparency = 1,
    Text = text,
    Font = Enum.Font.GothamMedium,
    TextSize = 13,
    TextColor3 = T.Text,
    TextXAlignment = Enum.TextXAlignment.Left,
    Parent = c,
  })
  local sw = make("Frame", {
    Size = UDim2.fromOffset(44, 24),
    AnchorPoint = Vector2.new(1, 0.5),
    Position = UDim2.new(1, -14, 0.5, 0),
    BackgroundColor3 = Color3.fromRGB(30, 20, 56),
    BackgroundTransparency = 0.2,
    BorderSizePixel = 0,
    Parent = c,
  })
  corner(sw, 12)
  local swStroke = stroke(sw, T.White, 1, 0.8)
  local fill = make("Frame", {
    Size = UDim2.fromScale(1, 1),
    BackgroundColor3 = T.White,
    BackgroundTransparency = 1,
    BorderSizePixel = 0,
    Parent = sw,
  })
  corner(fill, 12)
  grad(fill, ColorSequence.new(T.Accent2, T.Accent3), nil, 0)
  local knob = make("Frame", {
    Size = UDim2.fromOffset(18, 18),
    AnchorPoint = Vector2.new(0, 0.5),
    Position = UDim2.new(0, 3, 0.5, 0),
    BackgroundColor3 = T.White,
    BorderSizePixel = 0,
    Parent = sw,
  })
  corner(knob, 9)
  local hit = make("TextButton", {
    Size = UDim2.fromScale(1, 1),
    BackgroundTransparency = 1,
    Text = "",
    Parent = c,
  })
  local obj = {Value = default and true or false, Card = c, Label = lab}
  local function render(fire)
    tween(fill, 0.22, {BackgroundTransparency = obj.Value and 0.05 or 1})
    tween(swStroke, 0.22, {Transparency = obj.Value and 0.3 or 0.8, Color = obj.Value and T.Accent2 or T.White})
    tween(knob, 0.22, {Position = obj.Value and UDim2.new(1, -21, 0.5, 0) or UDim2.new(0, 3, 0.5, 0)})
    if fire and callback then
      task.spawn(callback, obj.Value)
    end
  end
  function obj:Set(v)
    obj.Value = v and true or false
    render(true)
  end
  hit.MouseButton1Click:Connect(function()
    obj.Value = not obj.Value
    render(true)
  end)
  render(false)
  Shin.Toggles = Shin.Toggles or {}
  table.insert(Shin.Toggles, {Tab = self, Text = text, Obj = obj})
  return obj
end

function Tab:AddSlider(text, min, max, default, callback, step)
  local c = card(self, 58)
  local lab = make("TextLabel", {
    Size = UDim2.new(1, -90, 0, 24),
    Position = UDim2.fromOffset(14, 5),
    BackgroundTransparency = 1,
    Text = text,
    Font = Enum.Font.GothamMedium,
    TextSize = 13,
    TextColor3 = T.Text,
    TextXAlignment = Enum.TextXAlignment.Left,
    Parent = c,
  })
  local chip = make("Frame", {
    Size = UDim2.fromOffset(46, 20),
    AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -12, 0, 7),
    BackgroundColor3 = T.Accent,
    BackgroundTransparency = 0.55,
    BorderSizePixel = 0,
    Parent = c,
  })
  corner(chip, 10)
  stroke(chip, T.Accent2, 1, 0.6)
  local val = make("TextLabel", {
    Size = UDim2.fromScale(1, 1),
    BackgroundTransparency = 1,
    Text = "",
    Font = Enum.Font.GothamBold,
    TextSize = 11,
    TextColor3 = T.White,
    Parent = chip,
  })
  local hit = make("TextButton", {
    Size = UDim2.new(1, -28, 0, 24),
    Position = UDim2.fromOffset(14, 30),
    BackgroundTransparency = 1,
    Text = "",
    Parent = c,
  })
  local track = make("Frame", {
    Size = UDim2.new(1, 0, 0, 6),
    AnchorPoint = Vector2.new(0, 0.5),
    Position = UDim2.fromScale(0, 0.5),
    BackgroundColor3 = T.White,
    BackgroundTransparency = 0.85,
    BorderSizePixel = 0,
    Parent = hit,
  })
  corner(track, 3)
  local fill = make("Frame", {
    Size = UDim2.fromScale(0, 1),
    BackgroundColor3 = T.White,
    BorderSizePixel = 0,
    Parent = track,
  })
  corner(fill, 3)
  grad(fill, ColorSequence.new(T.Accent3, T.Accent2), nil, 0)
  local knob = make("Frame", {
    Size = UDim2.fromOffset(16, 16),
    AnchorPoint = Vector2.new(0.5, 0.5),
    Position = UDim2.fromScale(0, 0.5),
    BackgroundColor3 = T.White,
    BorderSizePixel = 0,
    Parent = track,
  })
  corner(knob, 8)
  stroke(knob, T.Accent, 2, 0.2)

  local obj = {Value = math.clamp(default or min, min, max), Card = c, Label = lab}
  local function set(v, fire)
    local st = step or 1
    v = math.clamp(math.floor(v / st + 0.5) * st, min, max)
    v = tonumber(string.format("%.6g", v))
    obj.Value = v
    local a = (v - min) / (max - min)
    fill.Size = UDim2.fromScale(a, 1)
    knob.Position = UDim2.fromScale(a, 0.5)
    val.Text = tostring(v)
    if fire and callback then
      task.spawn(callback, v)
    end
  end
  function obj:Set(v)
    set(v, true)
  end
  local function fromX(x)
    local a = math.clamp((x - track.AbsolutePosition.X) / math.max(1, track.AbsoluteSize.X), 0, 1)
    set(min + (max - min) * a, true)
  end

  local dragging = false
  hit.InputBegan:Connect(function(input)
    local t = input.UserInputType
    if t == Enum.UserInputType.MouseButton1 or t == Enum.UserInputType.Touch then
      dragging = true
      self.Page.ScrollingEnabled = false
      tween(knob, 0.15, {Size = UDim2.fromOffset(20, 20)})
      fromX(input.Position.X)
    end
  end)
  table.insert(self.Window.Conns, UIS.InputChanged:Connect(function(input)
    if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
      fromX(input.Position.X)
    end
  end))
  table.insert(self.Window.Conns, UIS.InputEnded:Connect(function(input)
    if dragging and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
      dragging = false
      self.Page.ScrollingEnabled = true
      tween(knob, 0.15, {Size = UDim2.fromOffset(16, 16)})
    end
  end))
  set(obj.Value, false)
  return obj
end

local function esc(s)
  s = tostring(s == nil and "" or s)
  s = s:gsub("&", "&amp;")
  s = s:gsub("<", "&lt;")
  s = s:gsub(">", "&gt;")
  return s
end

local function richText(title, desc)
  if desc and desc ~= "" then
    return esc(title) .. '\n<font size="10" color="rgb(196,182,232)">' .. esc(desc) .. "</font>"
  end
  return esc(title)
end

local function applyText(o, title, desc)
  local has = desc and desc ~= ""
  o.Label.RichText = true
  o.Label.TextWrapped = true
  o.Label.Text = richText(title, desc)
  o.Card.Size = UDim2.new(1, 0, 0, has and 56 or 42)
end

local function normKey(s)
  s = tostring(s or ""):lower()
  s = s:gsub("[^%w]", "")
  return s
end

local function meta(tab, frame, kind, title, extra)
  tab.Meta = tab.Meta or {}
  local m = extra or {}
  m.kind = kind
  m.title = tostring(title or "")
  tab.Meta[frame] = m
  return m
end

local function isDown(i)
  local t = i.UserInputType
  return t == Enum.UserInputType.MouseButton1 or t == Enum.UserInputType.Touch
end

local function styleHeader(tab, f, m)
  if m.styled then
    return
  end
  m.styled = true
  m.label.TextColor3 = T.Accent2
  m.label.Font = Enum.Font.GothamBold
  f.BackgroundTransparency = 0.78
  local start
  f.InputBegan:Connect(function(i)
    if isDown(i) then
      start = i.Position
    end
  end)
  f.InputEnded:Connect(function(i)
    if start and isDown(i) then
      local d = (i.Position - start).Magnitude
      start = nil
      if d < 10 then
        tab.Collapsed[f] = not tab.Collapsed[f]
        tab:RefreshGroups()
      end
    end
  end)
end

function Tab:RefreshGroups()
  local q = self.Query or ""
  local function match(f)
    local m = self.Meta[f]
    return m ~= nil and m.title ~= nil and string.find(string.lower(m.title), q, 1, true) ~= nil
  end
  for _, f in ipairs(self.Lead or {}) do
    f.Visible = q == "" or match(f)
  end
  for _, g in ipairs(self.Groups or {}) do
    local collapsed = self.Collapsed[g.Header]
    local any = false
    for _, f in ipairs(g.Items) do
      local show
      if q == "" then
        show = not collapsed
      else
        show = match(f)
      end
      f.Visible = show
      any = any or show
    end
    local m = self.Meta[g.Header]
    g.Header.Visible = q == "" or any or match(g.Header)
    m.label.Text = ((collapsed and q == "") and "+  " or "-  ") .. m.base
  end
end

function Tab:BuildGroups()
  local items = {}
  for _, f in ipairs(self.Items or {}) do
    if f.Parent then
      items[#items + 1] = f
    end
  end
  self.Items = items
  self.Meta = self.Meta or {}
  self.Collapsed = self.Collapsed or {}
  if not self.SearchBox then
    local sf = make("Frame", {
      Size = UDim2.new(1, 0, 0, 34),
      BackgroundColor3 = T.White,
      BackgroundTransparency = 0.9,
      BorderSizePixel = 0,
      LayoutOrder = 0,
      Parent = self.Page,
    })
    corner(sf, 10)
    stroke(sf, T.Accent2, 1, 0.7)
    local box = make("TextBox", {
      Size = UDim2.new(1, -20, 1, 0),
      Position = UDim2.fromOffset(10, 0),
      BackgroundTransparency = 1,
      Text = "",
      PlaceholderText = "Search...",
      PlaceholderColor3 = T.Sub,
      Font = Enum.Font.GothamMedium,
      TextSize = 12,
      TextColor3 = T.Text,
      TextXAlignment = Enum.TextXAlignment.Left,
      ClearTextOnFocus = false,
      Parent = sf,
    })
    box:GetPropertyChangedSignal("Text"):Connect(function()
      self.Query = string.lower(box.Text)
      self:RefreshGroups()
    end)
    self.SearchBox = box
  end
  local lead, groups, cur = {}, {}, nil
  for _, f in ipairs(items) do
    local m = self.Meta[f]
    if m and m.kind == "para" and m.obj and not m.obj.Touched and not string.find(m.obj:GetDesc(), "%S") then
      m.kind = "header"
      m.label = m.obj.TitleLabel
      m.base = m.obj.TitleLabel.Text
      m.obj.DescLabel.Visible = false
      m.obj.IsHeader = true
    end
    if m and m.kind == "header" then
      styleHeader(self, f, m)
      if self.Collapsed[f] == nil then
        self.Collapsed[f] = #groups >= 1
      end
      cur = {Header = f, Items = {}}
      groups[#groups + 1] = cur
    elseif cur then
      cur.Items[#cur.Items + 1] = f
    else
      lead[#lead + 1] = f
    end
  end
  self.Lead, self.Groups = lead, groups
  self:RefreshGroups()
end

function Window:SortTabs(order, select)
  local rank = {}
  for i, n in ipairs(order) do
    rank[n] = i
  end
  for i, t in ipairs(self.Tabs) do
    t.Btn.LayoutOrder = rank[normKey(t.Name)] or (100 + i)
  end
  if select then
    local best
    for _, t in ipairs(self.Tabs) do
      if not best or t.Btn.LayoutOrder < best.Btn.LayoutOrder then
        best = t
      end
    end
    if best then
      best:Select()
    end
  end
end

function Window:Finalize(order, first)
  self:SortTabs(order, first)
  for _, t in ipairs(self.Tabs) do
    t:BuildGroups()
  end
end

function Tab:AddParagraph(title, desc)
  local c = card(self, 0)
  for _, ch in ipairs(c:GetChildren()) do
    if ch:IsA("Frame") then
      ch:Destroy()
    end
  end
  c.AutomaticSize = Enum.AutomaticSize.Y
  c.Size = UDim2.new(1, 0, 0, 0)
  make("UIListLayout", {Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder, Parent = c})
  make("UIPadding", {
    PaddingTop = UDim.new(0, 8),
    PaddingBottom = UDim.new(0, 8),
    PaddingLeft = UDim.new(0, 14),
    PaddingRight = UDim.new(0, 14),
    Parent = c,
  })
  local tl = make("TextLabel", {
    Size = UDim2.new(1, 0, 0, 0),
    AutomaticSize = Enum.AutomaticSize.Y,
    BackgroundTransparency = 1,
    Text = tostring(title or ""),
    Font = Enum.Font.GothamBold,
    TextSize = 13,
    TextColor3 = T.Text,
    TextWrapped = true,
    TextXAlignment = Enum.TextXAlignment.Left,
    LayoutOrder = 1,
    Parent = c,
  })
  local dl = make("TextLabel", {
    Size = UDim2.new(1, 0, 0, 0),
    AutomaticSize = Enum.AutomaticSize.Y,
    BackgroundTransparency = 1,
    Text = tostring(desc or ""),
    Font = Enum.Font.GothamMedium,
    TextSize = 12,
    TextColor3 = T.Sub,
    TextWrapped = true,
    TextXAlignment = Enum.TextXAlignment.Left,
    Visible = desc ~= nil and desc ~= "",
    LayoutOrder = 2,
    Parent = c,
  })
  local obj = {Card = c, TitleLabel = tl, DescLabel = dl}
  function obj:GetDesc()
    return dl.Text
  end
  function obj:SetDesc(d)
    d = d == nil and "" or tostring(d)
    if string.find(d, "%S") then
      obj.Touched = true
    end
    if dl.Text == d then
      return
    end
    dl.Text = d
    dl.Visible = d ~= "" and not obj.IsHeader
  end
  obj.SetContent = obj.SetDesc
  obj.Set = obj.SetDesc
  function obj:SetTitle(t)
    t = tostring(t or "")
    if tl.Text ~= t then
      tl.Text = t
    end
  end
  function obj:Destroy()
    c:Destroy()
  end
  return obj
end

function Tab:AddDropdown(text, options, default, callback, multi)
  local c = card(self, 42)
  local lab = make("TextLabel", {
    Size = UDim2.new(0.5, -14, 0, 42),
    Position = UDim2.fromOffset(14, 0),
    BackgroundTransparency = 1,
    Text = tostring(text or ""),
    Font = Enum.Font.GothamMedium,
    TextSize = 13,
    TextColor3 = T.Text,
    TextXAlignment = Enum.TextXAlignment.Left,
    TextTruncate = Enum.TextTruncate.AtEnd,
    Parent = c,
  })
  local head = make("TextButton", {
    Size = UDim2.new(0.5, -20, 0, 28),
    AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -10, 0, 7),
    BackgroundColor3 = T.Accent,
    BackgroundTransparency = 0.55,
    Text = "",
    AutoButtonColor = false,
    Parent = c,
  })
  corner(head, 9)
  stroke(head, T.Accent2, 1, 0.6)
  local val = make("TextLabel", {
    Size = UDim2.new(1, -24, 1, 0),
    Position = UDim2.fromOffset(8, 0),
    BackgroundTransparency = 1,
    Text = "",
    Font = Enum.Font.GothamBold,
    TextSize = 11,
    TextColor3 = T.White,
    TextXAlignment = Enum.TextXAlignment.Left,
    TextTruncate = Enum.TextTruncate.AtEnd,
    Parent = head,
  })
  local arrow = make("TextLabel", {
    Size = UDim2.fromOffset(18, 28),
    Position = UDim2.new(1, -18, 0, 0),
    BackgroundTransparency = 1,
    Text = "v",
    Font = Enum.Font.GothamBold,
    TextSize = 11,
    TextColor3 = T.Accent2,
    Parent = head,
  })
  local list = make("ScrollingFrame", {
    Size = UDim2.new(1, -20, 0, 0),
    Position = UDim2.fromOffset(10, 46),
    BackgroundTransparency = 1,
    BorderSizePixel = 0,
    ScrollBarThickness = 3,
    ScrollBarImageColor3 = T.Accent2,
    AutomaticCanvasSize = Enum.AutomaticSize.Y,
    CanvasSize = UDim2.new(),
    Visible = false,
    Parent = c,
  })
  make("UIListLayout", {Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, Parent = list})

  local obj = {Options = options or {}, Multi = multi and true or false, Card = c, Label = lab}
  local sel = {}
  local open = false
  local items = {}

  if obj.Multi then
    if type(default) == "table" then
      for k, x in pairs(default) do
        if type(k) == "number" then
          sel[x] = true
        elseif x == true then
          sel[k] = true
        end
      end
    end
  elseif default ~= nil then
    obj.Value = default
  end

  local function current()
    if obj.Multi then
      local out = {}
      for _, o in ipairs(obj.Options) do
        if sel[o] then
          out[#out + 1] = o
        end
      end
      return out
    end
    return obj.Value
  end

  local function paint()
    local v = current()
    if obj.Multi then
      local names = {}
      for _, o in ipairs(v) do
        names[#names + 1] = tostring(o)
      end
      val.Text = #names == 0 and "None" or table.concat(names, ", ")
    else
      val.Text = v ~= nil and tostring(v) or "None"
    end
    for _, it in ipairs(items) do
      local on
      if obj.Multi then
        on = sel[it.Opt] == true
      else
        on = obj.Value == it.Opt
      end
      it.Btn.BackgroundTransparency = on and 0.35 or 0.9
      it.Btn.TextColor3 = on and T.White or T.Sub
    end
  end

  local function resize()
    local h = math.min(#obj.Options, 6) * 32
    list.Size = UDim2.new(1, -20, 0, h)
    list.Visible = open
    arrow.Text = open and "^" or "v"
    tween(c, 0.2, {Size = UDim2.new(1, 0, 0, open and (42 + 8 + h + 6) or 42)})
  end

  local function fire()
    if callback then
      task.spawn(callback, current())
    end
  end

  local function build()
    for _, it in ipairs(items) do
      it.Btn:Destroy()
    end
    items = {}
    for i, opt in ipairs(obj.Options) do
      local b = make("TextButton", {
        Size = UDim2.new(1, -6, 0, 28),
        BackgroundColor3 = T.Accent,
        BackgroundTransparency = 0.9,
        BorderSizePixel = 0,
        Text = tostring(opt),
        Font = Enum.Font.GothamMedium,
        TextSize = 12,
        TextColor3 = T.Sub,
        AutoButtonColor = false,
        LayoutOrder = i,
        Parent = list,
      })
      corner(b, 8)
      b.MouseButton1Click:Connect(function()
        if obj.Multi then
          sel[opt] = not sel[opt] or nil
        else
          obj.Value = opt
          open = false
          resize()
        end
        paint()
        fire()
      end)
      items[#items + 1] = {Btn = b, Opt = opt}
    end
    paint()
    if open then
      resize()
    end
  end

  function obj:Set(v, fireCb)
    if obj.Multi then
      sel = {}
      if type(v) == "table" then
        for k, x in pairs(v) do
          if type(k) == "number" then
            sel[x] = true
          elseif x == true then
            sel[k] = true
          end
        end
      elseif v ~= nil then
        sel[v] = true
      end
    else
      obj.Value = v
    end
    paint()
    if fireCb ~= false then
      fire()
    end
  end
  obj.Select = obj.Set

  function obj:Refresh(newList)
    obj.Options = newList or {}
    if obj.Multi then
      local ns = {}
      for _, o in ipairs(obj.Options) do
        if sel[o] then
          ns[o] = true
        end
      end
      sel = ns
    else
      local found = false
      for _, o in ipairs(obj.Options) do
        if o == obj.Value then
          found = true
          break
        end
      end
      if not found then
        obj.Value = nil
      end
    end
    build()
  end

  function obj:SetTitle(t)
    lab.Text = tostring(t or "")
  end
  function obj:SetDesc() end
  function obj:Destroy()
    c:Destroy()
  end

  head.MouseButton1Click:Connect(function()
    open = not open
    resize()
  end)
  build()
  return obj
end

function Tab:AddInput(text, placeholder, default, callback, clear)
  local c = card(self, 42)
  local lab = make("TextLabel", {
    Size = UDim2.new(0.45, -14, 1, 0),
    Position = UDim2.fromOffset(14, 0),
    BackgroundTransparency = 1,
    Text = tostring(text or ""),
    Font = Enum.Font.GothamMedium,
    TextSize = 13,
    TextColor3 = T.Text,
    TextXAlignment = Enum.TextXAlignment.Left,
    TextTruncate = Enum.TextTruncate.AtEnd,
    Parent = c,
  })
  local frame = make("Frame", {
    Size = UDim2.new(0.55, -20, 0, 28),
    AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -10, 0, 7),
    BackgroundColor3 = T.Deep,
    BackgroundTransparency = 0.3,
    BorderSizePixel = 0,
    Parent = c,
  })
  corner(frame, 9)
  stroke(frame, T.Accent2, 1, 0.7)
  local box = make("TextBox", {
    Size = UDim2.new(1, -14, 1, 0),
    Position = UDim2.fromOffset(7, 0),
    BackgroundTransparency = 1,
    Text = tostring(default or ""),
    PlaceholderText = tostring(placeholder or ""),
    PlaceholderColor3 = T.Sub,
    Font = Enum.Font.GothamMedium,
    TextSize = 12,
    TextColor3 = T.Text,
    TextXAlignment = Enum.TextXAlignment.Left,
    TextTruncate = Enum.TextTruncate.AtEnd,
    ClearTextOnFocus = clear == true,
    Parent = frame,
  })
  local obj = {Value = box.Text, Card = c, Label = lab}
  box.FocusLost:Connect(function()
    obj.Value = box.Text
    if callback then
      task.spawn(callback, box.Text)
    end
  end)
  function obj:Set(v, fireCb)
    box.Text = tostring(v or "")
    obj.Value = box.Text
    if fireCb ~= false and callback then
      task.spawn(callback, box.Text)
    end
  end
  function obj:SetTitle(t)
    lab.Text = tostring(t or "")
  end
  function obj:SetDesc() end
  function obj:Destroy()
    c:Destroy()
  end
  return obj
end

local Core = {}
Shin.Core = Core

function Core.Toggle(tab, title, desc, default, cb)
  local skip = false
  local o = tab:AddToggle(title, default == true, function(v)
    if skip then
      skip = false
      return
    end
    if cb then
      cb(v)
    end
  end)
  local curTitle, curDesc = title, desc
  applyText(o, curTitle, curDesc)
  meta(tab, o.Card, "item", title)
  local w = {}
  function w:Set(v, fire)
    v = v and true or false
    if fire == false then
      if o.Value == v then
        return
      end
      skip = true
    end
    o:Set(v)
  end
  w.Select = w.Set
  function w:SetDesc(d)
    d = d == nil and "" or tostring(d)
    if d == curDesc then
      return
    end
    curDesc = d
    applyText(o, curTitle, curDesc)
  end
  w.SetContent = w.SetDesc
  function w:SetTitle(t)
    t = tostring(t or "")
    if t == curTitle then
      return
    end
    curTitle = t
    applyText(o, curTitle, curDesc)
  end
  function w:Destroy()
    o.Card:Destroy()
  end
  return setmetatable(w, {
    __index = function(_, k)
      if k == "Value" then
        return o.Value
      end
    end,
  })
end

function Core.Slider(tab, title, min, max, default, step, cb)
  local skip = false
  local o = tab:AddSlider(title, min, max, default, function(v)
    if skip then
      skip = false
      return
    end
    if cb then
      cb(v)
    end
  end, step)
  meta(tab, o.Card, "item", title)
  local w = {}
  function w:Set(v, fire)
    if fire == false then
      skip = true
    end
    o:Set(v)
  end
  function w:SetTitle(t)
    o.Label.Text = tostring(t or "")
  end
  function w:SetDesc() end
  function w:Destroy()
    o.Card:Destroy()
  end
  return setmetatable(w, {
    __index = function(_, k)
      if k == "Value" then
        return o.Value
      end
    end,
  })
end

function Core.Button(tab, title, desc, cb)
  local o = tab:AddButton(title, cb)
  meta(tab, o.Card, "item", title)
  local w = {}
  function w:SetTitle(t)
    o.Label.Text = tostring(t or "")
  end
  function w:SetDesc() end
  function w:Destroy()
    o.Card:Destroy()
  end
  return w
end

function Core.Dropdown(tab, title, desc, values, default, multi, cb)
  local o = tab:AddDropdown(title, values, default, cb, multi)
  meta(tab, o.Card, "item", title)
  return o
end

function Core.Input(tab, title, placeholder, default, cb, clear)
  local o = tab:AddInput(title, placeholder, default, cb, clear)
  meta(tab, o.Card, "item", title)
  return o
end

function Core.Paragraph(tab, title, desc)
  local o = tab:AddParagraph(title, desc)
  meta(tab, o.Card, "para", title, {obj = o})
  return o
end

function Core.Section(tab, text)
  tab:AddSection(tostring(text or ""))
end

return Shin
end)()

local ShinReg = {}
local ShinTabs = {}
local TabAlias = {fruitandraid = "dungeonraiding"}
local ShinWin

local function norm(s)
  s = tostring(s == nil and "" or s):lower()
  s = s:gsub("[^%w]", "")
  return s
end

local function noop() end

local function reg(name)
  ShinReg[norm(name)] = true
end

local Core = Shin.Core

local function wrapTab(t)
  local tab = {Shin = t}
  function tab:Toggle(c)
    c = c or {}
    reg(c.Title)
    return Core.Toggle(t, tostring(c.Title or ""), c.Desc, c.Value, c.Callback)
  end
  function tab:Slider(c)
    c = c or {}
    reg(c.Title)
    local v = c.Value or {}
    local min = v.Min or 0
    return Core.Slider(t, tostring(c.Title or ""), min, v.Max or 100, v.Default or min, c.Step or 1, c.Callback)
  end
  function tab:Dropdown(c)
    c = c or {}
    reg(c.Title)
    return Core.Dropdown(t, tostring(c.Title or ""), c.Desc, c.Values or {}, c.Value, c.Multi, c.Callback)
  end
  function tab:Button(c)
    c = c or {}
    reg(c.Title)
    return Core.Button(t, tostring(c.Title or ""), c.Desc, c.Callback)
  end
  function tab:Paragraph(c)
    c = c or {}
    reg(c.Title)
    return Core.Paragraph(t, c.Title, c.Desc)
  end
  function tab:Input(c)
    c = c or {}
    reg(c.Title)
    return Core.Input(t, tostring(c.Title or ""), c.Placeholder, c.Value, c.Callback)
  end
  function tab:Section(c)
    Core.Section(t, type(c) == "table" and c.Title or c)
    return {}
  end
  function tab:Divider() end
  function tab:Select()
    t:Select()
  end
  return tab
end

local WindUI = {}

function WindUI:CreateWindow(o)
  o = o or {}
  local S = Shin.new({Key = o.ToggleKey})
  ShinWin = S
  local W = {Shin = S, Destroyed = false, Closed = false, Title = o.Title}
  function W:Tab(c)
    c = c or {}
    local name = tostring(c.Title or c.Name or "Tab")
    local real = S:AddTab(name)
    ShinTabs[norm(name)] = real
    return wrapTab(real)
  end
  function W:Destroy()
    W.Destroyed = true
    S:Destroy()
  end
  function W:Close()
    S:Minimize()
  end
  function W:Open()
    S:Restore()
  end
  function W:Toggle()
    S:Toggle()
  end
  function W:Dialog(d)
    d = d or {}
    S:Notify(tostring(d.Title or ""), tostring(d.Content or ""), 4)
  end
  function W:GetUIScale()
    return 1
  end
  W.SetUIScale = noop
  W.ToggleFullscreen = noop
  W.EditOpenButton = noop
  W.SetTitle = noop
  W.SetAuthor = noop
  W.SetIcon = noop
  W.SetToggleKey = noop
  W.SetBackgroundImage = noop
  W.SelectTab = noop
  W.Lock = noop
  W.Unlock = noop
  W.OnClose = noop
  W.OnDestroy = noop
  W.OnOpen = noop
  W.Divider = noop
  W.Section = noop
  W.Tag = noop
  return W
end

function WindUI:Notify(d)
  d = d or {}
  if ShinWin then
    ShinWin:Notify(tostring(d.Title or ""), tostring(d.Content or ""), d.Duration or 4)
  end
end

function WindUI:SetTheme() end

function WindUI:GetThemes()
  return {}
end

local function makeRedzLib()
  local base = {}
  for k in pairs(ShinReg) do
    base[k] = true
  end
  local lib = {}
  function lib:MakeWindow()
    local win = {}
    local function stub()
      return setmetatable({Value = false}, {
        __index = function()
          return noop
        end,
      })
    end
    function win:NewMinimizer()
      return {CreateMobileMinimizer = function()
        return {}
      end}
    end
    function win:Notify(c)
      WindUI:Notify(c)
    end
    function win:MakeTab(c)
      c = c or {}
      local title = tostring(c.Title or c.Name or "Tab")
      title = title:gsub("^Tab ", "")
      local real
      local pending
      local function tabFor()
        if not real then
          local key = norm(title)
          real = ShinTabs[TabAlias[key] or key] or ShinWin:AddTab(title)
        end
        if pending then
          real:AddSection(pending)
          pending = nil
        end
        return real
      end
      local function dup(name)
        local k = norm(name)
        return k ~= "" and base[k] == true
      end
      local tab = {}
      function tab:AddSection(text)
        pending = tostring(text or "")
      end
      function tab:AddToggle(o)
        o = o or {}
        local name = o.Name or o.Title or ""
        if dup(name) then
          return stub()
        end
        local w = Core.Toggle(tabFor(), tostring(name), o.Description or o.Desc, o.Default == true, o.Callback)
        if o.Default == true and o.Callback then
          task.defer(o.Callback, true)
        end
        return w
      end
      function tab:AddButton(o)
        o = o or {}
        local name = o.Name or o.Title or ""
        if dup(name) then
          return stub()
        end
        return Core.Button(tabFor(), tostring(name), o.Description or o.Desc, o.Callback)
      end
      function tab:AddDropdown(o)
        o = o or {}
        local name = o.Name or o.Title or ""
        if o.Default ~= nil and o.Callback then
          task.defer(o.Callback, o.Default)
        end
        if dup(name) then
          return stub()
        end
        return Core.Dropdown(
          tabFor(),
          tostring(name),
          o.Description or o.Desc,
          o.Options or o.Values or {},
          o.Default,
          o.MultiSelect == true or o.Multi == true,
          o.Callback
        )
      end
      function tab:AddSlider(o)
        o = o or {}
        local name = o.Name or o.Title or ""
        local min = o.Min or 0
        local def = o.Default or min
        if o.Callback then
          task.defer(o.Callback, def)
        end
        if dup(name) then
          return stub()
        end
        return Core.Slider(tabFor(), tostring(name), min, o.Max or 100, def, o.Increment or o.Step or 1, o.Callback)
      end
      function tab:AddTextBox(o)
        o = o or {}
        local name = o.Name or o.Title or ""
        if dup(name) then
          return stub()
        end
        return Core.Input(tabFor(), tostring(name), o.Placeholder, o.Default, o.Callback, o.ClearOnFocus)
      end
      function tab:AddParagraph(title2, desc)
        if dup(title2) then
          return stub()
        end
        return Core.Paragraph(tabFor(), title2, desc)
      end
      return tab
    end
    return setmetatable(win, {
      __index = function()
        return noop
      end,
    })
  end
  return lib
end

