            def = values[def]
        end
        local rec = newRec(id, "Dropdown", def)
        rec.TabTitle = tabTitle(tab)
        rec.Title, rec.Values, rec._cb = tostring(c.Title or id or "Dropdown"), values, c.Callback
        local cb = c.Callback
        rec.Element = tab:Dropdown({
            Title = tostring(c.Title or id or "Dropdown"),
            Desc = descOf(c),
            Values = values,
            Value = def,
            Multi = c.Multi == true,
            AllowNone = true,
            Callback = mkCallback(rec, cb),
        })
        if def ~= nil then
            initFire(rec, cb, def)
        end
        return rec
    end
    function UIX.Button(tab, id, c)
        c = c or {}
    do local _fxg = _G.FARMX
      if not (_fxg and _fxg.Enable and _fxg.Enable.UIXGuard == false) then
        if tab == UIX or type(id) == "table" then
          warn("[UIXGuard] blocked recursive call")
          return nil
        end
      end
    end
        local rec = newRec(id, "Button", nil)
        rec.TabTitle = tabTitle(tab)
        local cb = c.Callback
        rec._cb = cb
        rec.Element = tab:Button({
            Title = tostring(c.Title or id or "Button"),
