    do local _fxg = _G.FARMX
      if not (_fxg and _fxg.Enable and _fxg.Enable.UIXGuard == false) then
        if tab == UIX or type(id) == "table" then
          warn("[UIXGuard] blocked recursive call")
          return nil
        end
      end
    end
        local rec = newRec(id, "Paragraph", nil)
        rec.TabTitle = tabTitle(tab)
        rec._desc = descOf(c) or ""
        rec._title = tostring(c.Title or "")
        rec.Element = tab:Paragraph({
            Title = rec._title ~= "" and rec._title or " ",
            Desc = rec._desc ~= "" and rec._desc or " ",
        })
        return rec
    end
    function UIX.Input(tab, id, c)
        c = c or {}
    do local _fxg = _G.FARMX
      if not (_fxg and _fxg.Enable and _fxg.Enable.UIXGuard == false) then
        if tab == UIX or type(id) == "table" then
          warn("[UIXGuard] blocked recursive call")
          return nil
        end
      end
    end
        local rec = newRec(id, "Input", c.Default or c.Value or "")
        rec.TabTitle = tabTitle(tab)
        local cb = c.Callback
        rec.Element = tab:Input({
            Title = tostring(c.Title or id or "Input"),
            Desc = descOf(c),
            Value = rec.Value,
            Placeholder = c.Placeholder,
            Callback = mkCallback(rec, cb),
        })
        return rec
    end
    function Lib:Notify(d)
        d = d or {}
        local isl = WindUI.Island
        if isl then
            local ok = pcall(function()
                isl:Notify({
                    Title = d.Title, Content = d.Content, Duration = d.Duration,
                    Icon = d.Icon, Value = d.Value, Unit = d.Unit,
                })
            end)
            if ok then
                return
            end
        end
        pcall(function()
            WindUI:Notify({ Title = d.Title or "", Content = d.Content or "", Duration = d.Duration or 4 })
        end)
    end
    function Lib:NotifyRed(d)
        d = d or {}
        local f = WindUI.NotifyRed
        if f and pcall(f, WindUI, d) then return end
        return Lib:Notify({ Title = d.Text or d.Title, Content = d.Description, Duration = d.Duration })
    end
    function Lib:NotifyYellow(d)
