    end
    Lib.NotifyRedDot, Lib.NotifyYellowDot, Lib.NotifyGreenDot = Lib.NotifyRed, Lib.NotifyYellow, Lib.NotifyGreen
    function Lib:NotifyDot(color, content, duration)
        local f = WindUI.NotifyDot
        if f and pcall(f, WindUI, color, content, duration) then return end
        return Lib:Notify({ Title = tostring(content or ""), Duration = duration })
    end
    return Lib
end)()
UIX = Library.UIX
local Window = Library.Window
-- [LX] P84 Longxgen (Cross cua boncuti, doi ten): registry tu dong tu UIX + NLU + shell + quyen. Giao dien nam trong island (XC.*)
do
    local WindUI = Library.WindUI
    local Opts = Library.Options
    local UIS = game:GetService("UserInputService")
    local LX = {
        Enabled = true,
        Perm = { Control = true, Shell = true, Character = true, Interface = true, Trigger = true },
        Face = "deadpan",
        Mood = "deadpan",
        MoodUntil = 0,
        Thinking = false,
        Busy = 0,
        Queue = {},
        Chat = {},
        Lines = {},
        Ver = 0,
        ChatVer = 0,
        Pending = nil,
    }
    Library.Longxgen = LX

    ------------------------------------------------------------------ text helpers
    local MAPSRC = {
        a = "àáạảãâầấậẩẫăằắặẳẵÀÁẠẢÃÂẦẤẬẨẪĂẰẮẶẲẴ",
        e = "èéẹẻẽêềếệểễÈÉẸẺẼÊỀẾỆỂỄ",
        i = "ìíịỉĩÌÍỊỈĨ",
        o = "òóọỏõôồốộổỗơờớợởỡÒÓỌỎÕÔỒỐỘỔỖƠỜỚỢỞỠ",
        u = "ùúụủũưừứựửữÙÚỤỦŨƯỪỨỰỬỮ",
        y = "ỳýỵỷỹỲÝỴỶỸ",
        d = "đĐ",
    }
    local MAP = {}
    for plain, set in pairs(MAPSRC) do
        for _, cp in utf8.codes(set) do
            MAP[utf8.char(cp)] = plain
        end
    end
    local function asc(s)
        s = tostring(s == nil and "" or s)
        s = string.gsub(s, utf8.charpattern, function(ch)
            return MAP[ch]
        end)
        return s
    end
    local function norm(s)
        s = string.lower(asc(s))
        s = string.gsub(s, "=", " = ")
        s = string.gsub(s, "[^%w%.%-%s=]", " ")
        s = string.gsub(s, "%s+", " ")
        s = string.gsub(s, "^%s+", "")
        s = string.gsub(s, "%s+$", "")
        return s
    end
    local function words(s)
        local out = {}
        for w in string.gmatch(s, "%S+") do
            out[#out + 1] = w
        end
        return out
    end
    local function has(p, kw)
        return string.find(" " .. p .. " ", " " .. kw .. " ", 1, true) ~= nil
    end
    local function hasAny(p, list)
        for _, kw in ipairs(list) do
            if has(p, kw) then
                return kw
            end
        end
        return nil
    end
    local function pick(t)
        return t[math.random(1, #t)]
    end
    local function esc(w)
        return (string.gsub(w, "%p", "%%%0"))
    end
    local function camel(id)
        local s = tostring(id)
        s = string.gsub(s, "(%l)(%u)", "%1 %2")
        s = string.gsub(s, "_", " ")
        return s
    end

    ------------------------------------------------------------------ output (shell + chat)
    local COLOR_OF = { cmd = "cmd", ok = "ok", err = "err", dim = "dim", out = "out", warn = "warn" }
    function LX.Out(kind, text)
        local line = { kind = COLOR_OF[kind] or "out", text = asc(text), t = os.clock() }
        local L = LX.Lines
        L[#L + 1] = line
        if #L > 80 then
            table.remove(L, 1)
        end
        LX.Ver = LX.Ver + 1
        if LX.OnLine then
            pcall(LX.OnLine, line)
        end
        return line
    end
    function LX.SetMood(m, hold)
        LX.Mood = m or LX.Face
        LX.MoodUntil = (hold and hold > 0) and (os.clock() + hold) or 0
    end
    function LX.Say(text, mood, hold)
        text = tostring(text or "")
        local C = LX.Chat
        C[#C + 1] = { role = "ai", text = text, t = os.clock() }
        if #C > 60 then
            table.remove(C, 1)
        end
        LX.ChatVer = LX.ChatVer + 1
        LX.SetMood(mood or LX.Face, hold or 2.4)
        if LX.OnSay then
            pcall(LX.OnSay, text)
        end
    end
    function LX.User(text)
        local C = LX.Chat
        C[#C + 1] = { role = "user", text = tostring(text), t = os.clock() }
        if #C > 60 then
            table.remove(C, 1)
        end
        LX.ChatVer = LX.ChatVer + 1
    end

    ------------------------------------------------------------------ registry (tu dong tu UIX: Toggle/Slider/Dropdown/Input/Button)
    local reg, regN = {}, -1
    local STOP = { auto = true, the = true, toggle = true, ["and"] = true, of = true }
    local FILL = {}
    for w in string.gmatch("bat mo tat dung ngung dat chinh chon bam nhan click press set on off turn enable disable select switch cho toi minh di nhe giup hay la len xuong thanh sang cai chuc nang tinh nang gium lam voi dum tu vao ra nua xem ban oi e ay a nha nhanh", "%S+") do
        FILL[w] = true
    end
    local function buildReg()
        local n = 0
        for _ in pairs(Opts) do
            n = n + 1
        end
        if n == regN then
            return reg
        end
        regN = n
        reg = {}
        for id, rec in pairs(Opts) do
            local t = rec.Type
            if type(id) == "string" and string.sub(id, 1, 3) ~= "LX_" and (t == "Toggle" or t == "Slider" or t == "Dropdown" or t == "Input" or t == "Button") then
                local title = tostring(rec.Title or id)
                local nt = norm(title)
                local toks, itoks = {}, {}
                for _, w in ipairs(words(nt)) do
                    if not STOP[w] then
                        toks[#toks + 1] = w
                    end
                end
                if #toks == 0 then
                    toks = words(nt)
                end
                for _, w in ipairs(words(norm(camel(id)))) do
                    if not STOP[w] then
                        itoks[#itoks + 1] = w
                    end
                end
                reg[#reg + 1] = { id = id, rec = rec, type = t, title = title, nt = nt, toks = toks, itoks = itoks, tab = rec.TabTitle }
            end
        end
        table.sort(reg, function(a, b)
            return a.id < b.id
        end)
        return reg
    end
    LX.Registry = buildReg
    local function hasTok(P, w)
        if P[w] then
            return true
        end
        if #w >= 4 then
            for p in pairs(P) do
                if #p >= 4 and (string.find(p, w, 1, true) or string.find(w, p, 1, true)) then
                    return true
                end
            end
        end
        return false
    end
    local function cover(toks, P)
        local n = #toks
        if n == 0 then
            return 0, 0
        end
        local m = 0
        for _, w in ipairs(toks) do
            if hasTok(P, w) then
                m = m + 1
            end
        end
        local s = m / n
        if m == n then
            s = s + 0.25 + 0.12 * math.min(m, 4)
        elseif m > 0 then
            s = s - 0.05
        end
        return s, m
    end
    local function scoreItem(it, phrase, P)
        local s1 = cover(it.toks, P)
        local s2 = cover(it.itoks, P)
        local best = math.max(s1, s2 * 0.9)
        if #it.nt >= 3 and string.find(phrase, it.nt, 1, true) then
            best = best + 0.3
        end
        return best
    end
    local function resolve(phrase, want)
        local P = {}
        for _, w in ipairs(words(phrase)) do
            if not FILL[w] and not tonumber(w) then
                P[w] = true
            end
        end
        local list = {}
        for _, it in ipairs(buildReg()) do
            if not want or want[it.type] then
                local s = scoreItem(it, phrase, P)
                if s >= 0.6 then
                    list[#list + 1] = { it = it, s = s }
                end
            end
        end
        table.sort(list, function(a, b)
            if a.s ~= b.s then
                return a.s > b.s
            end
            return #a.it.nt > #b.it.nt
        end)
        if #list == 0 then
            return nil, list
        end
        local gap = list[2] and (list[1].s - list[2].s) or 1
        if gap >= 0.12 then
            return list[1].it, list
        end
        return nil, list
    end

    ------------------------------------------------------------------ actions (moi action in 1 dong shell len island)
    local function need(perm, name)
        if not LX.Perm[perm] then
            LX.Out("err", "permission denied: " .. (name or perm))
            return false
        end
        return true
    end
    local function short(it)
        return string.lower(asc(it.title))
    end
    local function toBool(v)
        return v == true
    end
    function LX.DoToggle(it, on)
        if not need("Control", "control") then
            return false, "perm"
        end
        LX.Out("cmd", "toggle '" .. short(it) .. "' " .. (on and "on" or "off"))
        if toBool(it.rec.Value) == on then
            LX.Out("dim", "already " .. (on and "on" or "off"))
            return true, "same"
        end
        local ok, err = pcall(it.rec.SetValue, it.rec, on)
        if ok then
            LX.Out("ok", "done")
        else
            LX.Out("err", tostring(err))
        end
        return ok, "set"
    end
    function LX.DoSlider(it, n)
        if not need("Control", "control") then
            return false, "perm"
        end
        local lo, hi = tonumber(it.rec.Min) or 0, tonumber(it.rec.Max) or 100
        local c = math.clamp(n, lo, hi)
        LX.Out("cmd", "set '" .. short(it) .. "' = " .. tostring(c) .. "  [" .. lo .. ".." .. hi .. "]")
        local ok, err = pcall(it.rec.SetValue, it.rec, c)
        if ok then
            LX.Out("ok", "done")
        else
            LX.Out("err", tostring(err))
        end
        return ok, c
    end
    local function valueText(v)
        if type(v) == "table" then
            return tostring(v.Title or v.Name or v.Value or "")
        end
        return tostring(v)
    end
    function LX.DoDropdown(it, text)
        if not need("Control", "control") then
            return false, "perm"
        end
        local want = norm(text)
        local bestV, bestS = nil, 0
        for _, v in ipairs(it.rec.Values or {}) do
            local nv = norm(valueText(v))
            local s = 0
            if nv == want then
                s = 2
            elseif nv ~= "" and (string.find(nv, want, 1, true) or string.find(want, nv, 1, true)) then
                s = 1 + #nv / math.max(#want, 1) * 0.1
            else
                local P = {}
                for _, w in ipairs(words(want)) do
                    P[w] = true
                end
                local tk = words(nv)
                local m = 0
                for _, w in ipairs(tk) do
                    if P[w] then
                        m = m + 1
                    end
                end
                if #tk > 0 then
                    s = m / #tk * 0.9
                end
            end
            if s > bestS then
                bestV, bestS = v, s
            end
        end
        if not bestV or bestS < 0.5 then
            LX.Out("err", "no option matches '" .. asc(text) .. "'")
            return false, "none"
        end
        LX.Out("cmd", "select '" .. short(it) .. "' -> " .. string.lower(asc(valueText(bestV))))
        local ok, err = pcall(it.rec.SetValue, it.rec, bestV)
        if ok then
            LX.Out("ok", "done")
        else
            LX.Out("err", tostring(err))
        end
        return ok, valueText(bestV)
    end
    function LX.DoInput(it, text)
        if not need("Control", "control") then
            return false, "perm"
        end
        LX.Out("cmd", "input '" .. short(it) .. "' <- " .. asc(text))
        local ok, err = pcall(it.rec.SetValue, it.rec, text)
        if ok then
            LX.Out("ok", "done")
        else
            LX.Out("err", tostring(err))
        end
        return ok
    end
    function LX.DoPress(it)
        if not need("Control", "control") then
            return false, "perm"
        end
        LX.Out("cmd", "press '" .. short(it) .. "'")
        local cb = it.rec._cb
        if not cb then
            local e = it.rec.Element
            cb = e and e.Callback
        end
        if type(cb) ~= "function" then
            LX.Out("err", "button has no callback")
            return false
        end
        task.spawn(pcall, cb)
        LX.Out("ok", "pressed")
        return true
    end
    function LX.DoAll(on)
        if not need("Control", "control") then
            return 0
        end
        LX.Out("cmd", "toggle * " .. (on and "on" or "off"))
        local n = 0
        for _, it in ipairs(buildReg()) do
            if it.type == "Toggle" and toBool(it.rec.Value) ~= on then
                if pcall(it.rec.SetValue, it.rec, on) then
                    n = n + 1
                end
            end
        end
        LX.Out("ok", n .. " toggles changed")
        return n
    end

    ------------------------------------------------------------------ cac lenh chung (timer / watch / theme / nhan vat)
    local function dim()
        local fx = _G.FARMX
        return fx and fx.DIM
    end
    function LX.DoTimer(minutes)
        local d = dim()
        if not d or not d.TimerStart then
            LX.Out("err", "timer unavailable")
            return false
        end
        LX.Out("cmd", "timer " .. tostring(minutes) .. "m")
        d.TimerStart(minutes)
        LX.Out("ok", "timer started")
        return true
    end
    function LX.DoWatch(act)
        local d = dim()
        if not d then
            LX.Out("err", "stopwatch unavailable")
            return false
        end
        LX.Out("cmd", "stopwatch " .. act)
        if act == "lap" and d.WatchLap then
            d.WatchLap()
        elseif act == "reset" and d.WatchReset then
            d.WatchReset()
        elseif act == "stoptimer" and d.TimerStop then
            d.TimerStop()
        elseif d.WatchToggle then
            d.WatchToggle()
        end
        LX.Out("ok", "done")
        return true
    end
    function LX.ThemeList()
        local out = {}
        pcall(function()
            for k in pairs(WindUI:GetThemes()) do
                out[#out + 1] = tostring(k)
            end
        end)
        table.sort(out)
        return out
    end
    function LX.DoTheme(name)
        if not need("Interface", "interface") then
            return false
        end
        local want = norm(name)
        if want == "toi" then
            want = "dark"
        elseif want == "sang" then
            want = "light"
        end
        for _, th in ipairs(LX.ThemeList()) do
            if norm(th) == want then
                LX.Out("cmd", "theme " .. string.lower(th))
                local ok = pcall(function()
                    WindUI:SetTheme(th)
                end)
                LX.Out(ok and "ok" or "err", ok and "done" or "theme failed")
                return ok, th
            end
        end
        LX.Out("err", "unknown theme '" .. asc(name) .. "'")
        return false
    end

