EquipWeapon = function(text)
  if not text then return end
  if type(text) ~= "string" or text == "" then return end
  local _c = plr.Character
  if not _c then return end
  local _bp = plr:FindFirstChild("Backpack")
  if not _bp then return end
  local _t = _bp:FindFirstChild(text)
  if not _t then return end
  if not _t:IsA("Tool") then return end
  local _h = _c:FindFirstChildOfClass("Humanoid")
  if not (_h and _h:IsA("Humanoid")) then return end
  _h:EquipTool(_t)
end
weaponSc = function(weapon)
  for __in, v in pairs(plr.Backpack:GetChildren()) do
    if v:IsA("Tool") then
      if v.ToolTip == weapon then EquipWeapon(v.Name) end
    end
  end
end
