MaruHop = function()
  local G = _G
  if G.__MaruHopBusy and (os.clock() - (G.__MaruHopBusyAt or 0)) < 90 then return false end
  G.__MaruHopBusy = true
  G.__MaruHopBusyAt = os.clock()
  task.spawn(function()
    local okAll, errAll = pcall(function()
      local HS = game:GetService("HttpService")
      local RS = game:GetService("ReplicatedStorage")
      local TPS = game:GetService("TeleportService")
      local LP = game:GetService("Players").LocalPlayer
      local FILE, TTL = "serverhop_cache.json", 1800
      local visited = {}
      if type(isfile) == "function" and type(readfile) == "function" then
        pcall(function()
          if isfile(FILE) then
            local d = HS:JSONDecode(readfile(FILE))
            if type(d) == "table" then
              for id, t in pairs(d) do
                if type(t) == "number" and os.time() - t < TTL then visited[id] = t end
              end
            end
          end
        end)
      end
      local function save()
        if type(writefile) == "function" then pcall(writefile, FILE, HS:JSONEncode(visited)) end
      end
      local list, seen, cur = {}, {}, ""
      for _ = 1, 5 do
        local url = "https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&limit=100"
        if cur ~= "" then url = url .. "&cursor=" .. cur end
        local okh, body = pcall(function() return game:HttpGet(url) end)
        if not okh or type(body) ~= "string" then break end
        local okd, data = pcall(function() return HS:JSONDecode(body) end)
        if not okd or type(data) ~= "table" or type(data.data) ~= "table" then break end
        for _, s in ipairs(data.data) do
          if type(s) == "table" and s.id and not seen[s.id] then
            seen[s.id] = true
            list[#list + 1] = { id = s.id, n = tonumber(s.playing) or 0, max = tonumber(s.maxPlayers) or 0, r = math.random() }
          end
        end
        if type(data.nextPageCursor) ~= "string" or data.nextPageCursor == "" then break end
        cur = data.nextPageCursor
        task.wait(0.3)
      end
      if #list == 0 then
        local br0 = RS:FindFirstChild("__ServerBrowser")
        if br0 then
          for page = 1, 8 do
            local okr, rem = pcall(function() return br0:InvokeServer(page) end)
            if okr and type(rem) == "table" then
              for id, v in pairs(rem) do
                local c = type(v) == "table" and tonumber(v.Count) or nil
                if c and c < 12 and not seen[id] then
                  seen[id] = true
                  list[#list + 1] = { id = id, n = c, max = 0, r = math.random() }
                end
              end
            end
            task.wait(0.2)
          end
        end
      end
      local cand = {}
      for _, s in ipairs(list) do
        if s.id ~= game.JobId and not visited[s.id] and (s.max == 0 or s.max - s.n >= 2) then cand[#cand + 1] = s end
      end
      table.sort(cand, function(a, b)
        if a.n ~= b.n then return a.n < b.n end
        return a.r < b.r
      end)
      local tries = 0
      for _, s in ipairs(cand) do
        if tries >= 12 then break end
        tries = tries + 1
        visited[s.id] = os.time()
        save()
        local before = game.JobId
        local okt = false
        local br = RS:FindFirstChild("__ServerBrowser")
        if br then okt = pcall(function() br:InvokeServer("teleport", s.id) end) end
        if not okt then pcall(function() TPS:TeleportToPlaceInstance(game.PlaceId, s.id, LP) end) end
        local t0 = os.clock()
        while os.clock() - t0 < 8 do
          task.wait(0.5)
          if game.JobId ~= before then return end
        end
        G.__MaruHopBusyAt = os.clock()
      end
    end)
    G.__MaruHopBusy = false
    if not okAll then warn("[MaruHop] " .. tostring(errAll)) end
  end)
  return true
end
