_tp = function(target)
  local character = plr.Character
  if not character or not character:FindFirstChild("HumanoidRootPart") then return end
  local fxAtStart = _G.FARMX
  -- BodyVelocity/BodyGyro own the character only during the short dodge impulse.
  if fxAtStart and fxAtStart.MobDodge and fxAtStart.MobDodge.bodyActive then return end
  do
    local fxn = _G.FARMX
    if fxn and fxn.Nav and fxn.Nav.Auto then pcall(fxn.Nav.Auto, target) end
  end
  do
      local fxS = _G.FARMX
      if fxS and fxS.Enable and fxS.Enable.SafeModeOwner and fxS.SafeMode and fxS.SafeMode.state == "PANIC_UP" and not fxS.SafeMode.own then return end
  end
  do
      local fxD = _G.FARMX
      if fxD and fxD.Enable and typeof(target) == "CFrame" then
          local dodgeOffset = 0
          -- Merge dedicated Sea Beast/Terrorshark and mob-skill dodges; keep the highest safe offset.
          if type(fxD.DodgeOffset) == "function" then
              local okDodge, combinedOffset = pcall(fxD.DodgeOffset)
              if okDodge and type(combinedOffset) == "number" then
                  dodgeOffset = math.max(dodgeOffset, combinedOffset)
              end
          else
              if fxD.Enable.SeaDodgeV3 and type(fxD.SeaDodgeOffset) == "function" then
                  local okSea, seaOffset = pcall(fxD.SeaDodgeOffset)
                  if okSea and type(seaOffset) == "number" then dodgeOffset = math.max(dodgeOffset, seaOffset) end
              end
              if fxD.Enable.MobDodge and type(fxD.MobDodgeOffset) == "function" then
                  local okMob, mobOffset = pcall(fxD.MobDodgeOffset)
                  if okMob and type(mobOffset) == "number" then dodgeOffset = math.max(dodgeOffset, mobOffset) end
              end
          end
          if dodgeOffset > 0 then target = target + Vector3.new(0, dodgeOffset, 0) end
      end
  end
  local rootPart = character.HumanoidRootPart
  local distance = (target.Position - rootPart.Position).Magnitude
  -- User-requested fixed profile: >10 studs = 200; <=10 studs = 210.
  local requestedSpeed = distance <= 10 and 210 or 200
  local tweenSpeed = requestedSpeed
  local fx = _G.FARMX
  do
    local fx0 = fx
    if fx0 then fx0.SeaLastTarget = typeof(target) == "CFrame" and target or nil end
    local seaM = fx0 and fx0.SeaMode and fx0.SeaMode()
    if fx0 then fx0.SeaPath = seaM and "BLOCK" or "FLY/BLOCK" end
    if not seaM and fx0 and fx0.Enable and fx0.Enable.LinearVelocityFly and fx0.FlyTo and typeof(target) == "CFrame" then
      cancelMaruTargetTween()
      if fx0.FlyTo(target, tweenSpeed) then return end
    end
  end
  if fx and fx.Enable and fx.Enable.NearTween and distance <= ((fx.Cfg and fx.Cfg.NearDist) or 10) then
    tweenSpeed = math.max(tweenSpeed, (fx.Cfg and fx.Cfg.NearSpeed) or 210)
  end
  local _p26n250 = fx and distance <= ((fx.Cfg and fx.Cfg.FlyNearDist) or 10)
  if _p26n250 then
    tweenSpeed = math.max(tweenSpeed, (fx.Cfg and fx.Cfg.FlyNearSpeed) or 210)
  end
  -- Do not let the UI slider or a secondary cap silently reduce this safety profile.
  tweenSpeed = distance <= 10 and 210 or 200
  local activeTween = getgenv().__MaruActiveTargetTween
  local activeGoal = getgenv().__MaruActiveTargetTweenGoal
  local activeSpeed = getgenv().__MaruActiveTargetTweenSpeed
  if activeTween and activeGoal and activeSpeed == tweenSpeed
      and activeTween.PlaybackState == Enum.PlaybackState.Playing
      and (activeGoal.Position - target.Position).Magnitude <= 1.5 then
      return
  end
  cancelMaruTargetTween()
  local tweenInfo = TweenInfo.new(math.max(distance / tweenSpeed, 0.001), Enum.EasingStyle.Linear)
  local tween = game:GetService("TweenService"):Create(block, tweenInfo, {CFrame = target})
  getgenv().__MaruActiveTargetTween = tween
  getgenv().__MaruActiveTargetTweenGoal = target
  getgenv().__MaruActiveTargetTweenSpeed = tweenSpeed
  if (function() local _h = Attack.Hum(plr.Character); return _h and _h.Sit end)() == true then
    block.CFrame = CFrame.new(block.Position.X, target.Y, block.Position.Z)
