    FX.MobDodge = {
        untilT = 0, bossUntil = 0, bodyToken = 0, bodyActive = false,
        bodyUntil = 0, velocity = nil, gyro = nil, clip = nil, clipMaxForce = nil,
        lastImpulse = 0, handled = setmetatable({}, { __mode = "k" }),
        impulsed = setmetatable({}, { __mode = "k" }),
    }

    FX.MobDodgeCleanupBody = function()
        local st = FX.MobDodge
        if not st then return end
        if st.velocity then pcall(function() st.velocity:Destroy() end) end
        if st.gyro then pcall(function() st.gyro:Destroy() end) end
        st.velocity, st.gyro = nil, nil
        if st.clip and st.clip.Parent and st.clipMaxForce then
            pcall(function() st.clip.MaxForce = st.clipMaxForce end)
        end
        st.clip, st.clipMaxForce = nil, nil
        st.bodyActive = false
        st.bodyUntil = 0
    end

    FX.MobDodgeApplyBody = function(boss)
        local st = FX.MobDodge
        local char = plr.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not (st and hrp and hum and hum.Health > 0) then return false end
        if _G.FARMX ~= FX or not FX.On then return false end

        -- A dodge gets a short exclusive movement window; never fight the flight/tween movers.
        cancelMaruTargetTween()
        if FX.FlyStop then pcall(FX.FlyStop) end
        FX.MobDodgeCleanupBody()
        st.bodyToken = (st.bodyToken or 0) + 1
        local bodyToken = st.bodyToken
        local duration = boss and ((FX.Cfg and FX.Cfg.MobDodgeBossBodyDuration) or 0.42)
            or ((FX.Cfg and FX.Cfg.MobDodgeBodyDuration) or 0.32)
        local upwardSpeed = boss and ((FX.Cfg and FX.Cfg.MobDodgeBossVelocity) or 175)
            or ((FX.Cfg and FX.Cfg.MobDodgeBodyVelocity) or 135)
        local maxForce = (FX.Cfg and FX.Cfg.MobDodgeBodyForce) or 1000000

        local clip = hrp:FindFirstChild("BodyClip")
        if clip and clip:IsA("BodyVelocity") then
            st.clip = clip
            st.clipMaxForce = clip.MaxForce
            pcall(function() clip.MaxForce = Vector3.zero end)
        end

        -- These legacy BodyMovers are intentionally retained because this dodge path
        -- requires a direct vertical impulse and orientation hold on the local character.
        local okMovers = pcall(function()
            local velocity = Instance.new("BodyVelocity")
            st.velocity = velocity
            velocity.Name = "MaruSkillDodgeVelocity"
            velocity.P = 18000
            velocity.MaxForce = Vector3.new(0, maxForce, 0)
            velocity.Velocity = Vector3.new(0, upwardSpeed, 0)
            velocity.Parent = hrp

            local gyro = Instance.new("BodyGyro")
            st.gyro = gyro
            gyro.Name = "MaruSkillDodgeGyro"
            gyro.P = 18000
            gyro.D = 900
            local torque = (FX.Cfg and FX.Cfg.MobDodgeGyroTorque) or 90000000
            gyro.MaxTorque = Vector3.new(torque, torque, torque)
            gyro.CFrame = hrp.CFrame
            gyro.Parent = hrp
        end)
        if not okMovers then
            FX.MobDodgeCleanupBody()
            return false
        end
        st.bodyActive = true
        st.bodyUntil = os.clock() + duration
        st.lastImpulse = os.clock()
        task.spawn(function()
            while st.bodyToken == bodyToken and st.bodyActive and os.clock() < st.bodyUntil do
                if plr.Character ~= char or not hrp.Parent then break end
                task.wait(0.025)
            end
            if st.bodyToken == bodyToken then FX.MobDodgeCleanupBody() end
        end)
        return true
    end

    FX.MobDodgeTrigger = function(seconds, boss, mob, signal)
        local st = FX.MobDodge
        if not (st and FX.Enable and FX.Enable.MobDodge) then return false end
        if _G.FARMX ~= FX or not FX.On then return false end
        local now = os.clock()
        local duration = math.clamp(tonumber(seconds) or 0.45, 0.1, (FX.Cfg and FX.Cfg.MobDodgeMaxHold) or 14)
        st.untilT = math.max(st.untilT or 0, now + duration)
        if boss then st.bossUntil = math.max(st.bossUntil or 0, now + duration) end

        local freshSignal = signal == nil or not st.impulsed[signal]
        local cooldown = (FX.Cfg and FX.Cfg.MobDodgeBodyCooldown) or 0.55
        if freshSignal and ((st.lastImpulse or 0) <= 0 or now - st.lastImpulse >= cooldown) then
            st.lastImpulse = now
            local applyOk, applied = pcall(FX.MobDodgeApplyBody, boss == true)
            if signal ~= nil and applyOk and applied == true then st.impulsed[signal] = true end
        end
        return true
    end

    FX.MobDodgeOffset = function()
        local E, st = FX.Enable, FX.MobDodge
        if not (E and E.MobDodge and st) then return 0 end
        local now = os.clock()
        if now >= (st.untilT or 0) then
            st.untilT, st.bossUntil = 0, 0
            return 0
        end
        if now < (st.bossUntil or 0) then
            return (FX.Cfg and FX.Cfg.MobDodgeBossHeight) or 300
        end
        return (FX.Cfg and FX.Cfg.MobDodgeHeight) or 200
    end

    FX.DodgeOffset = function()
        local best = 0
        if FX.Enable and FX.Enable.SeaDodgeV3 and FX.SeaDodgeOffset then
            local ok, value = pcall(FX.SeaDodgeOffset)
            if ok and type(value) == "number" then best = math.max(best, value) end
        end
        -- R12: Katakuri V3 (Cake Prince专用) takes priority over Generic MobDodge
        -- Khi V3 active, skip MobDodge để tránh 2 state machine né đụng nhau
        if FX.IsKatakuriDangerV3 and FX.IsKatakuriDangerV3() then
            return best
        end
        if FX.MobDodgeOffset then
            local value = FX.MobDodgeOffset()
            if type(value) == "number" then best = math.max(best, value) end
        end
        return best
    end

    FX.StopMobDodge = function()
        local st = FX.MobDodge
        if not st then return end
        st.bodyToken = (st.bodyToken or 0) + 1
        FX.MobDodgeCleanupBody()
        st.untilT, st.bossUntil = 0, 0
        st.handled = setmetatable({}, { __mode = "k" })
        st.impulsed = setmetatable({}, { __mode = "k" })
    end
    FX.SeaDodge = { beast = nil, terror = nil, terrorHold = 0, prev = setmetatable({}, { __mode = "k" }), seen = setmetatable({}, { __mode = "k" }), candidates = setmetatable({}, { __mode = "k" }) }
    FX.SeaDodgeOffset = function()
        local E = FX.Enable
        if not (E and E.SeaDodgeV3) then return 0 end
        local sd, now, C = FX.SeaDodge, os.clock(), (FX.Cfg or {})
        if _G.SeaBeast1 and E.SeabeastDodge and _G.SeabeastDodge and sd.beast and now >= sd.beast.started then
            return C.SeaDodgeHeight or 600
        end
        if _G.TerrorShark and E.TerrorDodge and _G.TerrorDodge and (sd.terror or now < sd.terrorHold) then
            return C.SeaDodgeTerrorUp or 200
        end
        return 0
    end
    FX.SeaDodgeTick = function()
        local E, sd, C = FX.Enable, FX.SeaDodge, (FX.Cfg or {})
        local now = os.clock()

        -- Sea Beast: observe the two animation IDs already used by this codebase.
        if _G.SeaBeast1 and E.SeabeastDodge and _G.SeabeastDodge then
            local current = setmetatable({}, { __mode = "k" })
            local trackQueryFailed = false
            local seaFolder = workspace:FindFirstChild("SeaBeasts")
            if seaFolder then
                for _, beast in ipairs(seaFolder:GetChildren()) do
                    if beast.Name == "SeaBeast1" then
                        local hum = beast:FindFirstChildOfClass("Humanoid")
                        if hum then
                            local okTracks, tracks = pcall(hum.GetPlayingAnimationTracks, hum)
                            if not okTracks then
                                trackQueryFailed = true
                            else
                                for _, track in ipairs(tracks) do
                                    local animationId = tostring(track.Animation and track.Animation.AnimationId or "")
                                    if animationId == "rbxassetid://8708221792" or animationId == "rbxassetid://8708222556" then
                                        current[track] = true
                                        if not sd.prev[track] and not sd.beast then
                                            local delay = (animationId == "rbxassetid://8708222556")
                                                and (C.SeaDodgeBeastDelayA or 0.7)
                                                or (C.SeaDodgeBeastDelayB or 1.9)
                                            sd.beast = { tr = track, started = now + delay }
                                            if FX.TraceAdd then pcall(FX.TraceAdd, "SEA_DODGE_BEAST", animationId, tostring(delay)) end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
            sd.prev = current

            if trackQueryFailed and not sd.beast and FX.IsSeabeastDanger and FX.IsSeabeastDanger() then
                sd.beast = { tr = nil, started = now }
                if FX.TraceAdd then pcall(FX.TraceAdd, "SEA_DODGE_BEAST", "fallback", "track-query-failed") end
            end

            local beastState = sd.beast
            if beastState and now >= beastState.started then
                local trackEnded = beastState.tr ~= nil and not beastState.tr.IsPlaying
                local fallbackEnded = beastState.tr == nil and not (FX.IsSeabeastDanger and FX.IsSeabeastDanger())
                local timedOut = now - beastState.started >= (C.SeaDodgeBeastHold or 10)
                if trackEnded or fallbackEnded or timedOut then
                    sd.beast = nil
                end
            end
        else
            sd.beast = nil
            sd.prev = setmetatable({}, { __mode = "k" })
        end

        -- Terrorshark: retain newly-created warning parts briefly so an effect that
        -- arrives just before the shark model can still be associated with that shark.
        if _G.TerrorShark and E.TerrorDodge and _G.TerrorDodge then
            local enemies = workspace:FindFirstChild("Enemies")
            local terror = enemies and enemies:FindFirstChild("Terrorshark")
            local terrorRoot = terror and terror:FindFirstChild("HumanoidRootPart")
            local worldOrigin = workspace:FindFirstChild("_WorldOrigin")

            if worldOrigin then
                for _, effect in ipairs(worldOrigin:GetChildren()) do
                    if effect:IsA("BasePart")
                        and (effect.Name == "SharkSplash" or effect.Name == "ChargeUp")
                        and not sd.seen[effect] then
                        sd.seen[effect] = true
                        sd.candidates[effect] = now
                    end
                end
            end

            for effect, createdAt in pairs(sd.candidates) do
                if not effect.Parent or now - createdAt > (C.SeaDodgeTerrorCandidateTTL or 5) then
                    sd.candidates[effect] = nil
                elseif terrorRoot and not sd.terror
                    and (terrorRoot.Position - effect.Position).Magnitude < (C.SeaDodgeTerrorNear or 20) then
                    sd.terror = { part = effect, t0 = now }
                    sd.candidates[effect] = nil
                    if FX.TraceAdd then pcall(FX.TraceAdd, "SEA_DODGE_TERROR", effect.Name, "start") end
                end
            end

            local terrorState = sd.terror
            if terrorState and ((not terrorState.part) or (not terrorState.part.Parent)
                or now - terrorState.t0 > (C.SeaDodgeTerrorHold or 14)) then
                sd.terrorHold = now + (C.SeaDodgeTerrorExtra or 2.5)
                sd.terror = nil
            end
        else
            sd.terror = nil
            sd.terrorHold = 0
            sd.candidates = setmetatable({}, { __mode = "k" })
        end
    end
    FX.Harpoon = { last = 0 }
    FX.HarpoonBoat = function()
        local boats = workspace:FindFirstChild("Boats")
        if not boats then return nil end
