    FX.HarpoonHeart = function()
        local map = workspace:FindFirstChild("Map")
        local fh = map and map:FindFirstChild("FrozenHeart")
        if not fh then return nil, nil end
        local core = fh:FindFirstChild("Inside") or fh:FindFirstChild("Cube") or fh:FindFirstChild("Hitbox") or fh.PrimaryPart or fh:FindFirstChildWhichIsA("BasePart", true)
        local cf = core and core.CFrame or fh:GetPivot()
        return cf.Position, fh
    end
    FX.HarpoonAngles = function(harpoonFolder, targetPos)
        local seat = harpoonFolder:FindFirstChild("Seat")
        local baseCFrame
        if seat and seat:FindFirstChild("BoatWeld") and seat.BoatWeld.Part0 then
            baseCFrame = seat.BoatWeld.Part0.CFrame
        elseif seat and seat:IsA("BasePart") then
            baseCFrame = seat.CFrame
        else
            baseCFrame = harpoonFolder:GetPivot()
        end
        local l = baseCFrame:PointToObjectSpace(targetPos)
        local yaw = math.atan2(l.X, -l.Z)
        local x = math.sqrt(l.X ^ 2 + l.Z ^ 2)
        local y = l.Y
        local v, g = 400, workspace.Gravity
        local root = v ^ 4 - g * (g * x ^ 2 + 2 * y * v ^ 2)
        local pitch
        if root >= 0 then pitch = math.atan2(v ^ 2 - math.sqrt(root), g * x) else pitch = math.atan2(y, x) end
        return math.clamp(pitch, -0.17453292519943295, 0.7853981633974483), math.clamp(yaw, -1.1344640137963142, 1.1344640137963142)
    end
    FX.HarpoonTick = function()
        if not (FX.Enable and FX.Enable.LeviHarpoon and _G.ShootHeart) then return end
        local heartPos, fh = FX.HarpoonHeart()
        if not heartPos then return end
        local inside = fh:FindFirstChild("Inside")
        if inside and inside:GetAttribute("Harpooned") then return end
        local char = plr.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum or not hum.Sit then return end
        local boat = FX.HarpoonBoat()
        local hf = boat and boat:FindFirstChild("Harpoon")
        local hs = hf and hf:FindFirstChild("Seat")
        if not hs or hum.SeatPart ~= hs then return end
        local now = os.clock()
        if now - FX.Harpoon.last < ((FX.Cfg and FX.Cfg.HarpoonGap) or 1) then return end
        FX.Harpoon.last = now
        local pitch, yaw = FX.HarpoonAngles(hf, heartPos)
        local bw, cw = hs:FindFirstChild("BoatWeld"), hs:FindFirstChild("CannonWeld")
        if bw then pcall(function() bw.C0 = CFrame.Angles(0, yaw, 0) bw.C1 = CFrame.Angles(0, yaw * 2, 0) end) end
        if cw then pcall(function()
            local v21 = math.max(pitch - 0.4363323129985824, 0) / 0.6108652381980153 * 2.5
