    FX.DIM = { minutes = 5 }
    FX.DIM.Timer = { state = "idle", total = 0, endAt = 0, left = 0 }
    FX.DIM.Watch = { state = "idle", startAt = 0, accum = 0, laps = {} }
    FX.DIM.Fmt = function(sec)
        sec = math.max(0, math.floor((tonumber(sec) or 0) + 0.0001))
        return string.format("%d:%02d", math.floor(sec / 60), sec % 60)
    end
    FX.DIM.TimerLeft = function()
        local t = FX.DIM.Timer
        if t.state == "run" then return math.max(0, t.endAt - os.clock()) end
        if t.state == "pause" then return t.left end
        return 0
    end
    FX.DIM.TimerStart = function(minutes)
        local t = FX.DIM.Timer
        t.total = math.clamp(math.floor((tonumber(minutes) or 5) * 60 + 0.5), 1, 3600)
        t.endAt = os.clock() + t.total
        t.left = t.total
        t.state = "run"
        if FX.TraceAdd then pcall(FX.TraceAdd, "DIM_TIMER", "start", tostring(t.total)) end
    end
    FX.DIM.TimerPause = function()
        local t = FX.DIM.Timer
        if t.state == "run" then t.left = math.max(0, t.endAt - os.clock()) t.state = "pause" end
    end
    FX.DIM.TimerResume = function()
        local t = FX.DIM.Timer
        if t.state == "pause" then t.endAt = os.clock() + t.left t.state = "run" end
    end
    FX.DIM.TimerAdd = function(sec)
        local t = FX.DIM.Timer
        if t.state == "run" then t.endAt = t.endAt + sec t.total = t.total + sec
        elseif t.state == "pause" then t.left = t.left + sec t.total = t.total + sec end
    end
    FX.DIM.TimerStop = function()
        FX.DIM.Timer.state = "idle"
    end
    FX.DIM.WatchElapsed = function()
        local w = FX.DIM.Watch
        return w.accum + ((w.state == "run") and (os.clock() - w.startAt) or 0)
    end
    FX.DIM.WatchToggle = function()
        local w = FX.DIM.Watch
        if w.state == "run" then
            w.accum = w.accum + (os.clock() - w.startAt)
            w.state = "pause"
        else
            w.startAt = os.clock()
            w.state = "run"
        end
    end
    FX.DIM.WatchLap = function()
        local w = FX.DIM.Watch
        if w.state ~= "idle" then
            table.insert(w.laps, 1, FX.DIM.WatchElapsed())
            if #w.laps > 3 then table.remove(w.laps) end
            local isl = FX.DIM.Island()
            if isl then pcall(function() isl:Notify({ Title = "Lap " .. #w.laps, Value = FX.DIM.Fmt(w.laps[1]), Duration = 1.5 }) end) end
        end
    end
    FX.DIM.WatchReset = function()
        local w = FX.DIM.Watch
        w.state, w.accum, w.startAt, w.laps = "idle", 0, 0, {}
    end
    FX.DIM.Island = function()
        local ok, isl = pcall(function() return Library.WindUI.Island end)
        return ok and isl or nil
    end
    FX.DIM.Acts = function()
        local out = {}
        local t, w = FX.DIM.Timer, FX.DIM.Watch
        if t.state ~= "idle" then
            out[#out + 1] = { kind = "timer", icon = "hourglass", text = FX.DIM.Fmt(FX.DIM.TimerLeft()), ring = FX.DIM.TimerLeft() / math.max(t.total, 1) }
        end
        if w.state ~= "idle" then
            out[#out + 1] = { kind = "stopwatch", icon = "timer", text = FX.DIM.Fmt(FX.DIM.WatchElapsed()), ring = (FX.DIM.WatchElapsed() % 60) / 60 }
        end
        if Library.MusicIsland ~= nil then
            out[#out + 1] = { kind = "media", icon = "music" }
        end
        return out
    end
    FX.DIM.Promote = function(sk)
