    FX.Stage = function(killed, bossAlive)
        if bossAlive then return 5 end
        local k = tonumber(killed) or 0
        if k < 100 then return 0 end
        if k < 200 then return 1 end
        if k < 300 then return 2 end
        if k < 400 then return 3 end
        if k < 500 then return 4 end
        return 5
