_G.FARMX.ApplyMode = function(Value)
        _G.SelectedFarmMode = Value
        _G.Level            = false
        _G.Auto_Cake_Prince = false
        _G.FarmTyrant       = false
        _G.AutoFarm_Bone    = false
        _G.ActiveFarm       = nil
        alreadyTeleported   = false
        teleporting         = false
        if Value == "None" then
            return
        elseif Value == "Farm Level" then
            _G.Level      = true
            _G.ActiveFarm = "Level"
            _G.AcceptQuestC = false
            _G.AcceptQuestB = false
        elseif Value == "Farm Cake Prince" then
            _G.Auto_Cake_Prince = true
            _G.ActiveFarm       = "CakePrince"
        elseif Value == "Farm Tyrant of Skies" then
            _G.FarmTyrant = true
            _G.ActiveFarm = "Tyrant"
        elseif Value == "Farm Bone" then
            _G.AutoFarm_Bone = true
            _G.ActiveFarm    = "Bone"
        end
        local fxA = _G.FARMX
        if fxA and fxA.Enable.AcceptAutoOn and fxA.Enable.AcceptUiMove and not fxA.AcceptTouched and not _G.AcceptQuest
            and (Value == "Farm Cake Prince" or Value == "Farm Bone" or Value == "Farm Tyrant of Skies") then
            fxA.AcceptSetting = true
            pcall(function() Library.Options["Main_AcceptQuests"]:SetValue(true) end)
            fxA.AcceptSetting = false
        end
end
