        end
        _G.AcceptQuest = Value
        _G.AcceptQuestC = Value
        _G.AcceptQuestB = Value
        _G.AcceptQuestBoss = Value
    end
})
end
QuestController = {
    CurrentQuest = "",
    CurrentQuestName = "",
    QuestConnection = nil,
}
QuestController.Set = function(self, data)
    self.CurrentQuest = (function()
        for i, _ in next, data.Progress do
            return i
        end
    end)()
    self.CurrentQuestName = data.InternalQuestName
end
QuestController.Reset = function(self)
    self.CurrentQuest = ""
    self.CurrentQuestName = ""
end
local questConnectOk = pcall(function()
    QuestController.QuestConnection = ReplicatedStorage.Remotes.QuestUpdate.OnClientEvent:Connect(function(a2, a3)
        local fxe = _G.FARMX
        if fxe then
            local ev = fxe.QuestEvents
            if not ev then
                ev = {}
                fxe.QuestEvents = ev
            end
            ev[#ev + 1] = { t = os.clock(), ty = typeof(a2), a3 = typeof(a3) }
            if #ev > 30 then table.remove(ev, 1) end
        end
        if a2 and typeof(a2) == "table" then
            QuestController.ResetAt = nil
            QuestController:Set(a2)
            return
        end
        if fxe and fxe.Enable.QuestLock then
            QuestController.ResetAt = QuestController.ResetAt or os.clock()
            return
        end
        QuestController:Reset()
    end)
end)
function GetQuestData()
    if questConnectOk and QuestController.QuestConnection then
        local fxg = _G.FARMX
        if QuestController.ResetAt and fxg then
            local dtR = os.clock() - QuestController.ResetAt
            local okG, visG = pcall(function() return plr.PlayerGui.Main.Quest.Visible end)
            if dtR >= fxg.Cfg.QuestResetMax or (dtR >= fxg.Cfg.QuestResetHold and not (okG and visG)) then
                QuestController.ResetAt = nil
                QuestController:Reset()
            end
        end
        return QuestController.CurrentQuest ~= ""
    end
    local ok, visible = pcall(function()
        return plr.PlayerGui.Main.Quest.Visible
    end)
    return ok and visible or false
end
alreadyTeleported = false
teleporting = false
if not _G.ChooseWP then _G.ChooseWP = "Melee" end
if not _G.SelectWeapon then
    pcall(function()
        for _, v in pairs(plr.Backpack:GetChildren()) do
            if v:IsA("Tool") and v.ToolTip == "Melee" then
                _G.SelectWeapon = v.Name
                break
            end
        end
    end)
end
do
    local function InSubmergedIsland()
        local char = plr.Character
        if not char then return false end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if not hrp then return false end
        local islandXZ = Vector3.new(11520.8017578125, 0, 9829.513671875)
        local playerXZ = Vector3.new(hrp.Position.X, 0, hrp.Position.Z)
        return (playerXZ - islandXZ).Magnitude < 2000
    end
    local function On(key)
        local f = _G.FARMX
        return not (f and f.Enable and f.Enable[key] == false)
    end
    local function Cfg(key, default)
        local f = _G.FARMX
        local v = f and f.Cfg and f.Cfg[key]
        if v == nil then return default end
        return v
    end
    local tFin = -1e9
    local function H(fn, ...)
        if not On("LevelIsland") then return end
        if fn == "Finish" then
            local nowF = os.clock()
            if nowF - tFin < 1.5 then return end
            tFin = nowF
        end
        local FXh = _G.FARMX
        local f = FXh and FXh.FH and FXh.FH[fn]
        if f then
            local ok, err = pcall(f, ...)
            if not ok and FXh.Log then FXh.Log("level-island", err) end
        end
    end
    local function IsPlayerModel(m)
        return game:GetService("Players"):GetPlayerFromCharacter(m) ~= nil
    end
    local LV = { lastLevel = nil, lastState = nil, lastNeed = nil, mode = nil, tDetect = 0, tFarm = 0, apDeadline = nil, tpAim = 0, tStart = -1e9 }
    local GuiC = { t = -1e9, enemy = nil, labels = nil, kills = 0, lows = nil, lastSt = nil }
    local function QuestMobLows()
        if GuiC.lows then return GuiC.lows end
        local lows = {}
        pcall(function()
            for _, qset in pairs(Quests) do
                if type(qset) == "table" then
                    for _, qd in pairs(qset) do
                        if type(qd) == "table" and type(qd.Task) == "table" then
                            for nm in pairs(qd.Task) do
                                if type(nm) == "string" then lows[string.lower(nm)] = true end
                            end
                        end
                    end
                end
            end
        end)
        GuiC.lows = lows
        return lows
    end
    local function QuestGuiRead(enemyName, questData)
        local fxg = _G.FARMX
        local okV, vis = pcall(function() return plr.PlayerGui.Main.Quest.Visible end)
        if not okV then
            if fxg and fxg.Log then fxg.Log("quest-gui", "khong doc duoc plr.PlayerGui.Main.Quest") end
            return "none", nil, nil
        end
        if not vis then
            GuiC.labels = nil
            GuiC.lastSt = "none"
            return "none", nil, nil
        end
        if not On("QuestGuiScan") then return "active", nil, nil end
        local now = os.clock()
        if not GuiC.labels or GuiC.enemy ~= enemyName or now - GuiC.t >= Cfg("QuestGuiTTL", 0.5) then
            GuiC.t = now
            GuiC.enemy = enemyName
            local labels = {}
            local okS, errS = pcall(function()
                for _, d in ipairs(plr.PlayerGui.Main.Quest:GetDescendants()) do
                    if d:IsA("TextLabel") or d:IsA("TextButton") then labels[#labels + 1] = d end
                end
            end)
            if not okS and fxg and fxg.Log then fxg.Log("quest-gui", errS) end
            GuiC.labels = labels
        end
        local texts = {}
        pcall(function()
            for _, lb in ipairs(GuiC.labels) do
                local tx = lb.Text
                if type(tx) == "string" and tx ~= "" then texts[#texts + 1] = tx end
            end
        end)
        local cur, need
        for _, tx in ipairs(texts) do
            local a, b = string.match(tx, "^%s*(%d+)%s*/%s*(%d+)%s*$")
            if a then cur, need = tonumber(a), tonumber(b) break end
        end
        if not cur then
            for _, tx in ipairs(texts) do
                local a, b = string.match(tx, "%((%d+)%s*/%s*(%d+)%)")
                if a then cur, need = tonumber(a), tonumber(b) break end
            end
        end
        if not cur then
            for _, tx in ipairs(texts) do
                local a, b = string.match(tx, "(%d+)%s*/%s*(%d+)")
                if a then cur, need = tonumber(a), tonumber(b) break end
            end
        end
        if not need then
            for _, tx in ipairs(texts) do
                local n = string.match(tx, "[Dd]efeat%s+(%d+)%s")
                if n then need = tonumber(n) break end
            end
        end
        if not need and questData then
            pcall(function() need = Quests[questData[3]][questData[2]].Task[enemyName] end)
            if type(need) ~= "number" then need = nil end
        end
        local lowEnemy = string.lower(enemyName)
        local hasMob, otherMob = false, false
        for _, tx in ipairs(texts) do
            if string.find(string.lower(tx), lowEnemy, 1, true) then hasMob = true break end
        end
        if not hasMob then
            local lows = QuestMobLows()
            for _, tx in ipairs(texts) do
                local lt = string.lower(tx)
                for nm in pairs(lows) do
                    if nm ~= lowEnemy and string.find(lt, nm, 1, true) then otherMob = true break end
                end
                if otherMob then break end
            end
        end
        local state = "active"
        if otherMob then
            state = "wrong"
        elseif cur and need and need > 0 and cur >= need then
            state = "done"
        elseif not cur and need and need > 0 and GuiC.kills >= need then
            state = "done"
        end
        if state == "done" or state == "wrong" then
            if GuiC.cand == state then
                GuiC.candN = (GuiC.candN or 0) + 1
            else
                GuiC.cand, GuiC.candN = state, 1
            end
            if GuiC.candN < (Cfg("QuestStateConfirm", 2)) then state = "active" end
        else
            GuiC.cand, GuiC.candN = nil, 0
        end
        if GuiC.lastSt ~= state and fxg and fxg.Cfg and fxg.Cfg.Debug and fxg.Log then
            local parts = {}
            for _, lb in ipairs(GuiC.labels) do
                local okD, line = pcall(function() return lb:GetFullName() .. " [" .. lb.ClassName .. "] " .. string.sub(lb.Text, 1, 120) end)
                if okD then parts[#parts + 1] = line end
            end
            fxg.Log("quest-gui", "state=" .. state .. " cur=" .. tostring(cur) .. " need=" .. tostring(need) .. "\n" .. table.concat(parts, "\n"))
        end
        GuiC.lastSt = state
        return state, cur, need
    end
    if _G.FARMX then
        _G.FARMX.QuestLog = _G.FARMX.QuestLog or {}
        _G.FARMX.QLogAdd = function(reason, vis, hasQ, cur, need, since)
            local q = _G.FARMX.QuestLog
            q[#q + 1] = { t = os.clock(), reason = reason, vis = vis, hasQ = hasQ, cur = cur, need = need, since = since }
            if #q > 30 then table.remove(q, 1) end
        end
        _G.FARMX.QuestLogText = function()
            local out = {}
            for _, r in ipairs(_G.FARMX.QuestLog) do
                out[#out + 1] = string.format("%.1f %s vis=%s hasQ=%s cur=%s need=%s since=%s", r.t, tostring(r.reason), tostring(r.vis), tostring(r.hasQ), tostring(r.cur), tostring(r.need), tostring(r.since))
            end
            return table.concat(out, "\n")
        end
    end
    local function LvDetect(label, dist, content)
        local now = os.clock()
        if LV.mode == "detect" and now - LV.tDetect < 0.2 then return end
        LV.tDetect, LV.mode = now, "detect"
        H("Detect", "Level", { Title = "Going to " .. tostring(label), Content = content, Distance = dist })
    end
    local function LvFarm(enemy, level, cur, need, text)
        local now = os.clock()
        if LV.mode == "farm" and now - LV.tFarm < 0.3 then return end
        LV.tFarm, LV.mode = now, "farm"
        local hasProg = cur ~= nil and need ~= nil and need > 0
        local fxq = _G.FARMX
        local live = fxq and fxq.Enable.QuestCardLive
        local content
        if live then
            content = (need and need > 0) and string.format("Lv %d  ·  Defeat %d", level, need) or string.format("Lv %d", level)
        else
            content = string.format("Lv %d  ·  %s", level, text or "Killing")
        end
        H("FarmData", "Level", {
            Title = "Farming " .. tostring(enemy),
            Content = content,
            Value = hasProg and string.format("%d/%d", cur, need) or nil,
            Unit = live and "kills" or "quest",
            Left = "Lv " .. tostring(level),
            Right = hasProg and (live and (tostring(math.floor(100 * math.clamp(cur / need, 0, 1))) .. "%") or (tostring(need - cur) .. " left")) or "",
            Progress = hasProg and math.clamp(cur / need, 0, 1) or nil,
        })
    end
    task.spawn(function()
        while task.wait(Sec) do
            if _G.Level then
                local okLv, errLv = pcall(function()
                    local char = plr.Character or plr.CharacterAdded:Wait()
                    local Root = char:WaitForChild("HumanoidRootPart")
                    if not Root then return end
                    local level = plr.Data.Level.Value
                    if LV.lastLevel and level > LV.lastLevel then
                        H("Finish", "Level", { Title = "Level " .. tostring(level), Content = "Level up" })
                    end
                    LV.lastLevel = level
                    local inSub = InSubmergedIsland()
                    if level >= 2600 and not inSub and not teleporting and not alreadyTeleported then
                        teleporting = true
                        local npcPos = CFrame.new(-16269.7041, 25.2288494, 1373.65955)
                        local attempts = 0
                        repeat
                            task.wait(Sec)
                            _tp(npcPos)
                            attempts = attempts + 1
                            LvDetect("Submerged Island", (Root.Position - npcPos.Position).Magnitude, "Submarine worker")
                        until not _G.Level or (Root.Position - npcPos.Position).Magnitude <= 8 or attempts > 20
                        if not _G.Level then
                            teleporting = false
                            return
                        end
                        task.wait(1)
                        pcall(function()
                            local args = { "TravelToSubmergedIsland" }
                            game:GetService("ReplicatedStorage").Modules.Net:FindFirstChild("RF/SubmarineWorkerSpeak"):InvokeServer(unpack(args))
                        end)
                        local timeout = tick()
                        repeat
                            task.wait(0.5)
                            local currentInSub = InSubmergedIsland()
                            local farFromNPC = (Root.Position - npcPos.Position).Magnitude > 50
                            if currentInSub or farFromNPC then break end
                        until not _G.Level or tick() - timeout > 15
                        task.wait(2)
                        alreadyTeleported = true
                        teleporting = false
                    elseif inSub or level < 2600 then
                        alreadyTeleported = true
                        teleporting = false
                        local questData = QuestNeta()
                        local fxq5 = _G.FARMX
                        if fxq5 and fxq5.Enable.QuestLock then
                            if GetQuestData() then
                                if LV.qlock then
                                    questData = LV.qlock
                                end
                            else
                                LV.qlock = nil
                            end
                        end
                        if not questData or not questData[1] then
                            task.wait(1)
                            return
                        end
                        local enemyName = questData[1]
                        local st, cur, need = QuestGuiRead(enemyName, questData)
                        local hasQ = GetQuestData()
                        if LV.lastState == "active" and (st == "done" or st == "none") then
                            H("Finish", "Level", { Title = "Quest complete", Content = tostring(enemyName) .. "  x" .. tostring(LV.lastNeed or "") })
                        end
                        LV.lastState = st
                        if st == "active" then
                            LV.apDeadline = nil
                            if need and need > 0 then LV.lastNeed = need end
                        end
                        if st ~= "active" and not hasQ then
                            local aimCF = questData[6] or (GetMobFarmPosition and GetMobFarmPosition(enemyName)) or nil
                            local nowA = os.clock()
                            local distA = aimCF and (Root.Position - aimCF.Position).Magnitude or 0
                            if not LV.apDeadline then
                                local spd = (type(Settings) == "table" and Settings["Tween Speed"]) or 180
                                LV.apDeadline = nowA + distA / spd + Cfg("QuestApproachPad", 15)
                            end
                            if aimCF and distA > Cfg("QuestArriveRadius", 12) and nowA < LV.apDeadline then
                                if nowA - LV.tpAim >= 0.3 then
                                    LV.tpAim = nowA
                                    _tp(aimCF)
                                end
                                LvDetect("Quest NPC", distA, "Lv " .. tostring(level) .. "  ·  " .. tostring(enemyName))
                                return
                            end
                            task.wait(0.6)
                            local fxm = _G.FARMX
                            local lockOn = fxm and fxm.Enable.QuestLock
                            local okVis, visQ = pcall(function() return plr.PlayerGui.Main.Quest.Visible end)
                            local sinceStart = os.clock() - LV.tStart
                            if lockOn and okVis and visQ == true and sinceStart < Cfg("QuestMinHold", 20) and not GetQuestData() then
                                if fxm.QLogAdd then fxm.QLogAdd("lock", visQ, false, cur, need, sinceStart) end
                            elseif not GetQuestData() and os.clock() - LV.tStart >= Cfg("StartQuestGap", 1.5) then
                                if lockOn and fxm.QLogAdd then fxm.QLogAdd("accept", okVis and visQ or nil, false, cur, need, sinceStart) end
                                LV.tStart = os.clock()
                                if lockOn then LV.qlock = questData end
                                pcall(function()
                                    replicated.Remotes.CommF_:InvokeServer("StartQuest", questData[3], questData[2])
                                end)
                                GuiC.kills = 0
                            end
                            if lockOn then
                                local tw0 = os.clock()
                                repeat
                                    task.wait(0.2)
                                    local okV2, vis2 = pcall(function() return plr.PlayerGui.Main.Quest.Visible end)
                                until GetQuestData() or (okV2 and vis2 == true) or os.clock() - tw0 >= Cfg("QuestAcceptWait", 3)
                            else
                                task.wait(0.6)
                            end
                            LV.apDeadline = nil
                            st, cur, need = QuestGuiRead(enemyName, questData)
                            LV.lastState = st
                        end
                        local target = nil
                        local best = math.huge
                        for _, v in pairs(workspace.Enemies:GetChildren()) do
                            if v.Name == enemyName and v:FindFirstChild("Humanoid") and v:FindFirstChild("HumanoidRootPart") and Attack.Alive(v) and not IsPlayerModel(v) then
                                local d = (v.HumanoidRootPart.Position - Root.Position).Magnitude
                                if d < best then best = d target = v end
                            end
                        end
                        if target then
                            repeat
                                task.wait(Sec)
                                local hrp = target:FindFirstChild("HumanoidRootPart")
                                local myRoot = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                                if hrp then
                                    _tp(GetSpinCFrame(hrp, GetFarmOffset()))
                                    if myRoot then
                                        local fxq = _G.FARMX
                                        if fxq and fxq.Enable.QuestCardLive then
                                            if os.clock() - (LV.tGuiRef or -1e9) >= 0.5 then
                                                LV.tGuiRef = os.clock()
                                                local _, cR, nR = QuestGuiRead(enemyName, questData)
                                                if cR ~= nil then
                                                    cur, need = cR, nR
                                                elseif nR then
                                                    need = nR
                                                    cur = cur or GuiC.kills
                                                end
                                            end
                                            LvFarm(enemyName, level, cur, need, "Killing")
                                        elseif (myRoot.Position - hrp.Position).Magnitude < 70 then
                                            LvFarm(enemyName, level, cur, need, "Killing")
                                        end
                                    end
                                end
                                Attack.Kill(target, _G.Level)
                            until not _G.Level or not target.Parent or not Attack.Alive(target)
                            local hum = target:FindFirstChildOfClass("Humanoid")
                            if _G.Level and st == "active" and (not target.Parent or not hum or hum.Health <= 0) then
                                GuiC.kills = GuiC.kills + 1
                            end
                            local s2, c2, n2 = QuestGuiRead(enemyName, questData)
                            LV.lastState = s2
                            if s2 == "active" and n2 and n2 > 0 then LV.lastNeed = n2 end
                            if c2 ~= nil and n2 and _G.FARMX and _G.FARMX.Enable.QuestCardLive then LvFarm(enemyName, level, c2, n2, "Killing") end
                        else
                            local spawnCF = GetMobFarmPosition and GetMobFarmPosition(enemyName) or nil
                            if not spawnCF then
                                pcall(function()
                                    for _, sp in pairs(workspace["_WorldOrigin"].EnemySpawns:GetChildren()) do
                                        if string.find(sp.Name, enemyName) then
                                            spawnCF = sp.CFrame
                                            break
                                        end
                                    end
                                end)
                            end
                            if not spawnCF then
                                pcall(function()
                                    for _, v in pairs(replicated.Enemies:GetChildren()) do
                                        if v.Name == enemyName then
                                            spawnCF = questData[6]
                                            break
                                        end
                                    end
                                end)
                            end
                            local goCF = spawnCF and (spawnCF * CFrame.new(0, 25, 0)) or questData[6]
                            if goCF then
                                local FXl = _G.FARMX
                                local dist = (Root.Position - goCF.Position).Magnitude
                                if not (FXl and FXl.Enable.LevelStay) or dist > FXl.Cfg.LevelStayRadius then
                                    _tp(goCF)
                                    if _G.FARMX and _G.FARMX.Enable.QuestCardLive then LvFarm(enemyName, level, cur, need, "Killing") else LvDetect(enemyName .. " spawn", dist, "Lv " .. tostring(level)) end
                                else
                                    LvFarm(enemyName, level, cur, need, (_G.FARMX and _G.FARMX.Enable.QuestCardLive) and "Killing" or "Waiting spawn")
                                end
                            end
                            task.wait(0.3)
                        end
                    end
                end)
                if not okLv and _G.FARMX and _G.FARMX.Log then _G.FARMX.Log("level", errLv) end
                if okLv then
                    LV.errN = 0
                else
                    LV.errN = (LV.errN or 0) + 1
                    if LV.errN >= 3 and os.clock() - (LV.tErr or -1e9) >= 10 and On("StatusPill") then
                        LV.tErr = os.clock()
                        local fhE = _G.FARMX and _G.FARMX.FH
                        if fhE and fhE.NotifyRed then fhE.NotifyRed({ Text = "Level farm error" }) end
                    end
                end
            else
                teleporting = false
                alreadyTeleported = false
                LV.lastState = nil
                LV.apDeadline = nil
                if LV.mode then
                    LV.mode = nil
                    H("IslandStop", "Level")
                end
            end
        end
    end)
