do
    local FX = _G.FARMX
    FX.ChestState = { list = nil, t = 0, goal = nil, issued = 0, eta = 0 }
    FX.ChestStep = function()
        local char = plr.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local st = FX.ChestState
        local now = os.clock()
        if not st.list or now - st.t > FX.Cfg.ChestCacheTTL then
            st.list = game:GetService("CollectionService"):GetTagged("_ChestTagged")
            st.t = now
        end
        local best, bestD
        for _, c in ipairs(st.list) do
            if c.Parent and not c:GetAttribute("IsDisabled") and (not SelectedIsland or c:IsDescendantOf(SelectedIsland)) then
                local d = (c:GetPivot().Position - hrp.Position).Magnitude
                if not bestD or d < bestD then best, bestD = c, d end
            end
        end
        if not best then
            st.goal = nil
            return
        end
        if st.goal ~= best or now - st.issued > st.eta then
            st.goal = best
            st.issued = now
            st.eta = bestD / (Settings["Tween Speed"] or 180) + FX.Cfg.WalkTimeoutPad
            _tp(best:GetPivot())
        end
    end
end
spawn(function()
  while wait(Sec) do
    if _G.AutoFarmChest and _G.FARMX.Enable.Chest then
      if _G.FARMX.IsTop("Chest") and not (PFS_ShouldYieldBoss and PFS_ShouldYieldBoss()) then
        local ok, err = pcall(_G.FARMX.ChestStep)
        if not ok then _G.FARMX.Log("chest", err) end
      end
    elseif _G.AutoFarmChest then
      pcall(function()
        local CollectionService = game:GetService("CollectionService")
        local Players = game:GetService("Players")
        local Player = Players.LocalPlayer
        local Character = Player.Character or Player.CharacterAdded:Wait()
        if not Character then return end
        local Position = Character:GetPivot().Position
        local Chests = CollectionService:GetTagged("_ChestTagged")
        local Distance, Nearest = math.huge, nil
        for i = 1, #Chests do
          local Chest = Chests[i]
          local Magnitude = (Chest:GetPivot().Position - Position).Magnitude
          if not SelectedIsland or Chest:IsDescendantOf(SelectedIsland) then
            if not Chest:GetAttribute("IsDisabled") and Magnitude < Distance then
              Distance = Magnitude
              Nearest = Chest
            end
          end
        end
      if Nearest then _tp(Nearest:GetPivot()) end
      end)
    end
  end
end)
