AuraSkin = function(HakiID)
  local args = {[1] = {["StorageName"] = HakiID,["Type"] = "AuraSkin",["Context"] = "Equip"}};
  replicated:WaitForChild("Modules"):WaitForChild("Net"):WaitForChild("RF/FruitCustomizerRF"):InvokeServer(unpack(args));
end;
VaildColor = function(Part)
  if Part and Part.BrickColor then return (tostring(Part.BrickColor) == "Lime green") end;
end;
HakiCalculate = function(Part)
  local ID = {["Really red"] = "Pure Red";["Oyster"] = "Snow White";["Hot pink"] = "Winter Sky";};
  if Part and Part.BrickColor then return (ID[tostring(Part.BrickColor)])end;
end;
spawn(function()
  while wait(Sec) do
    if _G.AutoUnHaki then
      pcall(function()
        local Summoner = workspace.Map["Boat Castle"]:FindFirstChild("Summoner");
        if Summoner and Summoner:FindFirstChild("Circle") then
          for i,v in pairs(Summoner:FindFirstChild("Circle"):GetChildren()) do
            if v.Name == "Part" then
            local TogglesPart = v:FindFirstChild("Part");
              if VaildColor(TogglesPart) == false then
                AuraSkin(HakiCalculate(v));
                repeat wait() _tp(v.CFrame) until VaildColor(TogglesPart) == true or not _G.AutoUnHaki;
              end
            end
          end
        end
      end)
    end
  end
end)
UIX.Paragraph(Tabs.Main, "Para_40", {Title = "Farming Cake", Content = ""})
do
    local fxCP = _G.FARMX
    if fxCP then
        fxCP.CakePortal = function(silent)
            if fxCP.Sea ~= "Sea3" then return end
            if os.clock() < (fxCP._NextCakeCheck or 0) then return end
            fxCP._NextCakeCheck = os.clock() + (fxCP.Cfg.KatakuriSummonGap or 12)
            local npcPos = nil
            pcall(function()
                local list = {}
                for _, v in pairs(workspace:GetChildren()) do if v.Name == "drip_mama" then table.insert(list, v) end end
                for _, v in pairs(game:GetService("ReplicatedStorage"):GetChildren()) do if v.Name == "drip_mama" then table.insert(list, v) end end
                for _, v in ipairs(list) do
                    local hrp = v:FindFirstChild("HumanoidRootPart") or v:FindFirstChildWhichIsA("BasePart")
                    if hrp then npcPos = (hrp:IsA("BasePart") and hrp.Position) or (hrp.CFrame and hrp.CFrame.Position) break end
                end
            end)
            local _, _, root = pcall(function()
                local c = plr.Character
                return c, c:FindFirstChild("HumanoidRootPart")
            end)
            local myRoot = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if npcPos and myRoot and (npcPos - myRoot.Position).Magnitude > 45 and os.clock() >= (fxCP._NextCakeMove or 0) then
                fxCP._NextCakeMove = os.clock() + 15
                pcall(function()
                    if _tp then _tp(CFrame.new(npcPos)) end
                end)
                return
            end
            local ok, result = pcall(function()
                if fxCP.CachedInvoke then
                    return fxCP.CachedInvoke("CakePrinceSpawner", fxCP.Cfg.KatakuriSummonGap or 12, "CakePrinceSpawner")
                else
                    return game:GetService("ReplicatedStorage").Remotes.CommF_:InvokeServer("CakePrinceSpawner")
                end
            end)
            if ok and type(result) == "string" and result:find("open the portal now", 1, true) then
                local sent, reply = pcall(function()
                    return game:GetService("ReplicatedStorage").Remotes.CommF_:InvokeServer("CakePrinceSpawner")
                end)
                if not silent and fxCP.Log then fxCP.Log("cake-portal", "Cake Portal: sent=" .. tostring(sent) .. " reply=" .. tostring(reply)) end
            elseif not silent and fxCP.Log then
                fxCP.Log("cake-portal", "Cake Portal status: ok=" .. tostring(ok) .. " result=" .. tostring(result))
            end
        end
    end
end
spawn(function()
    while task.wait() do
        if _G.Auto_Cake_Prince and not _G.AutoRaidCastle then
            pcall(function()
                local player = game.Players.LocalPlayer
                local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                local questUI = player.PlayerGui.Main.Quest
                local enemies = workspace.Enemies
                local cakeMap = workspace.Map:FindFirstChild("CakeLoaf")
                local bigMirror = cakeMap and cakeMap:FindFirstChild("BigMirror")
                if not root then return end
                if _G.AcceptQuest and questUI and not questUI.Visible then
                    local questPos = CFrame.new(-1927.92, 37.8, -12842.54)
        local fxc = _G.FARMX
        local questArg = nil
        if fxc and fxc.Enable.CakeQuestByLevel then
            local okL, lvl = pcall(function() return plr.Data.Level.Value end)
            lvl = okL and tonumber(lvl) or 0
            if lvl >= 2275 then
                questArg = { "StartQuest", "CakeQuest2", 2 }
            elseif lvl >= 2250 then
                questArg = { "StartQuest", "CakeQuest2", 1 }
            elseif lvl >= 2225 then
                questArg = { "StartQuest", "CakeQuest1", 2 }
            else
                questArg = { "StartQuest", "CakeQuest1", 1 }
            end
            if questArg[2] == "CakeQuest1" then questPos = CFrame.new(-2021.32, 37.798, -12028.73) end
        end
        _tp(questPos)
        local walkT0, walkAbort = os.clock(), false
        local lastTpQ = os.clock()
        while (questPos.Position - root.Position).Magnitude > 50 do
            task.wait(0.2)
            if os.clock() - lastTpQ >= 1.5 then lastTpQ = os.clock(); _tp(questPos) end
            if fxc and fxc.Nav then fxc.Nav.Update("npc", "Cake Quest NPC", questPos.Position) end
            if fxc and fxc.Enable.CakeWalkGuard then
                local hrpN = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                if not _G.Auto_Cake_Prince or not hrpN or os.clock() - walkT0 >= fxc.Cfg.CakeQuestWalkTimeout then
                    walkAbort = true
                    break
                end
                root = hrpN
            end
        end
        local fxD3 = _G.FARMX
        local useQCv2 = fxD3 and fxD3.Enable and fxD3.Enable.QuestConfirmV2
        if not useQCv2 then
            if fxc and fxc.Nav then fxc.Nav.Clear("end") end
        end
        if walkAbort then return end
        if questArg == nil then
            local oldQuests = {
                [1] = {"StartQuest", "CakeQuest2", 2},
                [2] = {"StartQuest", "CakeQuest2", 1},
                [3] = {"StartQuest", "CakeQuest1", 1},
                [4] = {"StartQuest", "CakeQuest1", 2}
            }
            questArg = oldQuests[math.random(1, 4)]
        end
        pcall(function()
            game.ReplicatedStorage.Remotes.CommF_:InvokeServer(unpack(questArg))
        end)
        if useQCv2 then
            local cfT0 = os.clock()
            local confirmed = false
            while os.clock() - cfT0 < 3 do
                task.wait(0.2)
                local ok, vis = pcall(function() return player.PlayerGui.Main.Quest.Visible end)
                if ok and vis then confirmed = true break end
                if not confirmed then
                    local ok2, tq = pcall(function() return player.PlayerGui:FindFirstChild("TrackedQuestFrame") end)
                    if ok2 and tq then
                        local fr = tq:FindFirstChild("Frame", true)
                        local hd = fr and fr:FindFirstChild("header", true)
                        local l1 = hd and hd:FindFirstChild("textLabel", true)
                        local l2 = l1 and l1:FindFirstChild("textLabel", true)
                        local txt = l2 and l2.Text
                        if type(txt) == "string" and txt ~= "" and (txt:find("Cake") or txt:find("Cookie") or txt:find("Baking") or txt:find("Baker") or txt:find("Guard")) then
                            confirmed = true break
                        end
                    end
                end
            end
            if confirmed then
                if fxc and fxc.Nav then fxc.Nav.Clear("end") end
            else
                if fxD3.TraceAdd then fxD3.TraceAdd("QUEST_NOT_CONFIRMED", "CakeQuest", "3s") end
                if fxD3.IH and fxD3.IH.NotifyDot then pcall(fxD3.IH.NotifyDot, "y", "Cake Quest: chua xac nhan", 2) end
                return
            end
        else
            if fxc and fxc.Nav then fxc.Nav.Clear("end") end
        end
                end
                if not cakeMap then
                    if _G.FARMX and _G.FARMX.Enable.KatakuriSummon and _G.FARMX.CakePortal then
                        pcall(function() _G.FARMX.CakePortal(true) end)
                    end
                    _tp(CFrame.new(-2077, 252, -12373))
                    task.wait(2)
                    return
                end
                if bigMirror and (bigMirror.Other.Transparency == 0 or enemies:FindFirstChild("Cake Prince")) then
                    local boss = GetConnectionEnemies("Cake Prince")
                    if boss then
                        local fxB = _G.FARMX
                        local useV3 = fxB and fxB.Enable and fxB.Enable.KatakuriDodge and fxB.Enable.KatakuriDodgeV3 and fxB.IsKatakuriDangerV3
                        if useV3 then
                            local st = "ATTACK"
                            local clearT = nil
                            local lastLearn = 0
                            local function holdAt(cf)
                                local hr = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                                if hr and (hr.Position - cf.Position).Magnitude > 6 then pcall(_tp, cf) end
                            end
                            repeat task.wait()
                                if not _G.Auto_Cake_Prince then break end
                                if fxB.Enable.KillStopOnSwitch and fxB.NotOwner("CakePrince") then break end
                                if not boss.Parent or not Attack.Alive(boss) then break end
                                local bhrp = boss:FindFirstChild("HumanoidRootPart")
                                if not bhrp then break end
                                if fxB.KatakuriLearn and os.clock() - lastLearn > 0.25 then
                                    lastLearn = os.clock()
                                    pcall(fxB.KatakuriLearn)
                                end
                                local h = (fxB.Cfg and fxB.Cfg.KatakuriSafeHeight) or 80
                                local clearSec = (fxB.Cfg and fxB.Cfg.KatakuriClearSec) or 0.4
                                if fxB.IsKatakuriDangerV3() then
                                    if st ~= "UP" then
                                        st = "UP"
                                        if fxB.TraceAdd then fxB.TraceAdd("CAKE_DODGE_UP", "Cake Prince") end
                                    end
                                    clearT = nil
                                    holdAt(bhrp.CFrame * CFrame.new(0, h, 0))
                                elseif st == "UP" then
                                    clearT = clearT or os.clock()
                                    if os.clock() - clearT >= clearSec then
                                        st = "ATTACK"
                                        clearT = nil
                                        if fxB.TraceAdd then fxB.TraceAdd("CAKE_DODGE_DOWN", "Cake Prince") end
                                        holdAt(bhrp.CFrame * CFrame.new(4, 10, 10))
                                    else
                                        holdAt(bhrp.CFrame * CFrame.new(0, h, 0))
                                    end
                                else
                                    Attack.Kill2(boss, function() return _G.Auto_Cake_Prince == true end)
                                end
                            until not _G.Auto_Cake_Prince or (fxB.Enable.KillStopOnSwitch and fxB.NotOwner("CakePrince")) or not boss.Parent or not Attack.Alive(boss)
                        else
                            repeat task.wait()
                                Attack.Kill2(boss, function()
                                    local ownerFx = _G.FARMX
                                    return _G.Auto_Cake_Prince == true
                                        and not (ownerFx and ownerFx.Enable and ownerFx.Enable.KillStopOnSwitch
                                            and ownerFx.NotOwner and ownerFx.NotOwner("CakePrince"))
                                end)
                            until not _G.Auto_Cake_Prince or (fxB and fxB.Enable.KillStopOnSwitch and fxB.NotOwner("CakePrince")) or not boss.Parent or not Attack.Alive(boss)
                        end
                    else
                        _tp(CFrame.new(-2151.82, 149.32, -12404.91))
                    end
                else
                    local fxD = _G.FARMX
                    if not (fxD and fxD.Area and fxD.Dwell and fxD.SpawnHold and fxD.KillWatch) then return end
                    local near = fxD.Area.Near("CakePrince", math.huge)
                    local foundMob = near[1] and near[1].mob
                    if foundMob then
                        fxD.Dwell.Tick("CakePrince", #near)
                        if fxD.TraceAdd then fxD.TraceAdd("CAKE_KILL", foundMob.Name, near[1].dist) end
                        local stallT = os.clock()
                        repeat task.wait()
                            local k0 = os.clock()
                            Attack.Kill(foundMob, function()
                                local ownerFx = _G.FARMX
                                return _G.Auto_Cake_Prince == true
                                    and not (ownerFx and ownerFx.Enable and ownerFx.Enable.KillStopOnSwitch
                                        and ownerFx.NotOwner and ownerFx.NotOwner("CakePrince"))
                            end)
                            stallT = fxD.KillWatch(foundMob, stallT, os.clock() - k0)
                        until not _G.Auto_Cake_Prince or (fxD.Enable.KillStopOnSwitch and fxD.NotOwner("CakePrince")) or not foundMob.Parent or (not Attack.Alive(foundMob)) or (bigMirror and bigMirror.Other.Transparency == 0)
                    else
                        local fbC = CFrame.new(-2077, 252, -12373)
                        if not fxD.SpawnHold("CakePrince", fbC, false) then
                            fxD.Dwell.Reset("CakePrince")
                        elseif fxD.Dwell.Tick("CakePrince", 0) then
                            fxD.SpawnHold("CakePrince", fbC, true)
                            fxD.Dwell.Reset("CakePrince")
                        end
                    end
                end
            end)
        end
    end
end)
