    SQ.Key = function(e) return "Sea1/" .. e.island .. "/" .. e.name end
    SQ.IsDone = function(p, key)
        local v = p[key]
        if v == true then return true end
        return type(v) == "table" and v.Completed == true
    end
    SQ.Sea1 = function() return game.PlaceId == 2753915549 or game.PlaceId == 85211729168715 end
    SQ.Log = function(k, m) if FX.Log then pcall(FX.Log, "secret-" .. k, m) end end
    SQ.Note = function(key, text, level)
        local now = os.clock()
        if now - (SQ.Notified[key] or -1e9) < FX.Cfg.SQNotifyGap then return end
        SQ.Notified[key] = now
        local fh = FX.FH
        if not fh then return end
        if level == "red" and fh.NotifyRed then fh.NotifyRed({ Text = text })
        elseif level == "yellow" and fh.NotifyYellow then fh.NotifyYellow({ Text = text })
        elseif fh.NotifyGreen then fh.NotifyGreen({ Text = text }) end
    end
    SQ.Recount = function()
        local p = SQ.Prog
        if type(p) ~= "table" then return end
        local n, fresh = 0, nil
        for i = 1, #SQ.List do
            local e = SQ.List[i]
            if SQ.IsDone(p, SQ.Key(e)) then
                n = n + 1
                if not SQ.DoneSet[e.name] then
                    SQ.DoneSet[e.name] = true
                    if SQ.Counted then fresh = e end
                end
            end
        end
        SQ.Done = math.min(n, #SQ.List)
        SQ.Counted = true
        if fresh then SQ.Fresh = fresh end
        if not SQ.ShapeLogged then
            SQ.ShapeLogged = true
            local k1
            for k, v in pairs(p) do k1 = k SQ.Log("shape", tostring(k) .. " -> " .. typeof(v)) break end
            if k1 == nil then SQ.Log("shape", "bang tien do rong") end
        end
    end
    SQ.Progress = function(force)
        local now = os.clock()
        if not force and now - SQ.ProgT < FX.Cfg.SQProgressTTL then return SQ.Prog end
        if now < SQ.ProgNext then return SQ.Prog end
        SQ.ProgT = now
        SQ.ProgNext = now + FX.Cfg.SQProgressGap
        local ok, res = pcall(function()
            return game:GetService("ReplicatedStorage").Modules.Net["RF/RequestBonusMomentReplication"]:InvokeServer({ Type = "GetMomentProgress" })
        end)
        if not ok then
            SQ.ProgFail = SQ.ProgFail + 1
            SQ.Status = "REMOTE_FAILED"
            SQ.ProgNext = now + math.min(60, FX.Cfg.SQProgressGap * (2 ^ SQ.ProgFail))
            SQ.Log("progress", tostring(res))
            return SQ.Prog
        end
        if type(res) ~= "table" or type(res.Data) ~= "table" then
            SQ.ProgFail = SQ.ProgFail + 1
            SQ.Status = "MALFORMED"
            SQ.ProgNext = now + math.min(60, FX.Cfg.SQProgressGap * (2 ^ SQ.ProgFail))
            SQ.Log("progress", "response khong phai bang co Data")
            return SQ.Prog
        end
        SQ.ProgFail = 0
        SQ.Status = "OK"
        SQ.Prog = res.Data
        SQ.Recount()
        return SQ.Prog
    end
    SQ.Moment = function(name)
        if SQ.CtlErrT and os.clock() - SQ.CtlErrT < 30 then return nil end
        local ok, r = pcall(function()
            local c = SQ.Ctl
            if c == nil then
                c = require(game:GetService("ReplicatedStorage").Controllers.BonusMomentsController)
                SQ.Ctl = c
            end
            return c:GetLoadedMoments()[name]
        end)
        if ok then SQ.CtlErrT = nil return r end
        SQ.CtlErrT = os.clock()
        SQ.Log("moment", tostring(r))
        return nil
    end
    SQ.IslandPos = function(island)
        if SQ.Isl[island] then return SQ.Isl[island] end
        local ok, r = pcall(function()
            local map = require(game:GetService("ReplicatedStorage").Definitions.Map).findCurrentMap()
            local islands = map and map.Islands or {}
            for _, isl in pairs(islands) do
                if isl.Index.Key == island then
                    local pos, bd = isl.TeleportPoints[1].Position, nil
                    for _, ch in ipairs(workspace._WorldOrigin.Locations:GetChildren()) do
                        if ch.Name == isl.Reference.Location then
                            local m = (ch.Position - isl.World.Position).Magnitude
                            if not bd or m < bd then pos, bd = ch.Position, m end
                        end
                    end
                    return pos + Vector3.new(0, 30, 0)
                end
            end
            return nil
        end)
        if ok and r then SQ.Isl[island] = r return r end
        return nil
    end
    SQ.Go = function(pos, r)
        local char = plr.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return false end
        local d = (hrp.Position - pos).Magnitude
        SQ.Dist = d
        if d <= (r or 8) then return true end
        local now = os.clock()
        if now - (SQ.tGo or -1e9) >= 0.3 then
            SQ.tGo = now
            pcall(_tp, CFrame.new(pos))
        end
        return false
    end
    SQ.Settle = function(pos, r)
        if not SQ.Go(pos, r) then SQ.Arrived = nil return false end
        SQ.Arrived = SQ.Arrived or os.clock()
        if game:GetService("CollectionService"):HasTag(plr, "Teleporting") then
            SQ.TpTag = SQ.TpTag or os.clock()
            if os.clock() - SQ.TpTag <= 6 then return false end
        else
            SQ.TpTag = nil
        end
        return os.clock() - SQ.Arrived > 1.5
    end
    SQ.InAtomic = function() return os.clock() < SQ.AtomicUntil end
    SQ.Run["Fishman Karate"] = function(m)
        if m:InvokeServer("Initialize") == true then
            SQ.AtomicUntil = os.clock() + 8
            m:InvokeServer("Complete")
            SQ.ProgT = -1e9
            task.wait(2)
            SQ.AtomicUntil = 0
            return "Bend the light for the Water Kung Fu Teacher"
        end
        return "Waiting for the sealed door", true
    end
    SQ.Run["Early Access"] = function(m)
        local ea = SQ.EA
        if not ea or os.clock() - ea.time > 8 then
            ea = { time = os.clock(), available = m:InvokeServer("IsAvailable") == true, stage = m:InvokeServer("GetState") }
            SQ.EA = ea
        end
        local n = tonumber(ea.stage) or 0
        local function act(pos, ...)
            if not SQ.Settle(pos, 8) then return end
            SQ.AtomicUntil = os.clock() + 12
            for _, a in ipairs({ ... }) do
                local _, st = m:InvokeServer(a)
                if type(st) == "number" then ea.stage = st end
                task.wait(0.5)
            end
            SQ.AtomicUntil = 0
            ea.time = -1e9
            SQ.ProgT = -1e9
        end
        local npcs = workspace:FindFirstChild("NPCs")
        local npc = npcs and npcs:FindFirstChild("robotmega superfan")
        local npcPos = npc and (npc:GetPivot().Position + Vector3.new(0, 1.5, 3)) or Vector3.new(-1044.5, 26, 1683)
        if n == 0 then
            if not ea.available then return "DevBros are not visiting Middle Town now", true end
            act(npcPos, "InteractQuestGiver", "AcceptQuest")
            return "Talk to robotmega superfan"
        end
        if n == 1 then
            local assets = workspace._WorldOrigin:FindFirstChild("EarlyAccessBonusMomentAssets")
            local spot = assets and assets:FindFirstChild("KeySpot")
            act(spot and (spot.Position + Vector3.new(0, 3, 0)) or Vector3.new(-1052, 13, 1781), "CollectKey")
            return "Find the Rear Door Key"
        end
        if n == 2 then
            act(Vector3.new(-1091.8, 14, 1806), "InteractMansionDoor")
            return "Open the rear door"
        end
        if n == 3 then
            SQ.Infil = SQ.Infil or os.clock()
            if os.clock() - SQ.Infil > 9 then
                SQ.Infil = nil
                local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                if hrp then act(hrp.Position, "FinishInfiltration") end
            end
            return "Sneak into the dev room"
        end
        if n == 4 then
            act(npcPos, "InteractQuestGiver", "ClaimReward")
            return "Report to robotmega superfan"
        end
        return "Waiting for Early Access", true
    end
    SQ.Run["Zipline Repair"] = function(m)
        local z = SQ.ZL
        if not z or os.clock() - z.time > 30 then
            local conn
            conn = game:GetService("ReplicatedStorage").Remotes.BonusMomentsRemoteEvent.OnClientEvent:Connect(function(mn, kind, cf, _a, _b, _c, target, source)
                if mn == "Zipline Repair" and kind == "Setup" and typeof(cf) == "CFrame" then
                    SQ.ZL = { time = os.clock(), pickup = cf.Position, target = target, source = source }
                    conn:Disconnect()
                end
            end)
            m:FireServer("Initialize")
            task.wait(2)
            if conn.Connected then conn:Disconnect() end
            return "Locate grappling hook"
        end
        local char = plr.Character
        if not char then return "Waiting for character", true end
        local hook = char:FindFirstChild("Grappling Hook") or plr.Backpack:FindFirstChild("Grappling Hook")
        if not hook then
            if SQ.Settle(z.pickup + Vector3.new(0, 2, 0), 6) then
                m:FireServer("PickupTool")
                task.wait(1.5)
            end
            return "Pick up grappling hook"
        end
        if SQ.Settle(z.source + Vector3.new(0, 4, 0), 6) then
            if hook.Parent ~= char then
                local hum = char:FindFirstChildOfClass("Humanoid")
                if hum then hum:EquipTool(hook) end
                task.wait(0.5)
            end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp then
                SQ.AtomicUntil = os.clock() + 6
                local aim = require(game:GetService("ReplicatedStorage").Util.Trajectory).getArcAim(hrp.Position, z.target)
                m:InvokeServer("Throw", "Grappling Hook", aim)
                SQ.ProgT = -1e9
                task.wait(2)
                SQ.AtomicUntil = 0
            end
        end
        return "Throw hook to the zipline"
    end
    SQ.Why["Lookout"] = "buoc cuoi goi Guide.interactQuestGiver(\"TravelDressrosa\") (VX:12825) = chuyen Sea 2, hop dong chua xac minh"
    SQ.Why["Lever Jailbreak"] = "quest boss: phan danh Warden can hit-registration (VX:14421)"
    SQ.WhyBlocked = function(e)
        if SQ.Run[e.name] then return nil end
        if SQ.Why[e.name] then return SQ.Why[e.name] end
        if e.kind == "boss" then return "boss quest: hop dong chua xac minh (VX:13983-14517 can RegisterAttack/helper VX)" end
        return "can hit-registration/helper VX chua port (SAF T-14)"
    end
    SQ.Runnable = function()
        local n = 0
        for i = 1, #SQ.List do if SQ.Run[SQ.List[i].name] then n = n + 1 end end
        return n
    end
    SQ.Pick = function()
        if not (FX.Enable.SecretQuest and SQ.On) or not SQ.Sea1() then return nil end
        local p = SQ.Prog
        if SQ.Status ~= "OK" or type(p) ~= "table" then return nil end
        local now = os.clock()
        local best, bestRank
        for i = 1, #SQ.List do
            local e = SQ.List[i]
            if SQ.Run[e.name] and not SQ.IsDone(p, SQ.Key(e)) and (not e.requires or p[e.requires] == true) and now >= (SQ.Skipped[e.name] or 0) then
                local rank
                if SQ.Cur == e.name then rank = 0
                elseif SQ.Moment(e.name) ~= nil then rank = 1
                elseif now >= (SQ.Explore[e.name] or 0) then rank = 2 end
                if rank and (not bestRank or rank < bestRank) then best, bestRank = e, rank end
            end
        end
        return best
    end
    SQ.Want = function()
        local now = os.clock()
        if now - SQ.EvalT >= 0.5 then
            SQ.EvalT = now
            SQ.Act = SQ.Pick()
        end
        return SQ.Act ~= nil
    end
    SQ.Card = function(e)
        local fh = FX.FH
        if not fh or not fh.FarmData then return end
        local now = os.clock()
        if now - (SQ.tCard or -1e9) < 0.5 then return end
        SQ.tCard = now
        local ok = SQ.Status == "OK"
        pcall(fh.FarmData, "SecretQuest", {
            Title = e.name, Content = (e.island .. "  ·  " .. tostring(SQ.Step)),
            Value = ok and (tostring(SQ.Done) .. "/" .. tostring(#SQ.List)) or nil, Unit = "secret",
            Left = e.island, Right = ok and (tostring(#SQ.List - SQ.Done) .. " left") or "",
            Progress = ok and (SQ.Done / #SQ.List) or nil,
        })
    end
    SQ.Tick = function()
        local e = SQ.Pick()
        if not e then SQ.State = "IDLE" SQ.Cur = nil return end
        local now = os.clock()
        if SQ.Cur ~= e.name then
            SQ.Cur, SQ.CurSince, SQ.WaitSince, SQ.IslArr, SQ.Arrived, SQ.EA = e.name, now, nil, nil, nil, nil
            SQ.Note("start" .. e.name, "Secret Quest: " .. e.name .. " (" .. e.island .. ")", "green")
        end
        if now - SQ.CurSince > FX.Cfg.SQStallSec then
            SQ.Skipped[e.name] = now + 120
            SQ.Log("stall", e.name)
            SQ.Cur = nil
            return
        end
        local m = SQ.Moment(e.name)
        if not m then
            local pos = SQ.IslandPos(e.island)
            if not pos then
                SQ.State = "BLOCKED"
                SQ.Step = "khong doc duoc vi tri dao (Definitions.Map)"
                SQ.Skipped[e.name] = now + (e.retry or 420)
                SQ.Cur = nil
                return
            end
            SQ.State = "TRAVEL"
            SQ.Step = "Travel to " .. e.island
            SQ.Card(e)
            if SQ.Go(pos, 150) then
                SQ.IslArr = SQ.IslArr or now
                if now - SQ.IslArr > FX.Cfg.SQIslandWait then
                    SQ.IslArr = nil
                    SQ.Explore[e.name] = now + (e.retry or 420)
                    SQ.Cur = nil
                    SQ.Step = e.name .. " is not happening on " .. e.island
                    SQ.Note("nothappen" .. e.name, SQ.Step, "yellow")
                end
            else
                SQ.IslArr = nil
            end
            return
        end
        SQ.IslArr = nil
        SQ.State = "STEP"
        local ok, step, waiting = pcall(SQ.Run[e.name], m)
        if not ok then
            SQ.Log("run", e.name .. ": " .. tostring(step))
            SQ.Skipped[e.name] = now + 60
            SQ.Cur = nil
            SQ.State = "ERROR"
            SQ.Step = "loi: " .. tostring(step)
            SQ.Note("err" .. e.name, "Secret Quest loi: " .. e.name, "red")
            return
        end
        SQ.Step = tostring(step or "Working")
        SQ.Card(e)
        if waiting then
            SQ.WaitSince = SQ.WaitSince or now
            if now - SQ.WaitSince > 6 then
                SQ.Skipped[e.name] = now + (e.retry or 420)
                SQ.Cur, SQ.WaitSince = nil, nil
                SQ.Note("wait" .. e.name, e.name .. ": " .. SQ.Step .. ", chuyen quest khac", "yellow")
            end
        else
            SQ.WaitSince = nil
        end
    end
    SQ.Label = nil
    SQ.Refresh = function()
        if not SQ.Label then return end
        local txt
        if not SQ.On then
            txt = "OFF"
        elseif not SQ.Sea1() then
            txt = "GATED (chi Sea 1)"
        else
            local cnt = SQ.Status == "OK" and (tostring(SQ.Done) .. "/" .. tostring(#SQ.List)) or "?/" .. tostring(#SQ.List)
            txt = cnt .. "  |  tien do: " .. SQ.Status .. "  |  " .. SQ.State
            if SQ.Cur then txt = txt .. "  |  " .. SQ.Cur .. ": " .. tostring(SQ.Step) end
            txt = txt .. "  |  chay duoc " .. tostring(SQ.Runnable()) .. "/" .. tostring(#SQ.List) .. ", BLOCKED " .. tostring(#SQ.List - SQ.Runnable())
        end
        if txt ~= SQ.LastTxt then
            SQ.LastTxt = txt
            pcall(function() SQ.Label:SetContent("Status: " .. txt) end)
        end
    end
    SQ.Success = function(e)
        local fh = FX.FH
        if fh and fh.Finish then
            pcall(fh.Finish, "SecretQuest", { Title = e.name .. " done", Content = tostring(SQ.Done) .. "/" .. tostring(#SQ.List) .. " secret quests", Success = true })
        end
        SQ.Note("done" .. e.name, e.name .. " completed (" .. tostring(SQ.Done) .. "/" .. tostring(#SQ.List) .. ")", "green")
    end
