spawn(function()
    local player = game.Players.LocalPlayer
    while wait(0.5) do
        if PFS_ShouldYieldBone and PFS_ShouldYieldBone() then continue end
        if not _G.AutoFarm_Bone then continue end
        pcall(function()
            local char = player.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if not root then return end
            local questUI =
                player.PlayerGui:FindFirstChild("Main")
                and player.PlayerGui.Main:FindFirstChild("Quest")
            if _G.AcceptQuestB and questUI and not questUI.Visible then
                local questPos = CFrame.new(-9516.99316,172.01718,6078.46533)
                local questArgB = nil
                if _G.FARMX.Enable.BoneQuestByLevel then
                    local okB, lvB = pcall(function() return plr.Data.Level.Value end)
                    lvB = okB and tonumber(lvB) or 0
                    if lvB >= 2050 then
                        questArgB = { "StartQuest", "HauntedQuest2", 2 }
                    elseif lvB >= 2025 then
                        questArgB = { "StartQuest", "HauntedQuest2", 1 }
                    elseif lvB >= 2000 then
                        questArgB = { "StartQuest", "HauntedQuest1", 2 }
                    else
                        questArgB = { "StartQuest", "HauntedQuest1", 1 }
                    end
                    if questArgB[2] == "HauntedQuest1" then questPos = CFrame.new(-9479.2168, 141.215088, 5566.09277) end
                end
                _tp(questPos)
                local qT = _G.FARMX.Enable.BoneQuestTimeout
                local qT0 = os.clock()
                _G.FARMX._boneQTp = qT0
                repeat wait(0.2)
                    if qT then
                        local c2 = player.Character
                        local r2 = c2 and c2:FindFirstChild("HumanoidRootPart")
                        if r2 then root = r2 end
                        if (questPos.Position - root.Position).Magnitude > 50 and os.clock() - (_G.FARMX._boneQTp or 0) >= 1.5 then _G.FARMX._boneQTp = os.clock(); _tp(questPos) end
                        if _G.FARMX.Nav then _G.FARMX.Nav.Update("npc", "Haunted Quest NPC", questPos.Position) end
                    end
                until not _G.AutoFarm_Bone
                   or (questPos.Position - root.Position).Magnitude <= 50
                   or (qT and os.clock() - qT0 > _G.FARMX.Cfg.QuestWalkTimeout)
                if _G.FARMX.Nav then _G.FARMX.Nav.Clear("end") end
                if qT and _G.AutoFarm_Bone and (questPos.Position - root.Position).Magnitude > 50 then return end
                if not _G.AutoFarm_Bone then return end
                local questData = {
                    {"StartQuest","HauntedQuest2",2},
                    {"StartQuest","HauntedQuest2",1},
                    {"StartQuest","HauntedQuest1",1},
                    {"StartQuest","HauntedQuest1",2}
                }
                game.ReplicatedStorage.Remotes.CommF_:InvokeServer(
                    unpack(questArgB or questData[math.random(1,#questData)])
                )
            end
            local fxD = _G.FARMX
            if not (fxD and fxD.Area and fxD.Dwell and fxD.SpawnHold and fxD.KillWatch) then return end
            local near = fxD.Area.Near("Bone", math.huge)
            local foundMob = near[1] and near[1].mob
            if foundMob then
                fxD.Dwell.Tick("Bone", #near)
                if fxD.TraceAdd then fxD.TraceAdd("BONE_KILL", foundMob.Name, near[1].dist) end
                local stallT = os.clock()
                repeat
                    wait()
                    if not _G.AutoFarm_Bone then break end
                    if _G.ActiveFarm and _G.ActiveFarm ~= "Bone" then break end
                    local k0 = os.clock()
                    Attack.Kill(foundMob, _G.AutoFarm_Bone)
                    stallT = fxD.KillWatch(foundMob, stallT, os.clock() - k0)
                until not _G.AutoFarm_Bone
                   or not foundMob.Parent
                   or (not Attack.Alive(foundMob))
            else
                local fbB = CFrame.new(-9495.6806640625, 453.58624267578125, 5977.3486328125)
                if not fxD.SpawnHold("Bone", fbB, false) then
                    fxD.Dwell.Reset("Bone")
                elseif fxD.Dwell.Tick("Bone", 0) then
                    fxD.SpawnHold("Bone", fbB, true)
                    fxD.Dwell.Reset("Bone")
                end
            end
        end)
    end
end)
