UIX.Paragraph(Tabs.Main, "Para_42", {Title = "Tyrant of the Skies", Content = ""})
    local _TyrantMobList = {
        "Serpent Hunter",
        "Skull Slayer",
        "Isle Champion",
        "Sun-kissed Warrior",
        "Isle Outlaw",
        "Island Boy",
    }
    local _TyrantCenter = CFrame.new(-16268.287, 152.616, 1390.773)
    task.spawn(function()
        local function _tyOn()
            if not _G.FarmTyrant then return false end
            local fxT = _G.FARMX
            -- R03: owner check độc lập khỏi TyrantMove flag
            -- Trước đây: fxT.Enable.TyrantMove && fxT.Enable.KillStopOnSwitch && NotOwner → return false
            -- Bug: nếu TyrantMove off thì owner check bị skip, worker chạy dù không phải owner
            if fxT and fxT.Enable and fxT.Enable.KillStopOnSwitch and fxT.NotOwner and fxT.NotOwner("Tyrant") then return false end
            return true
        end
        local _tyWaitT = -1e9
        local _tyBlockT = {}
        local function tyEyes()
            -- R05/R06: dùng centralized reader
            local info = FX.ReadTyrantEyes and FX.ReadTyrantEyes() or nil
            return (info and info.count) or 0
        end
        local function tySpam()
            -- R07: verify owner + eyes trước khi spam skills
            if not _tyOn() then return end
            local fxS = _G.FARMX
            if fxS and fxS.Enable and fxS.Enable.TyrantEyesFlow then
                local eyeInfo = FX.ReadTyrantEyes and FX.ReadTyrantEyes() or nil
                if not (eyeInfo and eyeInfo.ok and eyeInfo.count >= 4) then return end
            end
            pcall(function()
                local ch = plr.Character
                if ch and not ch:FindFirstChildOfClass("Tool") then
                    local bp = plr:FindFirstChild("Backpack")
                    local t = bp and ((_G.SelectWeapon and bp:FindFirstChild(_G.SelectWeapon)) or bp:FindFirstChildOfClass("Tool"))
                    if t then t.Parent = ch end
                end
            end)
            local vim = game:GetService("VirtualInputManager")
            for _, k in ipairs({ "Z", "X", "C", "V", "F" }) do
                if not _tyOn() then return end
                pcall(function()
                    vim:SendKeyEvent(true, k, false, game)
                    task.wait(0.05)
                    vim:SendKeyEvent(false, k, false, game)
                end)
                task.wait(0.1)
            end
        end
        local function tyBlock(code, extra)
            local now = os.clock()
            if now - (_tyBlockT[code] or -1e9) < 8 then return end
            _tyBlockT[code] = now
            local fxG = _G.FARMX
            if not (fxG and fxG.Enable and fxG.Enable.TyrantMove) then return end
            if fxG.TraceAdd then pcall(fxG.TraceAdd, "TYRANT_" .. code, extra or "") end
            if fxG.FH and fxG.FH.NotifyDot then
                pcall(fxG.FH.NotifyDot, "y", "Tyrant: " .. code .. (extra and (" " .. tostring(extra)) or ""), 2)
            end
        end
        while task.wait() do
            if PFS_ShouldYieldBoss and PFS_ShouldYieldBoss() then
                if _G.ActiveFarm == "Tyrant" then tyBlock("PFS_YIELD") end
                continue
            end
            if not _tyOn() then
                if _G.ActiveFarm == "Tyrant" then
                    local fxO = _G.FARMX
                    local ow = fxO and fxO.FH and fxO.FH.Owner
                    tyBlock("BLOCKED", ow and ow.name or "flag-off")
                end
                continue
            end
            local okTyW, errTyW = pcall(function()
                if not plr.Character then return end
                local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                local fxT2 = _G.FARMX
                if fxT2 then
                    local pgT = plr:FindFirstChild("PlayerGui")
                    local trTextT = ""
                    if pgT then
                        local trT = pgT:FindFirstChild("TrackedQuestFrame")
                        if trT then
                            local f1T = trT:FindFirstChild("Frame")
                            local h1T = f1T and f1T:FindFirstChild("header")
                            local l1T = h1T and h1T:FindFirstChild("textLabel")
                            local l2T = l1T and l1T:FindFirstChild("textLabel")
                            if l2T and l2T:IsA("TextLabel") then trTextT = l2T.Text or "" end
                        end
                    end
                    local questUIT2 = pgT and pgT:FindFirstChild("Main") and pgT.Main:FindFirstChild("Quest")
                    local hasQuestT = (trTextT ~= "") or (questUIT2 and questUIT2.Visible == true)
                    local questMobNameT = nil
                    for _, mn in ipairs(_TyrantMobList) do
                        if trTextT ~= "" and string.find(trTextT, mn, 1, true) then questMobNameT = mn; break end
                    end
                    if (not hasQuestT) or (trTextT ~= "" and not questMobNameT) then
                        local okLT, lvlT = pcall(function() return plr.Data.Level.Value end)
                        lvlT = okLT and tonumber(lvlT) or 0
                        local questArgT = nil
                        -- R01/R02: fixed TikiQuest mapping per data.lua
                        -- 2450-2474 Isle Outlaw T1.1, 2475-2499 Island Boy T1.2,
                        -- 2500-2524 Sun-kissed Warrior T2.1, 2525-2549 Isle Champion T2.2,
                        -- 2550-2574 Serpent Hunter T3.1, 2575-2599 Skull Slayer T3.2
                        if lvlT >= 2575 then
                            questArgT = { "StartQuest", "TikiQuest3", 2 }   -- Skull Slayer
                        elseif lvlT >= 2550 then
                            questArgT = { "StartQuest", "TikiQuest3", 1 }   -- Serpent Hunter
                        elseif lvlT >= 2525 then
                            questArgT = { "StartQuest", "TikiQuest2", 2 }   -- Isle Champion
                        elseif lvlT >= 2500 then
                            questArgT = { "StartQuest", "TikiQuest2", 1 }   -- Sun-kissed Warrior
                        elseif lvlT >= 2475 then
                            questArgT = { "StartQuest", "TikiQuest1", 2 }   -- Island Boy
                        else
                            questArgT = { "StartQuest", "TikiQuest1", 1 }   -- Isle Outlaw (fallback)
                        end
                        local tikiNpcPos = CFrame.new(-16224, 9, 439)
                        if (hrp.Position - tikiNpcPos.Position).Magnitude > 80 then
                            _tp(tikiNpcPos)
                            local t0T = tick()
                            repeat task.wait(0.1)
                                hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                            until not _tyOn() or not hrp
                               or (hrp.Position - tikiNpcPos.Position).Magnitude <= 80
                               or (tick() - t0T > 12)
                            if not _tyOn() then return end
                            hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                            if not hrp then return end
                        end
                        local fxQ = _G.FARMX
                        -- R04: quest throttle độc lập khỏi TyrantMove flag
                        -- Trước đây: chỉ throttle khi TyrantMove on → nếu off thì không quest được
                        if (not fxQ) or os.clock() - (fxQ._tyQuestT or -1e9) > 8 then
                            if fxQ then fxQ._tyQuestT = os.clock() end
                            pcall(function()
                                game.ReplicatedStorage.Remotes.CommF_:InvokeServer(unpack(questArgT))
                            end)
                            task.wait(0.5)
                        end
                    end
                end
                local fxMV = _G.FARMX
                local useMV2 = fxMV and fxMV.Enable and fxMV.Enable.TyrantMoveV2
                if useMV2 then
                    local farDist = (fxMV.Cfg and fxMV.Cfg.TyrantFarDist) or 1500
                    if (hrp.Position - _TyrantCenter.Position).Magnitude > farDist then
                        local t0Tw = tick()
                        repeat
                            _tp(_TyrantCenter)
                            task.wait(0.2)
                            hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                        until not _tyOn()
                           or not hrp
                           or (hrp.Position - _TyrantCenter.Position).Magnitude <= 300
                           or (tick() - t0Tw > 30)
                        if fxMV.TraceAdd then fxMV.TraceAdd("TYRANT_FAR_TP", "TikiOutpost", (hrp and (hrp.Position - _TyrantCenter.Position).Magnitude) or -1) end
                        if not _tyOn() then return end
                        hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                        if not hrp then return end
                    end
                else
                    if (hrp.Position - _TyrantCenter.Position).Magnitude > 5000 then
                        local t0Tw = tick()
                        repeat
                            _tp(_TyrantCenter)
                            task.wait(2)
                            hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                        until not _tyOn()
                           or not hrp
                           or (hrp.Position - _TyrantCenter.Position).Magnitude <= 500
                           or (tick() - t0Tw > 30)
                        if not _tyOn() then return end
                        hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                        if not hrp then return end
                    end
                end
                local boss = workspace.Enemies:FindFirstChild("Tyrant of the Skies")
                if boss
                    and boss:FindFirstChildOfClass("Humanoid")
                    and boss:FindFirstChild("HumanoidRootPart")
                    and Attack.Alive(boss)
                then
                    -- Boss spawn notification (chỉ fire lần đầu khi _TyrantBossSeen chưa set)
                    local fxB = _G.FARMX
                    if fxB and fxB._TyrantBossSeen ~= true and fxB.FH and fxB.FH.NotifyDot then
                        fxB._TyrantBossSeen = true
                        pcall(fxB.FH.NotifyDot, "g", "Tyrant spawned", 2)
                    end
                    repeat
                        task.wait()
                        if not _tyOn() then break end
                        hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                        if not hrp then break end
                        if (hrp.Position - boss.HumanoidRootPart.Position).Magnitude > 30 then
                            _tp(boss.HumanoidRootPart.CFrame * CFrame.new(0, 20, 0))
                            local t0 = tick()
                            repeat task.wait()
                                hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                            until not _tyOn() or not hrp
                               or (hrp.Position - boss.HumanoidRootPart.Position).Magnitude <= 30
                               or (tick() - t0 > 8)
                        end
                        if _tyOn() and Attack and Attack.Kill then
                            Attack.Kill(boss, function() return _tyOn() end)
                        end
                    until not _tyOn()
                       or not boss.Parent
                       or not boss:FindFirstChildOfClass("Humanoid")
                       or not Attack.Alive(boss)
                    do
                        local fxD = _G.FARMX
                        if _tyOn() and fxD and fxD.Enable.TyrantMove and fxD.FH and fxD.FH.NotifyDot
                            and (not boss.Parent or (not Attack.Alive(boss))) then
                            pcall(fxD.FH.NotifyDot, "g", "Tyrant defeated", 2)
                        end
                    end
                    return
                end
                local foundMob = false
                local fxT3 = _G.FARMX
                if fxT3 then
                    local nearestMob = nil
                    local minDist = math.huge
                    for _, mob in pairs(workspace.Enemies:GetChildren()) do
                        if mob and table.find(_TyrantMobList, mob.Name)
                            and mob:FindFirstChild("HumanoidRootPart")
                            and mob:FindFirstChildOfClass("Humanoid")
                            and Attack.Alive(mob)
                        then
                            local d = (mob.HumanoidRootPart.Position - hrp.Position).Magnitude
                            if d < minDist then minDist = d; nearestMob = mob end
                        end
                    end
                    if nearestMob then
                        foundMob = true
                        if fxT3.TraceAdd then fxT3.TraceAdd("TYRANT_KILL", nearestMob.Name, minDist) end
                        if (hrp.Position - nearestMob.HumanoidRootPart.Position).Magnitude > 30 then
                            _tp(nearestMob.HumanoidRootPart.CFrame * CFrame.new(0, 20, 0))
                            local t0 = tick()
                            repeat task.wait()
                                hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                            until not _tyOn() or not hrp
                               or (hrp.Position - nearestMob.HumanoidRootPart.Position).Magnitude <= 30
                               or (tick() - t0 > 8)
                        end
                        repeat
                            task.wait()
                            if not _tyOn() then break end
                            if Attack and Attack.Kill then
                                Attack.Kill(nearestMob, function() return _tyOn() end)
                            end
                        until not _tyOn()
                           or not nearestMob.Parent
                           or not nearestMob:FindFirstChildOfClass("Humanoid")
                           or not Attack.Alive(nearestMob)
                    end
                end
                if not foundMob then
                    local fxW = _G.FARMX
                    -- R08: spawn fallback — tìm EnemySpawns part gần nhất cho Tiki mob
                    -- Giống Cake SpawnHold: khi không có mob trong Enemies, tween tới spawn part
                    local spawnMob = nil
                    pcall(function()
                        local origin = workspace:FindFirstChild("_WorldOrigin")
                        local spawns = origin and origin:FindFirstChild("EnemySpawns")
                        if spawns then
                            local minD = math.huge
                            for _, sp in ipairs(spawns:GetChildren()) do
                                if table.find(_TyrantMobList, sp.Name) and sp:IsA("BasePart") then
                                    local d = (sp.Position - hrp.Position).Magnitude
                                    if d < minD then minD = d; spawnMob = sp end
                                end
                            end
                        end
                    end)
                    if spawnMob then
                        if fxW.TraceAdd then fxW.TraceAdd("TYRANT_SPAWN_FALLBACK", spawnMob.Name) end
                        _tp(spawnMob.CFrame * CFrame.new(0, 20, 0))
                        local t0S = tick()
                        repeat task.wait(0.2)
                            hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                        until not _tyOn() or not hrp
                           or (hrp.Position - spawnMob.Position).Magnitude <= 50
                           or (tick() - t0S > 8)
                        task.wait(0.3)
                    else
                        local useEF = fxW and fxW.Enable and fxW.Enable.TyrantMove and fxW.Enable.TyrantEyesFlow
                        if useEF then
                            local hrpW = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                            local eyesN = tyEyes()
                            if hrpW and eyesN >= 4 then
                                if os.clock() - _tyWaitT > 6 and fxW.FH and fxW.FH.NotifyDot then
                                    _tyWaitT = os.clock()
                                    pcall(fxW.FH.NotifyDot, "y", "Waiting for Tyrant (4/4 Eyes)", 1.2)
                                end
                                tySpam()
                            elseif hrpW then
                                task.wait(0.3)
                            end
                        elseif fxW and fxW.Enable and fxW.Enable.TyrantMove then
                            local hrpW = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                            if os.clock() - _tyWaitT > 6 and fxW.FH and fxW.FH.NotifyDot then
                                _tyWaitT = os.clock()
                                pcall(fxW.FH.NotifyDot, "y", "Waiting for Tyrant", 1.2)
                            end
                            task.wait(0.5)
                        else
                            task.wait(0.5)
                        end
                    end
                end
            end)
            if not okTyW then tyBlock("ERR", tostring(errTyW):sub(1, 60)) end
        end
    end)
