do
    local FX = _G.FARMX
    local G = {
        lg = false, rm = false, conn = nil, token = 0,
        orig = setmetatable({}, { __mode = "k" }),
        water = nil, fx = {},
    }
    FX.Gfx = G
    local KIND = {
        Texture         = { "Transparency", 1,     "lg", true },
        Decal           = { "Transparency", 1,     "lg", true },
        Smoke           = { "Enabled",      false, "lg" },
        Fire            = { "Enabled",      false, "lg" },
        Sparkles        = { "Enabled",      false, "lg" },
        ParticleEmitter = { "Enabled",      false, "lg" },
        Trail           = { "Enabled",      false, "rm" },
        Beam            = { "Enabled",      false, "rm" },
    }
    local function inCharacter(d)
        local p = d.Parent
        while p and p ~= workspace do
            if p:IsA("Model") and p:FindFirstChildOfClass("Humanoid") then return true end
            p = p.Parent
        end
        return false
    end
    local function reduceOne(d)
        local k = KIND[d.ClassName]
        if not k then return end
        if not G[k[3]] then return end
        if k[4] and inCharacter(d) then return end
        if G.orig[d] then return end
        local ok, old = pcall(function() return d[k[1]] end)
        if not ok then return end
        G.orig[d] = { k[1], old }
        pcall(function() d[k[1]] = k[2] end)
    end
    local function restoreGroup(group)
        for d, rec in pairs(G.orig) do
            local k = KIND[d.ClassName]
            if k and k[3] == group then
                if d.Parent then pcall(function() d[rec[1]] = rec[2] end) end
                G.orig[d] = nil
            end
        end
    end
    local function lightingEffects(on)
        local l = game:GetService("Lighting")
        if on then
            for _, e in ipairs(l:GetDescendants()) do
                if (e:IsA("BlurEffect") or e:IsA("DepthOfFieldEffect")) and e.Enabled then
                    G.fx[e] = true
                    e.Enabled = false
                end
            end
        else
            for e in pairs(G.fx) do
                if e.Parent then pcall(function() e.Enabled = true end) end
                G.fx[e] = nil
            end
        end
    end
    local function water(on)
        local t = workspace:FindFirstChildOfClass("Terrain")
        if not t then return end
        if on then
            if not G.water then G.water = { t.WaterWaveSize, t.WaterWaveSpeed } end
            t.WaterWaveSize, t.WaterWaveSpeed = 0, 0
        elseif G.water then
            t.WaterWaveSize, t.WaterWaveSpeed = G.water[1], G.water[2]
            G.water = nil
        end
    end
    local function sweep()
        G.token = G.token + 1
        local tok = G.token
        task.spawn(function()
            local ok, err = pcall(function()
                local all = workspace:GetDescendants()
                for i = 1, #all do
                    if G.token ~= tok then return end
                    reduceOne(all[i])
                    if i % 1500 == 0 then task.wait() end
                end
            end)
            if not ok then FX.Log("gfx-sweep", err) end
        end)
    end
    local function syncConn()
        if (G.lg or G.rm) and not G.conn then
            G.conn = workspace.DescendantAdded:Connect(reduceOne)
        elseif not (G.lg or G.rm) and G.conn then
            G.conn:Disconnect()
            G.conn = nil
        end
    end
    FX.SetLowGfx = function(v)
        v = v and FX.Enable.LowGfx and true or false
        if G.lg == v then return end
        G.lg = v
        if v then sweep() else G.token = G.token + 1 restoreGroup("lg") end
        syncConn()
    end
    FX.SetReduceMotion = function(v)
        v = v and FX.Enable.ReduceMotion and true or false
        if G.rm == v then return end
        G.rm = v
        pcall(water, v)
        pcall(lightingEffects, v)
        if v then sweep() else G.token = G.token + 1 restoreGroup("rm") end
        syncConn()
    end
    UIX.Toggle(Tabs.Settings, "Settings_ReduceMotion", {
        Title = "Reduce Motion",
        Description = "Giảm chuyển động: tắt sóng nước, blur, trail, beam (khôi phục khi tắt)",
        Default = true,
        Callback = function(v) FX.SetReduceMotion(v) end
    })
    UIX.Toggle(Tabs.Settings, "Settings_LowGraphicsVfx", {
        Title = "Low Graphics (Texture + VFX)",
        Description = "Chỉ ẩn texture bề mặt + khói/lửa/hạt VFX. Không xóa part, mesh, vật liệu, nhân vật",
        Default = true,
        Callback = function(v) FX.SetLowGfx(v) end
    })
    FX.SetReduceMotion(true)
    FX.SetLowGfx(true)
end
;(function()
    local FX = _G.FARMX
    FX.Enable.AutoClean = FX.Enable.AutoClean ~= false
    FX.Cfg.CleanEvery = FX.Cfg.CleanEvery or 180
    FX.CleanStat = { runs = 0, last = 0, before = 0, after = 0, dropped = 0, mbBefore = 0, mbAfter = 0 }
    local function kb()
        local ok, v = pcall(collectgarbage, "count")
        return (ok and tonumber(v)) or 0
    end
    local function mb()
        local ok, v = pcall(function() return game:GetService("Stats"):GetTotalMemoryUsageMb() end)
        return (ok and tonumber(v)) or 0
    end
    local function trim(t, keep)
        if type(t) ~= "table" then
            return 0
        end
        local n = 0
        while #t > keep do
            table.remove(t, 1)
            n = n + 1
        end
        return n
    end
    FX.Clean = function(deep)
        local S = FX.CleanStat
        local now = os.clock()
        local b, mb0 = kb(), mb()
        local dropped = 0
        for k, c in pairs(FX.Cache or {}) do
            local age = now - ((type(c) == "table" and tonumber(c.t)) or 0)
            local lim = (type(k) == "string" and string.sub(k, 1, 3) == "QR:") and 120 or 600
            if deep then
                lim = lim / 4
            end
            if age > lim then
                FX.Cache[k] = nil
                dropped = dropped + 1
            end
        end
        for k, t in pairs(FX.Logs or {}) do
            if now - (tonumber(t) or 0) > 300 then
                FX.Logs[k] = nil
                dropped = dropped + 1
            end
        end
        for k, bk in pairs(FX.Bucket or {}) do
            if type(bk) == "table" and now - (tonumber(bk.t) or 0) > 300 then
                FX.Bucket[k] = nil
                dropped = dropped + 1
            end
        end
        if deep then
            dropped = dropped + trim(FX.QuestLog, 10) + trim(FX.QuestEvents, 10) + trim(FX.NetLog, 10)
            if FX.Probe then
                FX.Probe.clipBy = nil
            end
        end
        pcall(function()
            local Cr = Library.WindUI and Library.WindUI.Creator
            if Cr and Cr._WALGRims then
                for rim in pairs(Cr._WALGRims) do
                    if not rim.Parent then
                        Cr._WALGRims[rim] = nil
                        dropped = dropped + 1
                    end
                end
            end
        end)
        if deep then
            pcall(collectgarbage, "collect")
        else
            pcall(collectgarbage, "step", 300)
        end
        local a = kb()
        S.runs, S.last, S.before, S.after, S.dropped, S.mbBefore, S.mbAfter = S.runs + 1, os.clock(), b, a, dropped, mb0, mb()
        return b, a, dropped
    end
    _G.__MaruCleanTok = (_G.__MaruCleanTok or 0) + 1
    local tok = _G.__MaruCleanTok
    task.spawn(function()
        while _G.__MaruCleanTok == tok do
            task.wait(math.max(30, tonumber(FX.Cfg.CleanEvery) or 120))
            if _G.__MaruCleanTok ~= tok then
                break
            end
            local srch = false
            pcall(function() local C = Library.WindUI and Library.WindUI.Creator srch = C and C._WASrch ~= nil and not C._WASrch.closed end)
            if FX.Enable.AutoClean and not srch then
                pcall(FX.Clean, false)
            end
        end
    end)
    UIX.Toggle(Tabs.Settings, "Settings_AutoClean", {
        Title = "Tự dọn cache/RAM",
        Description = "Mỗi 120 s dọn cache của script (không đụng part/mesh/texture của game) rồi chạy GC",
        Default = FX.Enable.AutoClean,
        Callback = function(v) FX.Enable.AutoClean = v and true or false end
    })
    UIX.Button(Tabs.Settings, "Settings_CleanNow", {
        Title = "Dọn cache + RAM ngay",
        Description = "Dọn sâu cache script + collectgarbage; in KB trước/sau ra console",
        Callback = function()
            local ok, b, a, d = pcall(FX.Clean, true)
            local S = FX.CleanStat
            local msg = ok and string.format("script %.0f -> %.0f KB | bỏ %d mục | client %.0f -> %.0f MB (GC có thể trễ vài giây)", b, a, d, S.mbBefore, S.mbAfter) or ("lỗi: " .. tostring(b))
            print("[Shin Roblox][CLEAN] " .. msg)
            pcall(function() Library.WindUI:Notify({ Title = "Dọn cache/RAM", Content = msg, Duration = 4 }) end)
        end
    })
    UIX.Button(Tabs.Settings, "Settings_FpsBoostNow", {
        Title = "Giảm đồ họa mạnh ngay",
        Description = "Quét workspace theo từng đợt: tắt hạt/hiệu ứng/đèn, texture trong suốt, vật liệu phẳng, chất lượng Level01",
        Callback = function()
            if _G.QM_FpsBoostRun then
                _G.QM_FpsBoostRun()
            end
        end
    })
end)()
