local Workspace = game:GetService("Workspace")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local FishReplicated = ReplicatedStorage:WaitForChild("FishReplicated", 4)
local FishingRequest = FishReplicated and FishReplicated:WaitForChild("FishingRequest", 4)
local Config, GetWaterHeight
do
    local _ok1, _r1 = pcall(function() return require(FishReplicated.FishingClient.Config) end)
    Config = _ok1 and _r1 or { Rod = { MaxLaunchDistance = 100 } }
    local _ok2, _r2 = pcall(function() return require(ReplicatedStorage.Util.GetWaterHeightAtLocation) end)
    GetWaterHeight = _ok2 and _r2 or function() return 0 end
end
local MaxDistance = Config.Rod.MaxLaunchDistance
task.spawn(function()
    while task.wait(0.5) do
        if _G.AutoFishing then
            pcall(function()
                local Char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
                local HRP = Char:FindFirstChild("HumanoidRootPart")
                if not HRP then return end
                local Tool = Char:FindFirstChildOfClass("Tool")
                if _G.SelectedRod and (not Tool or Tool.Name ~= _G.SelectedRod) then
                    local backpackTool = LocalPlayer.Backpack:FindFirstChild(_G.SelectedRod)
                    if backpackTool then
                        do local _h = Attack.Hum(Char); if _h then _h:EquipTool(backpackTool) end end
                        Tool = backpackTool
                    end
                end
                if Tool then
                    local waterHeight = GetWaterHeight(HRP.Position)
                    local _, hitPos = Workspace:FindPartOnRayWithIgnoreList(
                        Ray.new(Char.Head.Position, HRP.CFrame.LookVector * MaxDistance),
                        {Char, Workspace.Characters, Workspace.Enemies}
                    )
                    local TargetPos = hitPos and Vector3.new(hitPos.X, math.max(hitPos.Y, waterHeight), hitPos.Z)
                    local State = Tool:GetAttribute("State")
                    local ServerState = Tool:GetAttribute("ServerState")
                    if TargetPos and (State == "ReeledIn" or ServerState == "ReeledIn") then
                        FishingRequest:InvokeServer("StartCasting")
                        task.wait()
                        FishingRequest:InvokeServer("CastLineAtLocation", TargetPos, 100, true)
                    elseif ServerState == "Biting" then
                        FishingRequest:InvokeServer("Catching", true)
                        task.wait(0.1)
                        FishingRequest:InvokeServer("Catch", 1)
                    end
                end
            end)
        end
    end
end)
