do
    UIX.Toggle(Tabs.SeaEvent, "SeaEvent_AutoUnjitterBoat", {
        Title = "Auto Fix Boat Jitter",
        Description = "Neu thuyen rung khi dang ngoi: tu bo ngoi roi nhay",
        Default = false,
        Callback = function(Value) _G.SeaBoatUnjitter = Value end
    })
    task.spawn(function()
        local RS = game:GetService("RunService")
        while task.wait(0.5) do
            if _G.SeaBoatUnjitter then
                pcall(function()
                    local char = plr.Character
                    local hum = char and char:FindFirstChildOfClass("Humanoid")
                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    if not (hum and hrp and hum.Sit) then return end
                    local boat
                    local boats = workspace:FindFirstChild("Boats")
                    if boats then
                        for _, b in ipairs(boats:GetChildren()) do
                            local o = b:FindFirstChild("Owner")
                            if o and tostring(o.Value) == plr.Name then boat = b break end
                        end
                    end
                    if not boat then return end
                    local part = boat.PrimaryPart or boat:FindFirstChildWhichIsA("BasePart")
                    if not part then return end
                    local last = part.Position - hrp.Position
                    local lastDir, rev, t0 = 0, 0, os.clock()
                    while os.clock() - t0 < 0.5 do
                        RS.Heartbeat:Wait()
                        if not _G.SeaBoatUnjitter or not hrp.Parent or not part.Parent then return end
                        local cur = part.Position - hrp.Position
                        local d = cur - last
                        local mag = d.Magnitude
                        if mag > 0.05 and mag < 5 then
                            local dir = math.sign(d.Y ~= 0 and d.Y or d.Z)
                            if lastDir ~= 0 and dir ~= 0 and dir ~= lastDir then rev = rev + 1 end
                            if dir ~= 0 then lastDir = dir end
                        end
                        last = cur
                    end
                    if rev >= 3 then
                        hum.Sit = false
                        task.wait(0.1)
                        hum.Jump = true
                    end
                end)
            end
        end
    end)
end
