task.spawn(function()
    while task.wait(Sec) do
        pcall(function()
            if _G.AimCam then
                local camera = workspace.CurrentCamera
                closestplayer = function()
                    local dist = math.huge
                    local target = nil
                    for _, v in next, ply:GetPlayers() do
                        if v ~= plr then
                            if v.Character and v.Character:FindFirstChild("Head") and _G.AimCam and v.Attack.Alive(Character) then
                                local Mag = (v.Character.Head.Position - plr.Character.Head.Position).Magnitude
                                if Mag < dist then
                                    dist = Mag
                                    target = v
                                end
                            end
                        end
                    end
                    return target
                end
                repeat
                    task.wait()
                    local _cp = closestplayer()
                    if not _cp or not _cp.Character then break end
                    camera.CFrame = CFrame.new(
                        camera.CFrame.Position,
                        _cp.Character.HumanoidRootPart.Position
                    )
                until not _G.AimCam or not closestplayer() or not closestplayer().Character
            end
        end)
    end
end)
