_G.FARMX.SafeMode = _G.FARMX.SafeMode or { state = "NORMAL", originY = nil, lastNotify = 0 }
spawn(function()
    while task.wait(Sec) do
        if not _G.SafeMode then
            if _G.FARMX.SafeMode.state ~= "NORMAL" then
                _G.FARMX.SafeMode.state = "NORMAL"
                _G.FARMX.SafeMode.originY = nil
            end
            continue
        end
        pcall(function()
            local char = game.Players.LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if not hum or not hrp then return end
            if hum.MaxHealth <= 0 then return end
            local hpPct = hum.Health / hum.MaxHealth * 100
            local sm = _G.FARMX.SafeMode
            local now = os.clock()
            local fxN = _G.FARMX
            if sm.state == "NORMAL" then
                if hpPct < 40 then
                    sm.state = "PANIC_UP"
                    sm.originY = hrp.Position.Y
                    sm.own = true; pcall(_tp, hrp.CFrame * CFrame.new(0, 2000, 0)); sm.own = false
                    if fxN and fxN.FH and fxN.FH.NotifyDot and now - sm.lastNotify > 1 then
                        sm.lastNotify = now
                        pcall(fxN.FH.NotifyDot, "r", "Safe Mode: HP low, flying up", 2)
                    end
                end
            elseif sm.state == "PANIC_UP" then
                if hpPct > 65 then
                    sm.state = "PANIC_DOWN"
                    local origY = sm.originY or hrp.Position.Y
                    sm.own = true; pcall(_tp, CFrame.new(hrp.Position.X, origY, hrp.Position.Z) * (hrp.CFrame - hrp.CFrame.Position)); sm.own = false
                    if fxN and fxN.FH and fxN.FH.NotifyDot and now - sm.lastNotify > 1 then
                        sm.lastNotify = now
                        pcall(fxN.FH.NotifyDot, "g", "HP recovered, descending", 2)
                    end
                end
            elseif sm.state == "PANIC_DOWN" then
                sm.state = "NORMAL"
                sm.originY = nil
            end
        end)
    end
end)
UIX.Paragraph(Tabs.Combat, "Para_95", {Title = "LocalPlayer Settings", Content = ""})
local flying = false
local flySpeed = 50
local flyConnection
local bv, bg
local function toggleFly(value)
    flying = value
    local character = player.Character
    if not character then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local rootPart = character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("Torso") or character:FindFirstChild("UpperTorso")
    if not humanoid or not rootPart then return end
    if flying then
        bv = Instance.new("BodyVelocity")
        bv.MaxForce = Vector3.new(9e9, 9e9, 9e9)
        bv.Velocity = Vector3.new(0, 0, 0)
        bv.Parent = rootPart
        bg = Instance.new("BodyGyro")
        bg.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
        bg.P = 9e5
        bg.CFrame = rootPart.CFrame
        bg.Parent = rootPart
        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") and part.CanCollide then
                part.CanCollide = false
            end
        end
        flyConnection = RunService.Heartbeat:Connect(function()
            if not flying or not player.Character then return end
            local cam = workspace.CurrentCamera
            bg.CFrame = cam.CFrame
            local moveDir = humanoid.MoveDirection
            if moveDir.Magnitude > 0 then
                local flatLook = cam.CFrame.LookVector * Vector3.new(1, 0, 1)
                flatLook = flatLook.Magnitude > 0 and flatLook.Unit or Vector3.new(0, 0, -1)
                local flatRight = cam.CFrame.RightVector * Vector3.new(1, 0, 1)
                flatRight = flatRight.Magnitude > 0 and flatRight.Unit or Vector3.new(1, 0, 0)
                local forwardInput = flatLook:Dot(moveDir)
                local rightInput = flatRight:Dot(moveDir)
                local flyDir = (cam.CFrame.LookVector * forwardInput) + (cam.CFrame.RightVector * rightInput)
                if flyDir.Magnitude > 0 then
                    character:TranslateBy(flyDir.Unit * (flySpeed / 10))
                end
            end
        end)
    else
        if flyConnection then flyConnection:Disconnect() flyConnection = nil end
        if bv then bv:Destroy() bv = nil end
        if bg then bg:Destroy() bg = nil end
        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") then
                part.CanCollide = true
            end
        end
    end
end
local function updateFlySpeed(value)
    flySpeed = value
end
player.CharacterAdded:Connect(function(character)
    task.wait(0.5)
    if flying then
        toggleFly(false)
        task.wait(0.1)
        toggleFly(true)
    end
end)
