    task.spawn(function()
        while task.wait(FastAttackModule.Rate) do
            FastAttackModule.ExecuteFastAttack()
        end
    end)
    RunService.Heartbeat:Connect(function()
        pcall(HitRegistrationModule.Execute)
    end)
end
