local MARU_MUSIC_FOLDER = "MaruMusicPlayer"
local function MaruTrim(s) return (s:gsub("^%s+", ""):gsub("%s+$", "")) end
local function MaruDecode(s)
    return (s:gsub('\\"', '"'):gsub('\\/', '/'):gsub('\\\\', '\\'))
end
local function MaruParsePlaylist(raw)
    local out = {}
    for obj in raw:gmatch("%b{}") do
        local name   = obj:match('"name"%s*:%s*"(.-)"')
        local artist = obj:match('"artist"%s*:%s*"(.-)"')
        local url    = obj:match('"download_url"%s*:%s*"(.-)"')
        if name and url then
            name   = MaruDecode(name)
            artist = MaruDecode(artist or "Unknown")
            url    = MaruDecode(url)
            local genre = MaruDecode(obj:match('"genre"%s*:%s*"(.-)"') or "?")
            table.insert(out, {
                name   = MaruTrim(name),
                artist = MaruTrim(artist),
                url    = url,
                genre  = MaruTrim(genre),
                asset  = url:match("^rbxassetid://(%d+)$"),
                label  = MaruTrim(name) .. " — " .. MaruTrim(artist) .. " [" .. MaruTrim(genre) .. "]"
            })
        end
    end
    return out
end
local function MaruIsMySound(s)
    return s == MaruCurSound or s.Name == "MaruMusicSound"
end
local function MaruSetGameMuted(on)
    MaruMuted = on
    for _, item in ipairs(game:GetDescendants()) do
        if item:IsA("Sound") and not MaruIsMySound(item) then
            if on then
                if MaruOrigVolumes[item] == nil then MaruOrigVolumes[item] = item.Volume end
                item.Volume = 0
            elseif MaruOrigVolumes[item] ~= nil then
                item.Volume = MaruOrigVolumes[item]
                MaruOrigVolumes[item] = nil
            end
        end
    end
end
local function MaruStopMusic()
    if Library.MusicIsland then
        local mh = Library.MusicIsland
        Library.MusicIsland = nil
        pcall(function() mh:Stop() end)
    end
    if MaruEndConn then MaruEndConn:Disconnect(); MaruEndConn = nil end
    if MaruCurSound then
        pcall(function() MaruCurSound:Stop(); MaruCurSound:Destroy() end)
        MaruCurSound = nil
    end
end
local function MaruRandIdx(exclude)
    if #MaruPlaylist == 0 then return nil end
    if #MaruPlaylist == 1 then return 1 end
    local idx
    repeat idx = math.random(1, #MaruPlaylist) until idx ~= exclude
    return idx
end
local MaruPlayTrack
MaruPlayTrack = function(idx, keepCount)
    if #MaruPlaylist == 0 then
        pcall(function() Library:Notify({Title = "Music", Content = "Playlist trống.", Duration = 4}) end)
        return
    end
    if idx < 1 or idx > #MaruPlaylist then idx = 1 end
    local track = MaruPlaylist[idx]
    MaruTrackIdx = idx
    if not keepCount then Library.MusicX.Played = 0 end
    if not writefile or not (getcustomasset or getsynasset) then
        pcall(function() Library:Notify({Title = "Music", Content = "Executor không hỗ trợ writefile.", Duration = 5}) end)
        return
    end
    MaruStopMusic()
    pcall(function()
        local fxm0 = _G.FARMX
        if fxm0 and fxm0.Enable and fxm0.Enable.StatusPill and Library.NotifyYellow then
            Library:NotifyYellow({Text = "Đang tải: " .. track.label, Duration = 4})
        else
            Library:Notify({Title = "Music ♪", Content = "Đang tải: " .. track.label, Duration = 4})
        end
    end)
    task.spawn(function()
        local fname = MARU_MUSIC_FOLDER .. "/track_" .. idx .. ".mp3"
        if not track.asset and not (isfile and isfile(fname)) then
            local ok, data
            if _G.FARMX and _G.FARMX.NetGet then ok, data = _G.FARMX.NetGet(track.url) else ok, data = pcall(function() return game:HttpGet(track.url) end) end
            if not ok or not data or #data == 0 then
                pcall(function()
                    local fxm1 = _G.FARMX
                    if fxm1 and fxm1.Enable and fxm1.Enable.StatusPill and Library.NotifyRed then
                        Library:NotifyRed({Text = "Lỗi tải: " .. track.name, Duration = 6})
                    else
                        Library:Notify({Title = "Music", Content = "Lỗi tải: " .. track.name, Duration = 6})
                    end
                end)
                return
            end
            pcall(function() writefile(fname, data) end)
        end
        if MaruTrackIdx ~= idx then return end
        local getAsset = getcustomasset or getsynasset
        local ok, assetId = pcall(function() if track.asset then return "rbxassetid://" .. track.asset end return getAsset(fname) end)
        if not ok or not assetId then
            pcall(function() Library:Notify({Title = "Music", Content = "Lỗi asset.", Duration = 4}) end)
            return
        end
        if MaruTrackIdx ~= idx then return end
        local snd = Instance.new("Sound")
        snd.Name = "MaruMusicSound"
        snd.SoundId = assetId
        snd.Volume = MaruVol
        snd.Looped = (Library.MusicX.Loop == "one" and (Library.MusicX.LoopCount or 0) == 0)
        snd.Parent = MaruSoundService
        MaruCurSound = snd
        MaruEndConn = snd.Ended:Connect(function()
            if MaruCurSound ~= snd then return end
            MaruCurSound = nil
            if MaruEndConn then MaruEndConn:Disconnect(); MaruEndConn = nil end
            snd:Destroy()
            local MX = Library.MusicX
            if MX.Loop == "one" then
                MX.Played = (MX.Played or 0) + 1
                if (MX.LoopCount or 0) == 0 or MX.Played < MX.LoopCount then
                    task.wait(0.15)
                    MaruPlayTrack(idx, true)
                    return
                end
                MX.Played = 0
            elseif MX.Loop == "fav" then
                local nx = MX.nextFav(idx)
                if nx then
                    task.wait(0.25)
                    MaruPlayTrack(nx)
                    return
                end
            end
            if MaruAutoNext then
                task.wait(0.25)
                if MaruShuffle then MaruPlayTrack(MaruRandIdx(idx))
                else MaruPlayTrack((idx % #MaruPlaylist) + 1) end
            end
        end)
        snd:Play()
        local mediaOk = false
        pcall(function()
            local isl = Library.WindUI.Island
            if not isl then return end
            local h
            h = isl:Media({
                Title = track.name, Artist = track.artist or "Music Player", Playing = true,
                Position = 0, Length = snd.TimeLength,
                OnPlay = function(p)
                    if MaruCurSound == snd then
                        if p then snd:Resume() else snd:Pause() end
                    end
                end,
                OnPrev = function() if #MaruPlaylist > 0 then MaruPlayTrack(((idx - 2) % #MaruPlaylist) + 1) end end,
                OnNext = function() if #MaruPlaylist > 0 then MaruPlayTrack((idx % #MaruPlaylist) + 1) end end,
            })
            if not h then return end
            Library.MusicIsland = h
            mediaOk = true
            task.spawn(function()
                while MaruCurSound == snd and Library.MusicIsland == h do
                    pcall(function() h:Set({ Position = snd.TimePosition, Length = snd.TimeLength, Playing = snd.IsPlaying }) end)
                    task.wait(0.5)
                end
            end)
        end)
        local fxm = _G.FARMX
        if not mediaOk and MaruCurSound == snd and not (fxm and fxm.Enable and fxm.Enable.MusicPlayingNotice == false) then
            pcall(function()
                if fxm and fxm.Enable and fxm.Enable.StatusPill and Library.NotifyGreen then
                    Library:NotifyGreen({Text = "Đang phát: " .. track.label, Duration = 3})
                else
                    Library:Notify({Title = "Music ♪", Content = "Đang phát: " .. track.label, Duration = 3})
                end
            end)
        end
    end)
end
Library.MusicX.n = function() return #MaruPlaylist end
Library.MusicX.track = function(i) return MaruPlaylist[i] end
Library.MusicX.cur = function() return MaruTrackIdx, (MaruCurSound ~= nil and MaruCurSound.IsPlaying == true) end
Library.MusicX.play = function(i) if i and MaruPlaylist[i] then MaruPlayTrack(i) end end
Library.MusicX.next = function() if #MaruPlaylist > 0 then MaruPlayTrack((MaruTrackIdx % #MaruPlaylist) + 1) end end
Library.MusicX.prev = function() if #MaruPlaylist > 0 then MaruPlayTrack(((MaruTrackIdx - 2) % #MaruPlaylist) + 1) end end
Library.MusicX.rand = function() local i = MaruRandIdx(MaruTrackIdx); if i then MaruPlayTrack(i) end end
Library.MusicX.stop = function() MaruStopMusic() end
Library.MusicX.pause = function(on)
    if not MaruCurSound then return false end
    pcall(function() if on then MaruCurSound:Pause() else MaruCurSound:Resume() end end)
    return true
end
Library.MusicX.vol = function(n)
    n = math.clamp(tonumber(n) or 100, 0, 100)
    MaruVol = n / 100
    if MaruCurSound then MaruCurSound.Volume = MaruVol end
    local o = Library.Options["Music_mLng"]
    if o then o:SetValue(n) end
    return n
end
Library.MusicX.setLoop = function(mode, count)
    local MX = Library.MusicX
    if mode ~= "one" and mode ~= "fav" then mode = "off" end
    MX.Loop = mode
    MX.LoopCount = math.max(0, math.floor(tonumber(count) or 0))
    MX.Played = 0
    if MaruCurSound then MaruCurSound.Looped = (mode == "one" and MX.LoopCount == 0) end
    local o1 = Library.Options["Music_LoopMode"]
    if o1 then o1:SetValue(MX.LoopLabels[mode]) end
    local o2 = Library.Options["Music_LoopCount"]
    if o2 then o2:SetValue(MX.LoopCount) end
end
Library.MusicX.loopText = function()
    local MX = Library.MusicX
    if MX.Loop == "one" then return (MX.LoopCount or 0) == 0 and "1 bài (vô hạn)" or ("1 bài x" .. MX.LoopCount) end
    if MX.Loop == "fav" then return "bài yêu thích" end
    return "tắt"
end
Library.MusicX.favList = function()
    local out = {}
    for i, t in ipairs(MaruPlaylist) do
        if Library.MusicX.Fav[t.name] then out[#out + 1] = i end
    end
    return out
end
Library.MusicX.isFav = function(i)
    local t = MaruPlaylist[i]
    return t ~= nil and Library.MusicX.Fav[t.name] == true
end
Library.MusicX.nextFav = function(idx)
    local fl = Library.MusicX.favList()
    if #fl == 0 then return nil end
    for _, i in ipairs(fl) do
        if i > idx then return i end
    end
    return fl[1]
end
Library.MusicX.labels = function(only)
    local out = {}
    for i, t in ipairs(MaruPlaylist) do
        if not only or only[i] then out[#out + 1] = string.format("%02d. %s - %s", i, t.name, t.artist) end
    end
    if #out == 0 then out[1] = "(chưa có)" end
    return out
end
Library.MusicX.favSave = function()
    if not writefile then return end
    pcall(function()
        if makefolder and isfolder and not isfolder(MARU_MUSIC_FOLDER) then makefolder(MARU_MUSIC_FOLDER) end
        local names = {}
        for n in pairs(Library.MusicX.Fav) do names[#names + 1] = n end
        table.sort(names)
        writefile(MARU_MUSIC_FOLDER .. "/favorites.txt", table.concat(names, "\n"))
    end)
end
Library.MusicX.favLoad = function()
    if not (readfile and isfile) then return end
    pcall(function()
        local f = MARU_MUSIC_FOLDER .. "/favorites.txt"
        if isfile(f) then
            for line in string.gmatch(readfile(f), "[^\r\n]+") do Library.MusicX.Fav[line] = true end
        end
    end)
end
Library.MusicX.favRefresh = function()
    local only = {}
    for _, i in ipairs(Library.MusicX.favList()) do only[i] = true end
    local o = Library.Options["Music_FavSelect"]
    if o then o:SetValues(Library.MusicX.labels(only)) end
end
Library.MusicX.fav = function(i)
    i = i or MaruTrackIdx
    local t = MaruPlaylist[i]
    if not t then return nil end
    local MX = Library.MusicX
    if MX.Fav[t.name] then MX.Fav[t.name] = nil else MX.Fav[t.name] = true end
    MX.favSave()
    pcall(MX.favRefresh)
    return MX.Fav[t.name] == true
end
Library.MusicX.boot = function()
    local parsed = MaruParsePlaylist(Library.MusicRaw)
    if #parsed > 0 then
        MaruPlaylist = parsed
        MaruFiltered = {}
        for i, t in ipairs(MaruPlaylist) do table.insert(MaruFiltered, {index = i, track = t}) end
    end
    Library.MusicX.favLoad()
    task.delay(1.5, function() Library.MusicX.ready = true end)
end
Library.MusicX.boot()
local function MaruLoadPlaylist()
    if MaruLoading then return end
    MaruLoading = true
    local ok, raw = true, Library.MusicRaw
    if MARU_PLAYLIST_URL ~= "" then if _G.FARMX and _G.FARMX.NetGet then ok, raw = _G.FARMX.NetGet(MARU_PLAYLIST_URL) else ok, raw = pcall(function() return game:HttpGet(MARU_PLAYLIST_URL) end) end end
    if not ok or not raw or #raw == 0 then
        MaruLoading = false
        pcall(function() Library:Notify({Title = "Music", Content = "Lỗi tải playlist!", Duration = 7}) end)
        return
    end
    local parsed = MaruParsePlaylist(raw)
    if #parsed == 0 then
        MaruLoading = false
        pcall(function() Library:Notify({Title = "Music", Content = "Không tìm thấy bài hát!", Duration = 7}) end)
        return
    end
    MaruPlaylist = parsed
    MaruLoading = false
    MaruFiltered = {}
    for i, t in ipairs(MaruPlaylist) do
        table.insert(MaruFiltered, {index = i, track = t})
    end
    pcall(function() Library:Notify({Title = "Music", Content = "Đã tải " .. #MaruPlaylist .. " bài hát.", Duration = 5}) end)
end
