  topC.Visible = true
  local TS = game:GetService("TweenService")
  local t0 = os.clock()
  local GREEN, DARK = Color3.fromRGB(72, 214, 150), Color3.fromRGB(12, 40, 33)
  local function fmt(n) n = tonumber(n) or 0 local s = tostring(math.floor(n)) local k repeat s, k = string.gsub(s, "^(-?%d+)(%d%d%d)", "%1,%2") until k == 0 return s end
  local function clock() local t = math.floor(os.clock() - t0) return string.format("%02d:%02d", math.floor(t / 60), t % 60) end
  local pill = Instance.new("TextButton")
  pill.Name = "WAPill"
  pill.AutoButtonColor = false
  pill.Text = ""
  pill.Size = UDim2.fromOffset(112, 24)
