  lab.Text = "Running · 00:00"
  local card = Instance.new("Frame")
  card.Name = "WAPillCard"
  card.Visible = false
  card.BackgroundColor3 = DARK
  card.BorderSizePixel = 0
  card.ClipsDescendants = true
  card.ZIndex = 200
  card.Parent = main.Main
  Instance.new("UICorner", card).CornerRadius = UDim.new(0, 16)
  local cst = Instance.new("UIStroke", card)
  cst.Color = GREEN
  cst.Transparency = 0.55
  local title = Instance.new("TextLabel", card)
  title.BackgroundTransparency = 1
  title.Position = UDim2.fromOffset(14, 8)
  title.Size = UDim2.new(1, -28, 0, 14)
  title.Font = Enum.Font.GothamMedium
  title.TextSize = 11
  title.TextColor3 = GREEN
  title.TextXAlignment = Enum.TextXAlignment.Left
  title.ZIndex = 201
  local vals = {}
  for i, name in ipairs({ "Beli", "Fragments" }) do
    local cap = Instance.new("TextLabel", card)
    cap.BackgroundTransparency = 1
    cap.Position = UDim2.new((i - 1) / 2, 14, 0, 28)
    cap.Size = UDim2.new(1 / 2, -14, 0, 12)
    cap.Font = Enum.Font.Gotham
    cap.TextSize = 10
    cap.TextColor3 = Color3.fromRGB(120, 190, 160)
    cap.TextXAlignment = Enum.TextXAlignment.Left
    cap.Text = name
    cap.ZIndex = 201
    local v = Instance.new("TextLabel", card)
    v.BackgroundTransparency = 1
    v.Position = UDim2.new((i - 1) / 2, 14, 0, 42)
    v.Size = UDim2.new(1 / 2, -14, 0, 18)
    v.Font = Enum.Font.GothamBold
    v.TextSize = 13
    v.TextColor3 = Color3.new(1, 1, 1)
    v.TextXAlignment = Enum.TextXAlignment.Left
    v.ZIndex = 201
    vals[i] = v
  end
  local function refresh()
    local data = plr and plr:FindFirstChild("Data")
    local beli = data and data:FindFirstChild("Beli")
    local frag = data and data:FindFirstChild("Fragments")
    vals[1].Text = beli and fmt(beli.Value) or "--"
    vals[2].Text = frag and fmt(frag.Value) or "--"
    title.Text = "Running · " .. clock()
  end
  local open, tok = false, 0
  local function place()
    local u = (Library.WindUI and Library.WindUI.UIScale) or 1
    local rel = (pill.AbsolutePosition - main.Main.AbsolutePosition) / u
    return rel
  end
  local function setOpen(on)
    tok = tok + 1
    local my = tok
    open = on
    local rel = place()
    if on then
      refresh()
      card.Position = UDim2.fromOffset(rel.X, rel.Y)
      card.Size = UDim2.fromOffset(112, 24)
      card.Visible = true
      pill.Visible = false
      TS:Create(card, TweenInfo.new(0.46, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Size = UDim2.fromOffset(232, 72), Position = UDim2.fromOffset(rel.X - 60, rel.Y) }):Play()
      task.delay(4.5, function() if tok == my and open then setOpen(false) end end)
    else
      local t = TS:Create(card, TweenInfo.new(0.26, Enum.EasingStyle.Quint, Enum.EasingDirection.In), { Size = UDim2.fromOffset(112, 24), Position = UDim2.fromOffset(rel.X, rel.Y) })
      t.Completed:Connect(function() if tok == my then card.Visible = false pill.Visible = true end end)
      t:Play()
