    if _G.AimCam then
      return "Aimbot Camera"
    end

    if _G.AimbotGun then
      return "Aimbot Guns"
    end
    return ""
  end

  local n60 = nil

  spawn(function()
    n60 = 345692894

    if wait(0.2) then
      local v2, v3

      repeat
        pcall(function()
          if _G.AimMethod then
            if _G.AimCam then
              aimbotStatusParagraph:SetDesc("Aimbot - " .. Checking_AimStatus() .. " : True")
            elseif _G.AimbotGun then
