do
local function HiruMain()
    local Players = game:GetService("Players")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local TweenService = game:GetService("TweenService")
    local TeleportService = game:GetService("TeleportService")

    local player = Players.LocalPlayer
    local commF = ReplicatedStorage:WaitForChild("Remotes"):WaitForChild("CommF_")

    local cfg = {
        TweenSpeed = 200,
        PosX = 0,
        PosY = 15,
        PosZ = 0,
        RandomCFrame = false,
        BringMob = true,
        AutoFarmLevel = false,
        TeleportIsland = false,
        RandomDevilFruit = false,
        SelectIsland = nil,
        SelectWeapon = nil,
    }

    local placeId = game.PlaceId
    local World1 = placeId == 2753915549 or placeId == 85211729168715
    local World2 = placeId == 4442272183 or placeId == 79091703265657
    local World3 = placeId == 7449423635 or placeId == 100117331123089

    local isTweening = false

    local function stopTween()
        isTweening = false
        local character = player.Character
        if character then
            local part = character:FindFirstChild("PartTele")
            if part then
                part:Destroy()
            end
        end
    end

    local function topos(targetCFrame)
        if not targetCFrame then
            return
        end
        local character = player.Character
        if not character then
            return
        end
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local root = character:FindFirstChild("HumanoidRootPart")
        if not humanoid or humanoid.Health <= 0 or not root then
            return
        end

        local distance = (targetCFrame.Position - root.Position).Magnitude

        if not character:FindFirstChild("PartTele") then
            local partTele = Instance.new("Part")
            partTele.Name = "PartTele"
            partTele.Parent = character
            partTele.Size = Vector3.new(10, 1, 10)
            partTele.Anchored = true
            partTele.Transparency = 1
            partTele.CanCollide = true
            partTele.CFrame = root.CFrame
            partTele:GetPropertyChangedSignal("CFrame"):Connect(function()
                if not isTweening then
                    return
                end
                task.wait()
                local currentCharacter = player.Character
                if currentCharacter and currentCharacter:FindFirstChild("HumanoidRootPart") then
                    currentCharacter.HumanoidRootPart.CFrame = partTele.CFrame
                end
            end)
        end

        isTweening = true

        local speed = cfg.TweenSpeed
        if speed <= 0 then
            speed = 200
        end

        local tween = TweenService:Create(
            character.PartTele,
            TweenInfo.new(distance / speed, Enum.EasingStyle.Linear),
            {CFrame = targetCFrame}
        )
        tween:Play()
        tween.Completed:Connect(function(state)
            if state == Enum.PlaybackState.Completed then
                if player.Character then
                    local part = player.Character:FindFirstChild("PartTele")
                    if part then
                        part:Destroy()
                    end
                end
                isTweening = false
            end
        end)
    end

    task.spawn(function()
        while task.wait() do
            if not isTweening then
                stopTween()
            end
        end
    end)

    task.spawn(function()
        while task.wait() do
            pcall(function()
                local character = player.Character
                if not character then
                    return
                end
                local root = character:FindFirstChild("HumanoidRootPart")
                local partTele = character:FindFirstChild("PartTele")
                if root and partTele then
                    if (root.Position - partTele.Position).Magnitude >= 100 then
                        stopTween()
                    end
                end
            end)
        end
    end)

    local function hookCharacter(character)
        local humanoid = character:WaitForChild("Humanoid")
        humanoid.Died:Connect(function()
            stopTween()
        end)
    end

    player.CharacterAdded:Connect(hookCharacter)
    if player.Character then
        task.spawn(hookCharacter, player.Character)
    end

    local function autoHaki()
        local character = player.Character
        if character and not character:FindFirstChild("HasBuso") then
            commF:InvokeServer("Buso")
        end
    end

    local function pickWeapon()
        local name = cfg.SelectWeapon or _G.SelectWeapon
        local character = player.Character
        if name and (player.Backpack:FindFirstChild(name) or (character and character:FindFirstChild(name))) then
            return name
        end
        for _, container in ipairs({player.Backpack, character}) do
            if container then
                for _, tool in ipairs(container:GetChildren()) do
                    if tool:IsA("Tool") and tool.ToolTip == "Melee" then
                        return tool.Name
                    end
                end
            end
        end
        return nil
    end

    local function equipWeapon()
        local character = player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if not humanoid then
            return
        end
        local name = pickWeapon()
        if not name or character:FindFirstChild(name) then
            return
        end
        local tool = player.Backpack:FindFirstChild(name)
        if tool then
            humanoid:EquipTool(tool)
        end
    end

    local function isAlive(model)
        if not model then
            return false
        end
        local humanoid = model:FindFirstChild("Humanoid")
        return humanoid ~= nil and humanoid.Health > 0
    end

    local function getEnemiesFolder()
        local folder = workspace:FindFirstChild("Enemies")
        if folder then
            return folder
        end
        local origin = workspace:FindFirstChild("_WorldOrigin")
        if origin then
            return origin:FindFirstChild("Enemies")
        end
        return nil
    end

    local RunService = game:GetService("RunService")
    local pack = {}
    local packName = nil
    local packAnchor = nil
    local PACK_SIZE = 5
    local ACTIVE_SIZE = 2
    local WAIT_OFFSET = Vector3.new(90, 0, 0)
    local BRING_RADIUS = 500

    local function slotPosition(index)
        if index <= ACTIVE_SIZE then
            return packAnchor
        end
        return packAnchor + WAIT_OFFSET
    end

    local function pinEnemy(enemy, position)
        pcall(function()
            local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
            if not enemyRoot then
                return
            end
            local bodyPosition = enemyRoot:FindFirstChild("HiruHubBringMob")
            if not bodyPosition then
                bodyPosition = Instance.new("BodyPosition")
                bodyPosition.Name = "HiruHubBringMob"
                bodyPosition.Parent = enemyRoot
            end
            bodyPosition.MaxForce = Vector3.new(1000000000, 1000000000, 1000000000)
            bodyPosition.P = 30000
            bodyPosition.D = 1000
            bodyPosition.Position = position
            enemyRoot.CanCollide = false
        end)
    end

    local function releaseEnemy(enemy)
        pcall(function()
            local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
            local bodyPosition = enemyRoot and enemyRoot:FindFirstChild("HiruHubBringMob")
            if bodyPosition then
                bodyPosition:Destroy()
            end
        end)
    end

    local function releasePack()
        for _, enemy in ipairs(pack) do
            releaseEnemy(enemy)
        end
        pack = {}
        packName = nil
        packAnchor = nil
    end

    local function inPack(enemy)
        for _, member in ipairs(pack) do
            if member == enemy then
                return true
            end
        end
        return false
    end

    local function bringEnemy(target)
        if not cfg.BringMob then
            if #pack > 0 then
                releasePack()
            end
            return target
        end
        local character = player.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if not root then
            return target
        end

        local folder = getEnemiesFolder()
        if not folder or not target or not target:IsDescendantOf(folder) then
            return pack[1] or target
        end

        pcall(function()
            if sethiddenproperty then
                sethiddenproperty(player, "SimulationRadius", math.huge)
            end
        end)

        if packName ~= target.Name then
            releasePack()
            packName = target.Name
        end

        local alive = {}
        for _, enemy in ipairs(pack) do
            if enemy.Parent and isAlive(enemy) then
                table.insert(alive, enemy)
            else
                releaseEnemy(enemy)
            end
        end
        pack = alive

        local targetRoot = target:FindFirstChild("HumanoidRootPart")
        if not packAnchor or #pack == 0 or (packAnchor - root.Position).Magnitude > 250 then
            if targetRoot and isAlive(target) then
                packAnchor = targetRoot.Position
            end
        end
        if not packAnchor then
            return target
        end

        if #pack < PACK_SIZE then
            local candidates = {}
            for _, enemy in ipairs(folder:GetChildren()) do
                if enemy.Name == packName and isAlive(enemy) and not inPack(enemy) then
                    local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
                    if enemyRoot then
                        local distance = (enemyRoot.Position - packAnchor).Magnitude
                        if distance <= BRING_RADIUS then
                            table.insert(candidates, {enemy = enemy, distance = distance})
                        end
                    end
                end
            end
            table.sort(candidates, function(x, y)
                return x.distance < y.distance
            end)
            for _, item in ipairs(candidates) do
                if #pack >= PACK_SIZE then
                    break
                end
                table.insert(pack, item.enemy)
            end
        end

        for index, enemy in ipairs(pack) do
            pinEnemy(enemy, slotPosition(index))
        end

        return pack[1] or target
    end

    RunService.Heartbeat:Connect(function()
        if not cfg.BringMob or not cfg.AutoFarmLevel or not packAnchor then
            return
        end
        for index, enemy in ipairs(pack) do
            local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
            local humanoid = enemy:FindFirstChildOfClass("Humanoid")
            if enemyRoot and humanoid and humanoid.Health > 0 then
                enemyRoot.CFrame = CFrame.new(slotPosition(index))
                enemyRoot.CanCollide = false
                enemyRoot.AssemblyLinearVelocity = Vector3.zero
                humanoid.WalkSpeed = 0
            end
        end
    end)

    local function spinAround(enemy, delay)
        if not enemy or not enemy:FindFirstChild("HumanoidRootPart") then
            return
        end
        local offsets = {
            CFrame.new(0, 30, 25),
            CFrame.new(25, 30, 0),
            CFrame.new(-25, 30, 0),
        }
        for _, offset in ipairs(offsets) do
            if not isAlive(enemy) then
                break
            end
            local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
            if not enemyRoot then
                break
            end
            topos(enemyRoot.CFrame * offset)
            task.wait(delay)
        end
    end

    local function kill(enemy)
        if not enemy or not isAlive(enemy) then
            return
        end
        local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
        if not enemyRoot then
            return
        end
        autoHaki()
        equipWeapon()
        local focus = bringEnemy(enemy) or enemy
        local focusRoot = focus:FindFirstChild("HumanoidRootPart")
        if not focusRoot or not isAlive(focus) then
            return
        end
        topos(focusRoot.CFrame * CFrame.new(cfg.PosX, cfg.PosY, cfg.PosZ))
        if cfg.RandomCFrame then
            spinAround(focus, 0.1)
        end
    end

    local okQuests, questModule = pcall(function()
        return require(ReplicatedStorage:WaitForChild("Quests", 15))
    end)
    if not okQuests or type(questModule) ~= "table" then
        questModule = {}
    end

    local okGuide, guideModule = pcall(function()
        return require(ReplicatedStorage:WaitForChild("GuideModule", 15))
    end)
    local npcList = {}
    if okGuide and type(guideModule) == "table" and guideModule.Data and guideModule.Data.NPCList then
        npcList = guideModule.Data.NPCList
    end

    local ignoredQuests = {
        BartiloQuest = true,
        CitizenQuest = true,
        ImpelQuest = true,
    }

    local function getLevel()
        local ok, value = pcall(function()
            return player.Data.Level.Value
        end)
        if not ok then
            return 1
        end
        return tonumber(value) or 1
    end

    local function positionOf(instance)
        if instance:IsA("BasePart") then
            return instance.Position
        end
        if instance:IsA("Model") then
            return instance:GetPivot().Position
        end
        return nil
    end

    local function getMobSpawnPosition(mobName)
        if not mobName then
            return nil
        end

        local origin = workspace:FindFirstChild("_WorldOrigin")
        local spawns = origin and origin:FindFirstChild("EnemySpawns")
        if spawns then
            for _, spawnPoint in ipairs(spawns:GetChildren()) do
                if spawnPoint.Name:find(mobName, 1, true) then
                    local position = positionOf(spawnPoint)
                    if position then
                        return position
                    end
                end
            end
        end

        local fortFolder = ReplicatedStorage:FindFirstChild("FortBuilderReplicatedSpawnPositionsFolder")
        if fortFolder then
            local entry = fortFolder:FindFirstChild(mobName)
            if entry then
                local position = positionOf(entry)
                if position then
                    return position
                end
            end
        end

        local enemies = workspace:FindFirstChild("Enemies")
        if enemies then
            for _, enemy in ipairs(enemies:GetChildren()) do
                if enemy.Name == mobName then
                    local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
                    if enemyRoot then
                        return enemyRoot.Position
                    end
                end
            end
        end

        return nil
    end

    local function getQuestForLevel()
        local level = getLevel()
        local teamName = (player.Team and player.Team.Name) or "Pirates"

        local preferredTask = false
        if level < 10 then
            if teamName == "Marines" then
                preferredTask = "trainee"
            else
                preferredTask = "bandit"
            end
        end

        local bestQuestId = nil
        local bestQuestData = nil
        local bestLevelReq = -1

        for questId, questData in pairs(questModule) do
            if not ignoredQuests[questId] and type(questData) == "table" then
                local firstEntry = questData[1]
                if firstEntry and firstEntry.LevelReq and firstEntry.LevelReq <= level then
                    local matches = true
                    if preferredTask then
                        matches = false
                        for taskKey in pairs(firstEntry.Task or {}) do
                            if tostring(taskKey):lower():find(preferredTask, 1, true) then
                                matches = true
                                break
                            end
                        end
                    end
                    if matches and bestLevelReq < firstEntry.LevelReq then
                        bestLevelReq = firstEntry.LevelReq
                        bestQuestId = questId
                        bestQuestData = questData
                    end
                end
            end
        end

        if not bestQuestData then
            return nil
        end

        local subIndex = 1
        for index, entry in ipairs(bestQuestData) do
            if entry and entry.LevelReq and entry.LevelReq <= level then
                subIndex = index
            end
        end

        local entry = bestQuestData[subIndex] or bestQuestData[#bestQuestData]

        local mobName = nil
        for taskKey in pairs(entry.Task or {}) do
            mobName = taskKey
        end

        local spawnPosition = getMobSpawnPosition(mobName)
        local character = player.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local referencePosition = spawnPosition or (root and root.Position) or Vector3.zero

        local npcCFrame = nil
        local bestDistance = math.huge
        for npcInstance, npcInfo in pairs(npcList) do
            if npcInfo and npcInfo.Levels and table.find(npcInfo.Levels, entry.LevelReq) then
                local cframe = nil
                if typeof(npcInstance) == "Instance" then
                    if npcInstance:IsA("BasePart") then
                        cframe = npcInstance.CFrame
                    elseif npcInstance:IsA("Model") then
                        cframe = npcInstance:GetPivot()
                    end
                end
                if cframe then
                    local distance = (cframe.Position - referencePosition).Magnitude
                    if distance < bestDistance then
                        bestDistance = distance
                        npcCFrame = cframe
                    end
                end
            end
        end

        return {
            QuestId = bestQuestId,
            SubIndex = subIndex,
            MobName = mobName,
            NpcCFrame = npcCFrame,
            LevelReq = entry.LevelReq,
        }
    end

    local function hasActiveQuest()
        local playerGui = player:FindFirstChild("PlayerGui")
        if not playerGui then
            return false
        end

        local tracked = playerGui:FindFirstChild("TrackedQuestFrame")
        if tracked and tracked.Enabled then
            local frame = tracked:FindFirstChild("Frame")
            if frame and frame.Visible then
                return true
            end
        end

        local main = playerGui:FindFirstChild("Main")
        if main then
            local quest = main:FindFirstChild("Quest")
            if quest and quest.Visible then
                local container = quest:FindFirstChild("Container")
                if container then
                    local questTitle = container:FindFirstChild("QuestTitle")
                    local title = questTitle and questTitle:FindFirstChild("Title")
                    if title and title.Text and title.Text ~= "" and title.Text ~= "QUEST" then
                        return true
                    end
                end
            end
        end

        return false
    end

    local function findNearestMob(mobName)
        local enemies = workspace:FindFirstChild("Enemies")
        if not enemies then
            return nil
        end

        local character = player.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local referencePosition = (root and root.Position) or Vector3.zero

        local nearest = nil
        local nearestDistance = math.huge
        for _, enemy in ipairs(enemies:GetChildren()) do
            if enemy.Name == mobName then
                local humanoid = enemy:FindFirstChildOfClass("Humanoid")
                local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
                if humanoid and enemyRoot and humanoid.Health > 0 then
                    local distance = (enemyRoot.Position - referencePosition).Magnitude
                    if distance < nearestDistance then
                        nearestDistance = distance
                        nearest = enemy
                    end
                end
            end
        end
        return nearest
    end

    local function travelToNextSeaIfNeeded(level)
        if World1 and level >= 700 then
            pcall(function()
                commF:InvokeServer("TravelDressrosa")
            end)
            task.wait(3)
            pcall(function()
                TeleportService:Teleport(4442272183, player)
            end)
            return true
        end
        if World2 and level >= 1500 then
            pcall(function()
                commF:InvokeServer("TravelZou")
            end)
            task.wait(3)
            pcall(function()
                TeleportService:Teleport(7449423635, player)
            end)
            return true
        end
        return false
    end

    task.spawn(function()
        while task.wait(0.1) do
            if cfg.AutoFarmLevel then
                pcall(function()
                    local character = player.Character
                    if not character then
                        return
                    end
                    local root = character:FindFirstChild("HumanoidRootPart")
                    local humanoid = character:FindFirstChildOfClass("Humanoid")
                    if not root or not humanoid or humanoid.Health <= 0 then
                        return
                    end

                    local level = getLevel()
                    if travelToNextSeaIfNeeded(level) then
                        task.wait(5)
                        return
                    end

                    local quest = getQuestForLevel()
                    if not quest or not quest.MobName then
                        return
                    end

                    if not hasActiveQuest() then
                        if not quest.NpcCFrame then
                            return
                        end
                        topos(quest.NpcCFrame + Vector3.new(0, 4, 3))
                        if (root.Position - quest.NpcCFrame.Position).Magnitude <= 18 then
                            task.wait(0.5)
                            commF:InvokeServer("StartQuest", quest.QuestId, quest.SubIndex)
                            task.wait(1)
                        end
                        return
                    end

                    local mob = findNearestMob(quest.MobName)
                    if mob then
                        kill(mob)
                    end
                end)
            end
        end
    end)

