            local remote = ReplicatedStorage.Modules.Net:FindFirstChild("RF/SubmarineWorkerSpeak")
            if remote then
                remote:InvokeServer("TravelToSubmergedIsland")
            end
        end
    end

    local teleportToken = 0

    local function setTeleportIsland(enabled)
        cfg.TeleportIsland = enabled
        teleportToken += 1
        if not enabled then
            stopTween()
            return
        end
        local token = teleportToken
        task.spawn(function()
            while cfg.TeleportIsland and token == teleportToken do
                local action = islandActions[cfg.SelectIsland]
                if action then
                    pcall(action)
                end
                task.wait(0.2)
            end
        end)
    end

    task.spawn(function()
        while task.wait(1) do
            if cfg.RandomDevilFruit then
                pcall(function()
                    commF:InvokeServer("Cousin", "Buy")
                end)
            end
        end
    end)

    local function tabFor(key, title)
        return ShinTabs[key] or ShinWin:AddTab(title)
    end

    local function placeFirst(tab, build)
        tab.Items = tab.Items or {}
        local before = #tab.Items
        build()
        local mine = {}
        for index = #tab.Items, before + 1, -1 do
            table.insert(mine, 1, table.remove(tab.Items, index))
        end
        if #mine == 0 then
            return
        end
        local isMine = {}
        for _, frame in ipairs(mine) do
            isMine[frame] = true
        end
        for _, child in ipairs(tab.Page:GetChildren()) do
            if child:IsA("GuiObject") and not isMine[child] and child.LayoutOrder >= 1 then
                child.LayoutOrder = child.LayoutOrder + #mine + 1
            end
        end
        for index, frame in ipairs(mine) do
            frame.LayoutOrder = index
            table.insert(tab.Items, index, frame)
        end
        if tab.SearchBox then
            local firstHeader = nil
            for _, frame in ipairs(mine) do
                local info = tab.Meta and tab.Meta[frame]
                if info and info.kind == "header" then
                    firstHeader = frame
                    break
                end
            end
            for header in pairs(tab.Collapsed or {}) do
                tab.Collapsed[header] = true
            end
            if firstHeader then
                tab.Collapsed[firstHeader] = false
            end
            tab:BuildGroups()
        end
    end

    local farmTab = tabFor("farming", "Farming")
    local travelTab = tabFor("teleport", "Teleport")
    local fruitTab = tabFor("fruit", "Fruit")

    pcall(function()
        local mirageTab = ShinTabs.mirageandrace
        if mirageTab and mirageTab.Lbl then
            mirageTab.Lbl.Text = "Mirage"
        end
    end)

    local statusCard = nil

    local function statusText()
        local names = {}
        for _, entry in ipairs(Shin.Toggles or {}) do
            if entry.Obj and entry.Obj.Value then
                table.insert(names, entry.Text)
            end
        end
        if #names == 0 then
            return "Chưa bật chức năng nào"
        end
        local lines = {}
        for index, name in ipairs(names) do
            if index > 10 then
                table.insert(lines, "... và " .. (#names - 10) .. " chức năng khác")
                break
            end
            table.insert(lines, "● " .. tostring(name))
        end
        return table.concat(lines, "\n")
    end

    placeFirst(farmTab, function()
        statusCard = Core.Paragraph(farmTab, "Đang Bật", statusText())
        Core.Section(farmTab, "Auto Farm Level")
        Core.Toggle(farmTab, "Auto Farm Level", "Tự động nhận quest, gom quái và đánh", false, function(value)
            cfg.AutoFarmLevel = value
            if value then
                pcall(function()
                    _G.Level = false
                    _G.ActiveFarm = nil
                    if _G.FARMX and _G.FARMX.ApplyMode then
                        _G.FARMX.ApplyMode("None")
                    end
                end)
            else
                stopTween()
                releasePack()
            end
        end)
        Core.Toggle(farmTab, "Random CFrame", "Di chuyển ngẫu nhiên quanh quái khi farm", false, function(value)
            cfg.RandomCFrame = value
        end)
        Core.Slider(farmTab, "Tween Speed", 50, 350, cfg.TweenSpeed, 10, function(value)
            cfg.TweenSpeed = tonumber(value) or 200
        end)
    end)

    if #islandOrder > 0 then
        placeFirst(travelTab, function()
            Core.Section(travelTab, "Teleport Island")
            Core.Dropdown(travelTab, "Select Island", nil, islandOrder, nil, false, function(value)
                cfg.SelectIsland = value
            end)
            Core.Toggle(travelTab, "Teleport Island", "Bay tới đảo đã chọn", false, function(value)
                setTeleportIsland(value)
            end)
        end)
    end

    placeFirst(fruitTab, function()
        Core.Section(fruitTab, "Random Fruit")
        Core.Toggle(fruitTab, "Random Devil Fruit", "Tự động mua trái ác quỷ ngẫu nhiên", false, function(value)
            cfg.RandomDevilFruit = value
        end)
    end)

    for _, name in ipairs({"Auto Farm Level", "Random CFrame", "Tween Speed", "Select Island", "Teleport Island", "Random Devil Fruit"}) do
        reg(name)
    end

    task.spawn(function()
        while task.wait(1) do
            if statusCard then
                pcall(function()
                    statusCard:SetDesc(statusText())
                end)
            end
        end
    end)
end

task.spawn(function()
    if getgenv().__ShinChatSent then
        return
    end
    getgenv().__ShinChatSent = true
    local TextChatService = game:GetService("TextChatService")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    pcall(function()
        if TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then
            local channels = TextChatService:WaitForChild("TextChannels", 15)
            local channel = channels and channels:WaitForChild("RBXGeneral", 15)
            if channel then
                channel:SendAsync("Shin Roblox")
            end
        else
            local events = ReplicatedStorage:WaitForChild("DefaultChatSystemChatEvents", 15)
            local say = events and events:WaitForChild("SayMessageRequest", 15)
            if say then
                say:FireServer("Shin Roblox", "All")
            end
        end
    end)
end)

task.spawn(function()
    local waited = 0
    while waited < 90 and not (ShinWin and ShinTabs.farming and ShinTabs.teleport and ShinTabs.fruit and ShinTabs.upgraderace) do
        task.wait(0.5)
        waited += 0.5
    end
    if not ShinWin then
        return
    end
    local last, stable = -1, 0
    while waited < 90 do
        task.wait(1)
        waited += 1
        local n = 0
        for _ in pairs(ShinReg) do
            n += 1
        end
        if n > 0 and n == last then
            stable += 1
        else
            stable = 0
        end
        last = n
        if stable >= 3 then
            break
        end
    end
    local ok, err = pcall(HiruMain)
    if not ok then
        warn("[Shin] Hiru: " .. tostring(err))
    end
end)
end

task.spawn(function()
  local ok, err = pcall(MaruMain)
  if not ok then
    warn("[Shin] Maru: " .. tostring(err))
  end
end)

task.spawn(function()
  local last, stable, waited = -1, 0, 0
  while waited < 90 do
    task.wait(1)
    waited += 1
    local n = 0
    for _ in pairs(ShinReg) do
      n += 1
    end
    if n > 0 and n == last then
      stable += 1
    else
      stable = 0
    end
    last = n
    if stable >= 4 then
      break
    end
  end
  if not ShinWin then
    return
  end
  local store = {}
  local realG = getgenv and getgenv() or _G
  local privG = setmetatable({}, {
    __index = function(_, k)
      if GavzOverlap[k] then
        return store[k]
      end
      return realG[k]
    end,
    __newindex = function(_, k, v)
      if GavzOverlap[k] then
        store[k] = v
      else
        realG[k] = v
      end
    end,
  })
  local env = setmetatable({
    __ShinRedz = makeRedzLib,
    _G = privG,
    getgenv = function()
      return privG
    end,
  }, {__index = getfenv(0)})
  local okEnv = pcall(setfenv, GavzMain, env)
  if not okEnv then
    warn("[Shin] setfenv unavailable, Gavz runs without isolation")
  end
  local ok, err = pcall(GavzMain)
  if not ok then
    warn("[Shin] Gavz: " .. tostring(err))
  end
  task.wait(3)
  ShinWin:Finalize(TabOrder, true)
  task.wait(25)
  ShinWin:Finalize(TabOrder, false)
end)
